window.__D("tolt-5",[[80,"ביאור על הנ\"ל"],[80,"<b>להבין<\/b> שרשי הדברים הנ\"ל. הנה כללות כל הדברים הנ\"ל הוא ע\"פ לשון הקבלה ענין יחוד וזיווג דאו\"א וזו\"נ. ולבאר הדברים בפרטות הוא שלמעלה בחי' מצרים הוא מצר מי. פי' כי מבואר בלק\"ת פ' וישב (ד\"ה ועתה נבאר סוד יוסף) כי הגרון נק' ארץ מצרים כי הוא מקום יותר צר שבכל האדם כי הלא ג' מוחין ברדתן ובהתפשטותן למטה בגוף שם מתרחבים לכל רוחב הגוף בג' קוים. אמנם בהיותם בגרון דהיינו ברדתם מהראש להגרון קודם התפשטותם בגוף שם הם במקום צר עד קצה האחרון ושם הוא סוד מצרים ומהאחוריים היה יניקת מצרים."],[80,"וזה ענין פרעה אותיות הערף. וזהו ופרעה עמד על היאור. כי היאור הוא יסוד דאימא הנמשך דרך הגרון עד חזה דז\"א ובו מלובש מוח הדעת. ופרעה שהוא הערף בחי' גרון עומד על היאר ממש. וענין יצ\"מ הוא יציאת המוחין ממצר הגרון בהתפשטות בגוף ומשם הם נמשכים בבחי' מל' שהיא ארץ טובה ורחבה מקום רחב. משא\"כ הגרון הוא בחי' מצרים מקום צר כנ\"ל:"],[80,"<b>וביאור<\/b> הדברים הנה תחלה צ\"ל מהו ענין הגרון הנקרא ארץ מצרים דקדושה. וענינו הוא שהוא בחי' ממוצע שלהיות המשכת המוחין מן הראש ללב הוא ע\"י אמצעות הגרון דוקא. פי' עד\"מ באדם כשמתהפך מהשכל למדה. דהיינו שמהשכל שמבין איך שאותו דבר הוא טוב. נתהווה מזה אצלו אהבה ותשוקה לאותו הדבר."],[80,"והנה האהבה שנתהוה אצלו שיאהוב אותו דבר הוא מחמת הבנת שכלו שהשיג תחלה בשכלו איך שאותו דבר הוא טוב לפניו ועי\"ז נולדה אצלו מדת האהבה לאהוב לאותו דבר. וזהו ענין התהפכות השכל למדה דהיינו שמבחי' השכל שהשיג תחלה בשכלו איך שאותו דבר טוב נמשך המשכה ללב ונתהפך לבחי' מדה היא מדת האהבה שנולדה בלב מהשכל שבמוח שהולדה זו של המדה הוא מהשכל שנמשך ממוח ללב ונעשה מזה אהבה א\"כ מתהפך השכל למדות."],[80,"והנה זהו בחי' צמצום לגבי השכל שיתהפך למהות אחר ממש שנעשה מדה וע\"ז יש בחי' ממוצע המחבר המוח עם הלב והוא הגרון שהוא הממוצע הגורם שיהיה התהפכות השכל למדה ויתחברו המוח עם הלב. והיינו שבגרון יש בחי' הקנה שנק' שר המשקים (והוושט הוא שר האופים כמ\"ש במ\"א) שממשיך שפע יסוד המים ולחלוחית שבמוח אל הלב כי כל בחי' קנה הוא ענין המשכה מלמעלה למטה. כמו קנה חכמה קנה בינה והוא בחי' הממוצע לחבר שפע השכל שבמוח להתפשט בבחי' מדה בלב. והנה ענין בחי' ממוצע הזה בין השכל למדה הרי אינו לא מהות שכל ולא מהות מדה. ר\"ל דקודם שנמשך השכל בבחי' הגרון בהיותו עדיין במוח הוא בחי' מהות שכל בתכלית והוא רק היותו משיג איך שהדבר טוב. וכן לאחר שמתהפך השכל לגמרי למהות מדה (שהוא לאחר שמסתיים יסוד אימא בחזה כדלקמן) אז השכל נעשה מהות מדה לגמרי ומגדיל המדה וזהו בחי' התפשטות והרחבה. אך בהיות השפע בחי' הממוצע שהוא הגרון דהיינו כשמתצמצם השכל להתהפך לבחי' מדה וקודם התהפכותו שעדיין לא נתהפך ממש כ\"א הוא מתצמצם להתהפך אז הוא בחי' גרון. שהגרון אינו לא ממהות מוחין שבראש."],[80,"ולא ממהות מדות שבלב שאינו מהות שכל שהרי בהיות השפע בגרון היינו שכבר ירד ממהות שכל שבמוח להיות יורד ונמשך להתהפך למהות מדה. וגם אינו מהות מדה שלא בא ⟦נח,ג⟧עדיין לכלל מהות מדה. וזהו בחי' הפסק בין מהות שכל למהות מדה דהיינו ביני לביני ונק' מקום החתך כשירד ממהות הראשון שהיה מהות שכל ולמהותו השני שהיא מהות מדה עדיין לא הגיע (ולכן זהו המקום היותר צר שבכל הגוף דהנה המדות הם בבחי' התפשטות. ויש יותר אפי' מן השכל המולידם וכמשל המעיין שביציאתו הוא דק ואח\"כ כשנמשך בהתפשטות נעשה ממנונהר גדול כו' כך אנו רואים שהמדה מתרחבת מעצמה בבואה בלב יותר מן השכל המולידה כמשל הכועס על חבירו מאיזה טעם שכשמתפשט הכעס בלב מתגדל יותר מכח הטעם שהולידו וכן באהבה כו'. וזש\"ש בלק\"ת שבהיות המוחין בגוף הם בהתפשטות ומרחב יותר מבהיותן בראש. ועמ\"ש בד\"ה ששים המה מלכות בענין נהרא מכפיה מיברך. אמנם עכ\"פ בעודן בראש הם ג\"כ במרחב יותר מכשנמשכין בגרון שאז הן בתכלית הצרות להיות שירדו ממהות שכל ועדיין לא הגיעו למהות מדה רק עומדין להתהפך כו'. ולפיכך הם בתכלית הצמצום שאינן לא מהות זה ולא מהות זה):"],[80,"<b>והנמשל<\/b> מזה יובן למעלה. דהנה ענין יסוד אימא שמסתיים בחזה דז\"א. פי' שאימא הוא בחי' בינה שהוא בחי' השגת השכל. והז\"א הוא בחי' המדות דאצי'. והתהוות המדות הוא מהשכל כנ\"ל במשל. וזהו שיסוד אימא מסתיים בחזה דהיינו מה שנתהפך שפע השכל להיות בחי' מדה (ובמ\"א נתבאר ענין עד החזה להיות כי גם המדות אע\"פ שעיקרן הן בחי' מדות לבד מ\"מ כלולים ג\"כ מג' בחי' חב\"ד חג\"ת נה\"י. והוא בחי' הטעם והפנימי' של החסד ועצם החסד ובחי' ההשפעה שלו ונק' ג' בחי' אלו ג\"כ ג' שלישים. והנה שליש העליון והוא בחי' חב\"ד של עצם המדה ולא חב\"ד ממש וזהו ענין עד החזה ובחי' עצם החסד זהו שליש האמצעי. והוא מהחזה עד הטבור. ובחי' נה\"י של עצם המדה זהו בחי' שליש התחתון מהטבור עד הירכים. והוא מקור לנה\"י של כללות הפרצוף שהן הרגלים. והשליש העליון הוא הפונה למעלה לקבל מעילתו. וזהו שיסוד אימא מסתיים בחזה והיינו שמחב\"ד האמתיים שהן המוחין שבראש נמשך להיות מוחין ובחי' חב\"ד למדות שבלב שזהו ענין השליש העליון. ומ\"מ אנו אומרים שהשכל מתהפך למדה ממש. כי בחי' שליש העליון דהגוף הוא מהות מדה ממש רק שנק' מוחין בערך המדות. אבל לגבי עצם השכל נק' זה שמתהפך למהות מדה ממש):"],[80,"<b>אמנם<\/b> צ\"ל בחי' ממוצע לחבר בחי' יסוד אימא עם המדות שהוא בחי' ז\"א והוא בחי' הגרון ששם מתחילין המוחין להתהפך להיות חיות למדות וירדו ממהותן הראשון שהיו בחי' שכל בחי' גדלות המוחין."],[80,"ועתה בגרון נתצמצם בבחי' קטנות המוחין בכדי להתהפך למדה ולכך שם הוא בחי' מצרים מצר מ\"י. בחי' מ\"י הם נש\"ב הנמשכים במדות כשהם בגרון הם בתכלית המצר והקטנות שהרי הוא בחי' מצר וקטנות לגבי המוחין כשהן בראש כנ\"ל."],[80,"וגם לגבי המדות שבלב שכשנעשה מהות מדה הנה אז השכל מגדיל המדה להיות בהתפשטות רב כנ\"ל. משא\"כ בגרון אינו עדיין מהות מדה בהתגלות וגם אינו בגדלות המוחין ע\"כ זהו מצר יותר מבחי' השכל ומבחי' המדות."],[80,"וזהו מה דאיתא בכהאריז\"ל דגרון וחרן הוא ענין א' כמבואר בלק\"ת ר\"פ ויצא ששניהם בגימטריא אחת. להיות כי בחי' הגרון הוא מצר וקטנות ע\"כ זהו ענין בחי' חרן כי הדינים והגבורות נמשכים מצד קטנות המוחין כנודע ממשל התנוק שאינו יכול כלל לסבול דבר שכנגד רצונו מחמת ששכלו קטן ביותר אבל סבא דעתוהי סתים שיוכל לסבול מה שנגד רצונו ⟦נח,ד⟧מחמת שדעתו מתיישבת מבחי' מוחין דגדלות כמ\"ש בישישים חכמה לכן מבחי' גרון נמשך בחי' חרן:"],[80,"<b>והנה<\/b> בחי' זו שהוא בחי' היות המוחין בגרון הנ\"ל הנק' מצרים הוא בחי' עבור כנזכר בפע\"ח בשער הפסח שבחי' עבור הוא שז\"א הוא כלול תלת גו תלת בבחי' עבור בבטן אימא. שזהו ענין העבור הוא שהגרון מפסיק בנתיים ואין המדות מתגלים בבחי' לידה וגילוי ממש בלב. והוא למטה ג\"כ בעבודה ענין העבור ג\"כ כנ\"ל שהוא בבחי' מצר הגרון. שהוא כשמשיג היטב גדולתו ית' ויש לו אהוי\"ר בהעלם ואינו מוציאן לידי גילוי שיהיו בהתגלות לבו. והוא מחמת שהם בבחינת מעצור הגרון שנשארים שם בבחי' עבור והעלם ואינן באים לידי גילוי בלב כו':"],[80,"<b>וזהו<\/b> ג\"כ ענין הפסוק ופרעה עמד על היאור. דהיינו כשהז\"א הוא בבחי' עבור שזהו סוד מצרים אז נאמר ופרעה עמד כו' כי היאור הוא יסוד דאימא שבו המוחין בבחי' עבור והעלם. והיינו כשהם בבחי' מצר הגרון כנ\"ל ולשם פרעה שהוא הערף עומד ודורך על היאור הנ\"ל ומעכב שלא יהיה הלידה כו'. ובעבודת ה' היינו בחינת רצונות הזרות המעכבים גילוי המדות כו':"],[80,"<b>והנה<\/b> אחר שנתבאר ענין מצרים שהוא הגרון וגלות מצרים הוא בהיות הז\"א בבחי' עבור שם. מעתה יש לבאר ענין יצ\"מ שהוא בחי' לידה דהיינו שהמדות יוצאים לידי גילוי מן ההתבוננות ואז הוא הגדלת המדות."],[80,"והנה המוציאן מבחי' ההעלם שהוא העבור לידי גילוי שהיא הלידה הוא ג\"כ הגרון הנ\"ל כי הגרון ממנו נמשך הקול. והקול הוא המוציא את המדות מההעלם הנ\"ל לידי גילוי. והנה מבואר לעיל איך כי בחי' לידה זו וגילוי זה של המדות הוא ג\"כ בחי' שמחה כי השמחה היא בחי' הגלוי כשהמלך בשמחה הוא מתגלה."],[80,"וענין שמחה זו היא כמ\"ש מה יפית ומה נעמת אהבה בתענוגים ומבואר שם שהיא בחי' כנס\"י שנק' שמחה שהיא בחי' גילוי עלמא דאתגליא. והיא הנקראת ג\"כ אהבה בתענוגים. וביאור שרש הענין הוא דמבואר למעלה שהלידה הוא כשיוצא ז\"א מבטן אימא לידי גלוי. והנה אז מתחיל בנין פרצוף המל' שהיא בחי' הנוקבא כי היא מתחלת מאחורי ז\"א (כנזכר בע\"ח שיש נקב כנגד החזה דז\"א מאחוריו שדרך שם יוצאת המל'. וזהו ענין דודי שלח ידו מן החור) והיינו שמאחורי ז\"א שהוא בחי' החיצוניות מתחיל בנין פרצוף הנוק'. וזהו דשמחה שהיא כנס\"י עלמא דאתגלייא היא מתהווה לאחר לידת ז\"א שאז אח\"כ בהתגלות יסוד אימא בחזה דז\"א שזהו לידת המדות הנק' ז\"א אז מתחיל התהוות פרצוף הנוק'. אך תוכן הענין שיש ב' בחינות בהמל' בחי' חיצוניות ופנימיות כנז' (בזוהר הרקיע) ר\"פ בראשית על מאמר כשושנה כו' כן רעיתי שבחי' חיצוניות המל' דהיינו מה שיורדת לבי\"ע להחיותן זהו ענין שושנה בין החוחים. ובחי' פנימית המל' שאינה יורדת כלל הוא בחי' רעיתי. והנה ענין הנז' בע\"ח דהתהוות המל' הוא מהנקב באחורי ז\"א זה קאי על חיצוניות המל' שהוא בחינת חיצוניות הדבור שהתהוות בחי' זו הוא מהנקב מאחוריו ששרש בנינה הוא מאחורי ז\"א. אבל הפנימית שלה שהוא פנימיות הדבור שרש בנינה הוא מפנימיות ז\"א (ועמ\"ש בזה ע\"פ ששים המה מלכות כו' אחת היא יונתי כו'). ובחי' זו ר\"ל הפנימית שלה נק' כלת משה. שמשה הוא בעלא דמטרוניתא והיא הנקראת ג\"כ כנס\"י שמפנימיות דז\"א הוא מקור של כללות נשמות ישראל ועליו נאמר מה יפית ומה נעמת אהבה בתענוגים וזהו ג\"כ ענין בחי' שמחה:"],[80,"⟦נט,א⟧<b>והנה<\/b> נתבאר לעיל שהמוציאן מן ההעלם שהוא בחי' עבור לידי גילוי שהיא הלידה הוא ג\"כ הגרון והיינו ע\"י הקול שבו. וזהו מה שנת\"ל הקול קול יעקב דהיינו קורא בתורה שע\"י הקריא' בתושב\"כ שנק' מקרא מוציאן מן ההעלם לגילוי שיהיה בחינת לידה שלכך נק' מקרא שהוא ע\"ש הקריאה שקורא בקול להוציאן מן ההעלם שהוא בחי' עבור לידי גילוי שהיא הלידה כנ\"ל."],[80,"ודוקא ע\"י מקרא שהוא תושב\"כ להיות כי ההפרש בין תושב\"כ לתושבע\"פ שתושב\"כ הוא בחי' מוחין דאבא ותושבע\"פ הוא בחינת מוחין דאימא ולכן בתושב\"כ הקפידא על האותיות דוקא שהם מנויים וספורים ושיהיו עשויין כדינן."],[80,"והיינו שהאותיות שבתושב\"כ הם הם רק רמזים על החכ' שאע\"פ שמבין ומשיג בה בתבונתו יותר ממה שכתוב להדיא אינו רשאי להוסיף אותיות לפי השגתו בה יותר. והטעם הוא מפני שתושב\"כ הוא מבחי' מוחין דאבא שהוא בחי' חכמה ולחכימא ברמיזא שצירופי האותיות שלה הם רומזים על איכות המשכת החכמה כמו אל\"ף הוא יו\"ד בראשו ויו\"ד בסופו וקו באמצעיתו."],[80,"והיינו בחי' רמז על ח\"ע וח\"ת שהם יו\"ד דהוי\"ה ויו\"ד דאדני. ולפעמי' היו\"ד שלמטה עושים במקומה דלי\"ת להיות כי המל' שהיא ח\"ת נק' דל. והקו ההולך באלכסון כדמות ו' הוא בחי' ת\"ת המחבר חכמה ומלכות."],[80,"וכן בי\"ת הוא ג' קוין מעלה ומטה וקו הימין והוא ג\"כ רומז על איכות ההמשכה. וכן גימ\"ל הוא קו א' שהוא וי\"ו עם נקודה שהוא י' תחתיו וזה מורה על בחי' היסוד ולכך נק' גימ\"ל שהוא גומל דלים. פי' שגומל חסד ושפע למלכות הנק' דל כמ\"ש אשרי משכיל אל דל כו'."],[80,"וענין הוי\"ו יו\"ד הרי זה דוגמת אות וי\"ו אלא שתמונ' אות וי\"ו הוא יו\"ד וי\"ו להורות על פנימית הטפה דהיא יו\"ד בראשית השפע כו' ונמשכה בשפע הוי\"ו אח\"כ כידוע. משא\"כ גימ\"ל הוא בהפוך הוי\"ו למעלה והיו\"ד למטה להורות על סיום השפע במל' אחרי המשך האור והשפע מן המשפיע כו'. וכן כל האותיות והתגין שעליהם הם הכל רמזים על איכות ההמשכה כו'. והחכמה שבהמשכת אורות אלו זו היא חכמה שבתושב\"כ ואין התגלותה בהתושב\"כ רק ע\"ד רמז ולא באה בגילוי ההשגה וההבנה ממש בהאותיות דתושב\"כ (כי הנה בספורי מעשיות שבתורה כמו מעשה דלבן ומעשה בלק הפשט הנגלה בהכתוב המובן בגלוי מתוך האותיות עם היותו תורה שלימה מ\"מ נק' לבושא דאורייתא בזהר )(ח\"ג דקנ\"ב). אבל גופי תורה הם המתלבשים בהלבושים ואינן מתגלים בהאותיות להדיא אלא ע\"ד לחכימא ברמיזא. ועל זה אמר דוד גל עיני ואביטה כו' שיבין מתוך הרמזים את החכמה. ויש בבחי' התורה ג\"כ נשמתאלנשמתא."],[80,"ועמ\"ש הרמ\"ז שם עד\"מ פסוק ואלה המלכים ודאי מעשה שהיה כך היה אבל בה נגנזו סודות עולם התהו לכן בקצתן נאמר שם עירו וקצתם לא. ובאחרון נזכר שם אשתו. ועוד כמה שינויים שלענין הספור לא מעלים ולא מורידים וכפי הסוד רומזים ענינים נפלאים כמ\"ש בכהאריז\"ל בע\"ח ואוצ\"ח. נמצא האותיות והפסוקים דתושב\"כ הם הכל בחי' רמיזות על החכמה ולא בחי' גילוי שכל באותיות ע\"ד שהוא בתושבע\"פ כדלקמן. שהרי גילוי השכל שבתושב\"כ זהו נק' לבושא דאורייתא כנ\"ל והלבוש מתגלה אבל אפי' גופי תורה שהם פרטי הדינים וכ\"ש הסודות הנק' נשמתא דאורייתא ורזא דרזין שהם נשמה לנשמה אינן מתגלים כלל באותיות דתושב\"כ רק ע\"ד לחכימא ברמיזא."],[80,"והיינו לפי שתושב\"כ נמשכה מח\"ע שהיא למעלה מבחי' גילוי בהאותיות ממש שגילוי השכל באותיות זהו מבחי' בינה כדלקמן. אבל מהחכמה א\"א להיות הגילוי רק בבחינת רמיזא וזהו לחכימא ברמיזא. ולכן אין רשאי להוסיף אף אות א' לפי תבונתו והשגתו ⟦נט,ב⟧יותר כו' מאחר שאין החכמה באה לידי גילוי ממש בהאותיות א\"כ אין שייך להוסיף אותיות מחמת רבוי ההשגה כו' ויפסול עי\"ז את התורה. שהרמז צ\"ל דוקא כמו שהוא בתושב\"כ שקבל משה מפי הגבורה."],[80,"ויצא לנו מזה שתושב\"כ נמשכה מבחי' ח\"ע הוא בחי' מוחין דאבא ולכן נקראת מוסר אביך. ותושבע\"פ נק' תורת אמך. ולכן דוקא ע\"י מקרא שהוא תושב\"כ בחי' מוחין דאבא מוציא מההעלם לגילוי שזהו ענין הקל קול יעקב שבגרון קול הקריאה דתושב\"כ מוציא מן ההעלם לידי גילוי. אבל תושבע\"פ הוא בחי' מוחין דאימא שהוא בינה (ע' ע\"פ גן נעול ענין בינה יתירה ניתנה באשה) היא מקור לצירופי האותיות (שהם פתוחי חותם) כמו למשל בנפש האדם שהתהוות צירופי האותיות הוא מן השגתו והבנתו שלפי ההבנה כמו\"כ ממש מתרבים צירופי האותיות שכשהשגתו והבנתו היא רחבה אזי גם צירופי האותיות הן מרובים. ואם הבנתו קצרה אזי האותיות מועטים. שהאותיות הן כלים לאור ההשגה וההבנה. שההשגה וההבנה מתגלה בהאותיות לכך לפי ערך רבוי האור כך הוא רבוי הכלים. (משא\"כ בחי' חכמה שלמעלה מההשגה אינה מתגלית ממש תוך האותיות רק ע\"ד לחכימא ברמיזא הילכך אין האותיות מתרבים כו' כנ\"ל) וכמו\"כ למעלה שתושבע\"פ נק' מוסר אמך להיותה מבחי' מוחין דאימא דכמו שמטפת האב נעשה בבטן האם ולד ברמ\"ח איברים כו'. כך מפסוק א' בסכת תשבו נעשה בתושבע\"פ מסכת סוכה. ופירש\"י ותוספות ופוסקים. והיינו להיותה בחי' אימא שהיא ההשגה. ולכן היא הנקראת ארץ טובה ורחבה:"],[80,"<b>וזהו<\/b> שנקראת ג\"כ ארץ הצבי שדומה לצבי שאין עורו מחזיק את בשרו שכשנלקח הבשר ממנו מתכווץ העור. אבל כל זמן שהבשר בו אזי כל זמן שהבשר הולך וגדל כמו\"כ מתגדל עורו. והוא המשל לתורה שבעל פה שהיא מוחין דאימא בחי' מוח ההבנה המתלבש בהאותיות בבחי' אור וכלי בגילוי הילכך כל מה שמתרבה ההשגה ממילא מתרבים האותיות. וכמו שאנו רואים שבמשנה האותיות מועטים לפי ששם עדיין ההבנה בקצרה. אבל בתלמוד שנתוסף ההבנה וההשגה בהרחבה גדולה (כי תלמוד בבריאה ששם מתלבשים חב\"ד דאצי' ומשנה ביצי' כו') לכך נתרבו שם צירופי האותיות מאד. וזהו שנק' ארץ טובה ורחבה שמתרחבת עד אין קץ שכל מה שתלמיד ותיק עתיד לחדש בכלל תושבע\"פ יחשב ואזי מתרחבים האותיות כו'. ולכן אין בתושבע\"פ הקפידא על האותיות כמו בתושב\"כ. שהמשנה מדברת בלשון זה וברייתא בלשון אחר. וכן גמרא בלשון אחר והוא מטעם הנ\"ל שעיקר התושבע\"פ היא ההבנה וההשגה והאותיות הם מתרבים ומשתנים לפי ההשגה כו'. (וכ\"ז להיות בתושבע\"פ ההשגה בגילוי באותיות והיינו מבחי' מוחין דאימא. משא\"כ תושב\"כ שהיא מבחי' מוחין דאבא שאין מתגלים בהאותיות רק שהאותיות הן רמיזות ע\"כ הרמיזות הם דוקא כך וכך ולא ישתנו מחמת רבוי הבנתו וכנ\"ל). (וזהו שבינה נק' ג\"כ רחובות הנהר ועמ\"ש בפ' לך לך גבי ה' דאברהם שכדי להיות ההרחבה וההתפשטות שרשו ממקום עליון יותר מהחכמה דהיינו מבחי' קוצו של יו\"ד שהוא בחי' כתר שלמעלה מהחכמה. ועד\"ז יובן ג\"כ בתושבע\"פ שהוא בחי' הבינה להבין הענין בהרחבה שרשה גבוה מתושב\"כ שהיא בחי' חכמה):"],[80,"<b>והנה<\/b> כמו שבבינה שהיא נק' תושבע\"פ נק' ארץ טובה ורחבה מצד התרחבות צירופי האותיות. כמו\"כ הוא ממש מבחי' מלכות נוק' דזעיר אנפין שהיא נקראת גם כן ארץ טובה ורחבה שהיא היא עיקר בחי' תורה שבעל פה כמאמר התיקוני זהר הידוע ⟦נט,ג⟧מלכות פה תושבע\"פ קרינן לה. כי תושב\"כ ותושבע\"פ ע\"ז נאמר חכמות בחוץ תרונה ב' חכמות חכמה עילאה היא בחי' תושב\"כ וח\"ת היא בחי' תושבע\"פ והיא הנק' ארץ טובה ורחבה. שהיא מתרחבת מאד לפי השראת האור א\"ס ב\"ה בתוכה. פי' כידוע בכהאריז\"ל שבזאת משונה המל' מכל הספירות שיש בה שינויים רבים שפעם מתרחבת מאד ופעם מתקצרת ביותר."],[80,"ויש רבוי בחינות בענין התרחבות זאת והשינויים האלו הן ממש בכלים דבחי' מל'. דהיינו פעם היא רק נקודה תחת היסוד. ופעם מתגדלת עד בחי' נה\"י. ופעם עד חג\"ת כו'. ולפעמים מתרחבת עד שהן שוין בקומתן."],[80,"וכל סבת השינויים האלו בהכלים תלוי הכל מצד השפעת והמשכת האור מא\"ס ב\"ה בה. שבהתמעט גילוי האור אז גם הכלי מתמעט להיות רק נקודה חדא וע\"ז נאמר שחורה אני כו' בבחי' נקודה חדא."],[80,"וכשמתרבה גילוי האור אזי גם הכלי מתרבה ממש הכל לפ\"ע גילוי האור. וזהו שנקראת ארץ צבי שגידול והתפשטות העור הוא תלוי לפי גידול הבשר שבהתמעטות והסתלקות הבשר נתכווץ העור. וזה מורה על ענין הנ\"ל שבמלכות שרבוי ומיעוט הכלים תלוי לפי רבוי ומיעוט האורות ע\"כ יש שינוים רבים בגידולה ובקומתה עד\"מ שהם הכלים משא\"כ בשאר הפרצופים שאין שינויים כלל בענין הכלים שלהם."],[80,"והשינויים בשבת ויו\"ט הוא בענין הוספת האור כו'. אבל הכלים אין בהם רבוי ומיעוט. כי או\"א אינן מתרחבים ומתקצרי' לעולם כי אין בהם שינוי לעולם בהכלים. וגם המדות הנק' ז\"א ג\"כ אינו מתרחב ומתקצר כ\"א כשנשפע להם מוחין דיניקה מלמעלה מקבלים הם המוחין או לא נשפע להם המוחין אבל הם המדות בעצמן אינן מתקצרים ומתרחבים כמו המל' שהיא בעצמה יש בהם שינויים. הרי הכלים דמל' תלוי התפשטותן בהתפשטות האורות."],[80,"וזו מעלה יתירה בכלים דמל' שבטלים לגמרי לגבי האורות וזהו שנק' ארץ טובה ורחבה שמתרחבת לפ\"ע רבוי האור כו'. וזהו היתרון בעסק התושבע\"פ אפילו על בחי' אהבה בתענוגים. ששמחה ואהבה בתענוגים היא בחי' יש ודבר. שהשמחה הוא בהתגלות הלב שמרגיש השמחה והתענוג בלבבו והיא בחי' יש ודבר. אבל בתושבע\"פ האור מוסתר ואין נרגש התענוג לכך היא נעלה שהיא בחי' מ\"ה תכלית הבטול בלי הרגשה כלל."],[80,"וזהו שאמר והוצאתי אתכם מתחת סבלות מצרים שהיא היציאה וגילוי המדות מהגרון ע\"י קול תורה שבכתב אזי אח\"כ והבאתי אתכם אל הארץ תושבע\"פ שיש בה מעלה ומדרגה יתירה בהיות' ארץ צבי כו' טובה ורחבה כנ\"ל:"],[80,"<b>ועתה<\/b> יש לבאר ענין ונתתי צבי בארץ החיים. והוא עוד מעלה בענין תושבע\"פ. והיינו עוד טעם שני למה שנקראת ארץ צבי. כי פי' צבי הוא הרצון (מלשון צביוני וכן לצביונן נבראו הקב\"ה שאל להם רצונכם שאברא אתכם וכן ולא אביתם תרגום ולא צביתון כו'. וכן בלה\"ק ג\"כ פירושו חפץ או הדר ופאר כמבואר בספרים) והיינו שרצונו העליון ית' (וחפץ הוא פנימיות הרצון כנודע) הוא מלובש ומתגלה בארץ החיים דוקא שהיא התושבע\"פ. וזאת עוד מעלת התושבע\"פ על התושב\"כ שתושב\"כ מקרא הוא בחי' מוחין דאבא בלבד שהוא בחי' חכמה. אבל אין בה כ\"כ גילוי רצון העליון ממש שלמעלה מהחכמה. שהרי א\"א להבין ולהורות איזה פסק דין שהוא רצון העליון לזכות או לחיוב אסור או מותר כו' מן התושב\"כ שא\"א להבין ממנה הפסק דין שהוא רק בחי' חכמתו ית' בלבד. אבל תושבע\"פ בה מלובש ומתגלה רצון העליון ב\"ה שהוא ענין פסקי הדינין שבתושבע\"פ אסור מותר שזהו רצון העליון ב\"ה."],[80,"וזהו ונתתי צבי בארץ החיי' דוקא שגילוי הרצון העליון ⟦נט,ד⟧הוא בתושבע\"פ דוקא. והוא מפני שסוף מעשה הוא דוקא במחשבה תחלה ונעוץ תחלתן בסופן ולכן נק' המלכות א\"ח עטרת בעלה ונק' ג\"כ ארץ חפץ ע\"ש גילוי הרצון בה דוקא (וכמו בארץ הגשמית גילוי כח הצומח שהוא בחי' א\"ס לברוא מאין כו' כמ\"ש באגה\"ק איהו וחיוהי ובמאמ' א\"ח עט\"ב. והנה בתושבע\"פ ג\"כ יש אגדות ופסקי דינין ובאגדות ג\"כ רק מלובש ח\"ע. אבל בהלכות ופסקי דינין מלובש רצה\"ע ולכן לימוד דהלכות נעלה יותר טובא מלימוד האגדות כדאיתא בגמ' דסוטה דף מ'):"],[80,"<b>אך<\/b> עם היות שיש מעלו' ומדרגות יתירות בתושבע\"פ על תושב\"כ שנק' ארץ טובה ורחבה וגם בה גילוי רצה\"ע עכ\"ז מצד אחד היא למטה במדרגה יותר שנשפלה מאד למטה בגשמיות ומדברת רק בענינים גשמיים (ועמ\"ש בפרשת בראשית). אך על זה נאמר והבאתי אתכם אל הארץ אשר נשאתי את ידי כו'. כמשל היד שמגביה בה החפץ המונח למטה ויכולה היא היד להגביה למעלה מן הראש ויכולה להניח על הראש כמו\"כ המלכות הנק' תושבע\"פ היא בחי' הארץ שעם היות שנתלבשה בגשמיות אבל נשאתי את ידי להגביה אותה למעלה ראש מבחי' ח\"ע כי היא בחי' אשת חיל עטרת בעלה. שהיא בחי' עטרה וכתר לז\"א."],[80,"והיינו מטעם הנ\"ל דונתתי צבי בארץ החיים שבה גילוי רצה\"ע כו'. והכתר הוא למעלה מן המוחין שבראש כנודע. וזהו אשר נשאתי את ידי. פי' ידי הם הזרועות דא\"א שהם חג\"ת דא\"א שהם מכינים את המל'. כמ\"ש מקדש אדני כוננו ידיך:"],[80,"<b>וזהו<\/b> והיית עטרת תפארת וגו' וצניף מלוכה בכף אלהיך. פי' הצניף מלוכה שהוא המל' היא עטרת תפארת כנ\"ל פי' עטרת בעלה. בכף אלקיך שזהו ע\"י אשר נשאתי את ידי זרועות דא\"א."],[80,"וזהו לתת אותה לאברהם ליצחק וליעקב. שהאבות הן חג\"ת דז\"א ומעלה יתירה היא להם שניתנה להם הארץ משום דהיא א\"ח עט\"ב כתר לז\"א כנ\"ל. והיינו מעלת ומדרג' התושבע\"פ. ונתתי אתה לכם מורשה שיהיה מוסתר בה האור שזהו תכלית הבטול שאין נרגש כלל הבטול ובזה גבוה הוא אפי' מבחי' אהבה בתענוגים שהוא בחי' יש ודבר שנרגש השמחה בלב. אבל הלימוד כשהוא בבחי' בטול ע\"ד אני המשנה המדברת בפיך הוא בטול ממש בלי שום הרגשה כנ\"ל."],[80,"וזהו מתניתין מלכתא כנודע. וזהו לתת אותה לאברהם. כי אברהם בחי' אהבה והארץ שהיא תושבע\"פ גבוה יותר אפי' מבחי' אהבה בתענוגים. נמצא המתבאר בפסוק זה הוא למעל' כללו' ענין יחוד דאו\"א וזו\"נ וכן בחי' אלו הן הן ממש בעבודת ה' בכל יום שהאדם יש בו כל בחינות אלו."],[80,"ולכן בכל יום בבקר ובערב מזכירין יצ\"מ כי תחלה יש בחי' גלות מצרים שהוא עבור ז\"א בבטן אימא והוא בחי' מצרים מצר הגרון ואח\"כ ע\"י אמר לבני ישראל אני ה' שהוא עסק התורה שבכתב הנק' תורת הוי' הוא הלידה וזהו לשון מקרא שהוא קורא ומוציא אותן מההעל' אל הגילוי. אך כמו הלידה הגשמית א\"א בלא חבלי לידה ויסורין כמו\"כ צריך להרגיש כאב וצער על מניעת גילוי שם הוי' בלבו."],[80,"ועי\"ז יהיה הלידה שהוא השמחה ותענוג כמ\"ש אם הבנים שמחה. ולמעלה היינו לידת ז\"א ולמטה בנפש גילוי המדות אהוי\"ר. ויוצא דם נדה שנדחין כל המחשבות זרות ע\"י הלידה כו'. ואח\"כ והבאתי אתכם אל הארץ ענין זה למעלה מה שמבחי' ז\"א יורד ההשפעה למל' ונק' ארץ כנען שמכניע כל החיצונים ונמתקים כל הדינים מפני שע\"י הלידה שהוא בחי' גדלות אין יניקה לחיצונים. אבל מבחי' עבור וקטנות יש להם יניקה כמבואר במ\"א."],[80,"ולמטה הארץ היא בחי' תושבע\"פ והיא אשר נשאתי את ידי כי אשת חיל עטרת בעלה והיית צניף מלוכה כו' וכנ\"ל. ⟦ס,א⟧ולהיות נודע שבכל יום נמשכין מוחין חדשים למעלה וכן בנפש האדם כמ\"ש חדשים לבקרים כו' שנעשה בריה חדשה ע\"כ צ\"ל בכל יום יצ\"מ שההמשכה ממוחין למדות הוא ע\"י מצר הגרון והיינו ע\"י תושב\"כ ואח\"כ והבאתי אתכם אל הארץ היא התושבע\"פ הנק' ארץ חפץ כנ\"ל:"],[81,"⟦ס,א⟧<b>בעצם היום הזה יצאו כל צבאות ה' מארץ מצרים.<\/b> הנה ארז\"ל על חנה מיום שברא הקב\"ה את עולמו לא היה אדם שקראו להקב\"ה צבאות עד שבאת חנה כו'. דהיינו שהיא פתחה תחלה לקרות הקב\"ה הוי\"ה צבאות ואמר הקב\"ה עתיד בן שלך לפתוח בנבואה בשם זה כמ\"ש ויאמר שמואל כה אמר ה' צבאות פקדתי כו'. והנביאים האחרונים נבאו בשם זה ובפרט חגי זכרי' ומלאכי יותר מכולן. וקיי\"ל (ספ\"ד דשבועות) דצבאות הוא מן השמות שאינן נמחקין. והנה מתחלה יש להקדים ענין השמות מהו. גם מעלת שם המיוחד שם הוי\"ה על שאר השמות ואח\"כ ית' אי\"ה ענין שם צבאות. הנה ידוע שמהותו ועצמותו של הא\"ס ב\"ה הוא פשוט בתכלית הפשיטות ולא שייך כלל במהו\"ע ענין התוארים שנמצאו שכינו לו ית' בתורה ובדברי הנביאים ובדברי רז\"ל כמו חכם חסיד רחמן כו' וכיוצא בהן. כי הוא ית' מרומם ונשגב ומובדל מכל גדרים אלו שהחכמה שהיא המעלה הראשונה בנבראים היא נחשבת כעשיה גשמי' לגבי מהותו ועצמותו ית'."],[81,"ומכ\"ש בחי' המדות וכמאמר דלאו מכל אלין מדות איהו כלל וכנודע. ואעפ\"כ יש מציאות ענין התוארים הללו שבאו בתנ\"ך ובדחז\"ל. דהיינו ע\"ד מארז\"ל במקום שאתה מוצא גדולתו כו' שם אתה מוצא ענותנותו שהוא ית' משפיל א\"ע להיות מתלבש בעשר כלים דאצילות שהן בחי' חו\"ג כו'."],[81,"וג\"ר חב\"ד ואז שייך לקרותו בתוארים שנק' חכם מצד התלבשותו בחכמה וכמאמר אליהו אנת חכים פי' שמספר בענותנותו שמשפיל א\"ע להתלבש בבחי' כלי החכמה עם היות שהחכמה אין ערוך אליו כלל כנ\"ל. וכן משפיל א\"ע להתלבש בבחי' חסד ונק' אז הגדול או חסיד וזהו שהגדולה היא ענותנותו שע\"י ענוה והשפלה שהשפיל א\"ע להתלבש במדת חסד אז דייקא שייך לקרותו גדול משא\"כ מהו\"ע מרומם מגדר זה כנ\"ל."],[81,"והנה שמותיו של הקב\"ה הם הכלים דע\"ס דאצי' שמתלבש בהן אוא\"ס ב\"ה ומתייחד עמהן בתכלית היחוד ע\"ד דאיהו וגרמוהי חד היינו שם אל הוא בבחי' כלי החסד. ושם אלקים בבחי' כלי הגבורה ושם אדנ\"י בבחי' מל'. אמנם שם הוי\"ה הוא הפנימיו' של כל השמות שהם הכלים. כי הוא בבחי' האורות המתלבשים בתוך הכלים דהיינו בבחי' אל שהוא השם שבכלי החסד. הנה בבחי' האור הנמשך מא\"ס ב\"ה להתלבש בו הוא בחי' שם הוי\"ה."],[81,"וכן גם בבחי' שם אלקים שבכלי הגבורה מתלבש בתוכו שם הוי\"ה שהוא בבחי' האור מא\"ס המתלבש בתוך הכלים הנ\"ל. ועד\"ז בכל השמות שאינן נמחקין שהם בבחי' הכלים. ושם הוי\"ה הוא בבחי' האורות המתלבשים בהן. ולכך שם הוי\"ה מצטרף עם כל השמות כמ\"ש ביום עשות הוי\"ה אלקים ארץ ושמים כו' וכתיב הוי\"ה צבאות כו' מפני שבחי' שם הוי\"ה הוא הממשיך את האור א\"ס להתלבש בשמות אלקים וצבאות שהם הכלים כו' שהוא הממוצע בין אורות וכלים ולכך הוא המחבר האורות עם הכלים:"],[81,"<b>והנה<\/b> כתיב זה שמי לעלם וזה זכרי כו'. ופי' בת\"ז שמי עם י\"ה שס\"ה ל\"ת. זכרי עם ו\"ה רמ\"ח מ\"ע. והיינו שכללות התורה רמ\"ח מ\"ע ושס\"ה ל\"ת הם מושרשים בשם הוי\"ה שהוא בחי' ז\"א דאצי'. רמ\"ח מ\"ע נמשכים מבחי' החסדים שבז\"א ושס\"ה ל\"ת ⟦ס,ב⟧מבחי' הגבורות שבז\"א ובהם נכללים כל פרטי הדינים דאו\"ה כשר ופסול חייב וזכאי כו'. שההיתר והכשר נמשך מבחי' החסד דז\"א והעובר אל\"ת ממשיך עליו מבחינת הגבורות להיות נענש כו' ואור א\"ס ב\"ה הוא מלובש בכלים דז\"א עד דאיהו וגרמוהי חד כדלעיל וזהו בחי' שם הוי\"ה."],[81,"ובזה יובן מה שבכל התורה לא נזכר שם צבאות רק שם הוי\"ה לבדו רק חנה אמרה ה' צבאות. כי מרע\"ה שזכה שתנתן התורה על ידו היינו לפי שהמשיך התלבשות אור א\"ס בכלים דז\"א. ומשם נמשך התורה כנ\"ל (ומשם היתה נבואתו כי עיקר נבואתו היתה מאצי' רק דרך מעבר נמשך על ידי הבריאה כמ\"ש בשער הקדושה להרח\"ו ח\"ג שער ו') אבל לא המשיך שיהיה ג\"כ התלבשות אור א\"ס בבי\"ע ע\"ד שהוא מתייחד עם כלים דאצילות כך יהי' מתייחד עם כלים דבי\"ע זה לא המשיך משה ולא הוצרך לזה כי המשכת התורה המשיך מבחי' אצילות ממש. ושם מתייחד אור א\"ס עם הכלים עד דאיהו וגרמוהי חד כנ\"ל. משא\"כ בבי\"ע אין הגילוי כלל בהכלים (ולאו איהו וגרמוהי חד בהון כנודע) אבל הנביאים שאחריו המשיכו את אור א\"ס ב\"ה שיתלבש ג\"כ בכלים דבי\"ע מה שלא היה כן בימי מרע\"ה. והיינו שחנה פתחה תחלה בשם צבאות ואחריה נמשכו כל הנביאים שענין שם זה הוא מורה על ענין התלבשות אור א\"ס בכלים דבי\"ע להיות מתייחד עמהם ג\"כ וכמשי\"ת אי\"ה."],[81,"והוצרכו לזה כי בימי מרע\"ה שהיתה נבואתו מאצילות ע\"כ המשיך להם למטה התורה משם מבחי' אצילות והוא היה דבר ה' בפי משה וקיימו ישראל התורה כו'. אבל בימי הנביאים שאחריו שלא היו ישראל עושין רש\"מ והוצרכו הנביאים להוכיחם."],[81,"וענין ההפרש בין תוכחה שאומר הנביא לשאר מוכיח הוא כי בהנביא הנה התוכחה היא דבר ה' המתלבש בדבורו של הנביא ונמצא הוא ית' הוא המוכיח. ולזאת הוכרח להיות המשכת התורה מאצילות לבי\"ע כדי שיקיימו ישראל התורה כי בהיותה באצילות כבימי משה לא היו מקיימים אותה ישראל שבימי הנביאים אחר דורו של משה מצד שנשגבה מהם והית' התורה בפ\"ע והאדם בפ\"ע."],[81,"ולכך היה צ\"ל התלבשות התורה מאצי' לבריאה ונמשך שם דבר ה' בפי הנביא להזהיר את ישראל שיקיימו התורה כו'. והגיע להם עי\"ז התוכחה מדבר ה' ממש המתלבש בכלים דבי\"ע ומשם בפי הנביא כו':"],[81,"<b>והנה<\/b> הגם שאין נביא רשאי לחדש דבר. אך אין זה חדוש ותוספת על תורת מרע\"ה. רק המשכת התורה בלי תוס' וגרעון מאצילות לבריאה. וזהו ענין שם צבאות שנז' בנביאים כי צבאות הוא לשון חיילות. והם גדודי נשמות ומלאכים דבריאה אשר אין מספר לגדודיו והם נבראים ומחודשים מאין ליש ממש. ואינן אלהות כלל כמו אצילות שהוא בחי' אלהות ממש ואעפ\"כ הנביאים המשיכו שיתלבש בהם אור א\"ס ב\"ה בתכלית היחוד כמו שנתלבש בכלים דאצי' עד דאיהו וגרמוהי חד עד שיהיה נק' האור א\"ס המלובש בהם בשם צב(אות שהוא שם התואר שהוא עצמו הוא בחי' הצבאות ממש כענין איהו וגרמוהי חד שבאצי' שהוא עצמו הוא הדעה כו'. כך מתייחד בכלי' דבי\"ע עד שהוא עצמו הוא הצבאות כו'. ולא שהם נפרדים בפ\"ע רק שבטלים אליו אלא שמתייחד עמהן ממש. וכמשל יחוד וחבור הנשמה עם הגוף שהגם שהגוף הוא הכלי והעיקר היא הנשמה עכ\"ז מתאחדת עם הגוף שנק' אדם הנשמה שבגוף ואין להגוף שם בפ\"ע כו' וכהדין קמצא דלבושי' מיניה וביה. וכמו שקורין לאדם שלמד חכמה בשם חכם הנה החכמה קודם שלמדה היא מהות בפ\"ע זולת האדם שלמדה והאדם מהות בפ\"ע. וכשקנה החכמה נק' חכם ע\"ש החכמה שהוא שם התואר. כך עד\"מ למעלה עם היות הכלים דבי\"ע הם מהות בפ\"ע בחי' נשמות ומלאכים נבראים רק שבטלים אליו ית'. אך עכ\"ז ע\"י שהמשיכו הנביאים להיות גלוי אוא\"ס ב\"ה בהם ע\"ד יחודו באצי' אז נק' הוא ית' הוי\"ה צבאות שהוא שם התואר שהוא ית' הוא אחד עם הצבאות הנ\"ל ואינן נפרדים כו'. ולכן שם הוי\"ה מצטרף לשם צבאות כי שם הוי\"ה הוא באצי' והוא המשכת אוא\"ס בכלי' דאצי' ואם כן כדי שיתמשך אור א\"ס בבי\"ע הוא על ידי שם הוי\"ה בתחלה וזהו הוי\"ה צבאות. ולאחר שהמשיכו הנביאים בחי' זו אזי הוכיחו את ישראל בשם זה כי מבחי' זו שבבריאה נמשך הנבואה להנביא דבר ה' ממש הוא המוכיח את ישראל ולא דמי כלל לשאר מוכיח כו' שהיא תוכחת הנברא וזוהי תוכחת הבורא ית' ממש. והכח להמשכה זו שיהיה אור א\"ס מתלבש בבי\"ע ע\"ד הנ\"ל כבאצי' המשיכו הנביאים מבחי' העיגול והסוכ\"ע אשר שם כחשכה כאורה שוין השוה ומשוה קטן וגדול שהוא דוקא יכול לישפל א\"ע למטה מטה גם בבי\"ע כי קמי' ית' כולם שוים וכמ\"ש ומתחת זרועו' עולם )(ובזה יובן מ\"ש בחנה ותתפלל על ה' כו' ותאמר הוי\"ה צבאות שכדי להמשיך בחי' צבאות הוצרך להמשיך מבחי' על הוי\"ה היינו למעלה משם הוי\"ה כמבואר הפי' בזה במ\"א. ע' בפ' משפטים ע\"פ לא תהי' משכלה ועקרה כו'):"],[81,"<b>וז\"ש<\/b> בעצם היום הזה יצאו כל צבאות וגו'. פי' צבאות הוי\"ה הוא לשון סמוך שהצבאות נטפל לשם הוי\"ה אבל אינו לשון שם התואר כמו הוי\"ה צבאות. והיינו בחי' הנצוצים שנתבררו בגלות דמצרים ונתעלו ליכלל בשם הוי\"ה הם הנק' צבאות הוי\"ה כי רפ\"ח נצוצים נפלו בשבה\"כ ומזה נתברר בגלות מצרים ר\"ב נצוצים וע\"ז נאמר וינצלו את מצרים."],[81,"וז\"ש וגם ערב רב עלה אתם. וכתיב רב לך כו'. ופי' וענין שנק' צבאות הוי\"ה בחי' טפל וסמוך לשם הוי\"ה. הענין כי מספר רפ\"ח נצוצים הם מבחי' שמות ע\"ב ס\"ג מ\"ה ב\"ן כו'."],[81,"וכאשר נתבררו מבי\"ע לחזור לשרשם אז אינם נקראים בשמות אלו כלל מפני שנתכללו במקורם בתכלית היחוד לכך אינם עולים בשם כלל. והמשל בזה כשהאדם משכיל בגדולת ה' בהתבוננות והשגה אזי נרגשת ההשגה בבחי' יש ודבר. אבל כשנתבטל במציאות לגמרי אז אינו מרגיש ההשגה והבטול בבחי' יש ודבר מה כ\"א הוא בטל לגמרי בתכלית הבטול בלי הרגשה כלל. כך עד\"מ הנצוצים דתהו שנפלו בשבירה יש להן שמות שזה מורה בחי' יש ודבר עד שנק' בשם שזהו הגילוי לזולתו כמו האדם שבפ\"ע א\"צ לשם רק שחבירו קוראו בשם."],[81,"וכיון שנתבררו וחזרו למקורם בתכלית הבטול להתכלל באלקות אזי אין להם שמות כלל. ולכן נק' אז צבאות הוי\"ה שהם טפלים וסמוכים ונכללים בשם הוי\"ה ופי' הוציא ה' את בני ישראל על צבאתם היינו שנש\"י הן למעלה מבחי' ניצוצין הנ\"ל:"],[82,"<b>למען תהי' תורת ה' בפיך כי ביד חזקה הוצאך ה' ממצרים.<\/b> ולכאורה הוא תמוה וכי מה ענין התורה ליצ\"מ להזכירם. ⟦ס,ד⟧ולהבין ענין התורה דהנה כתיב וידבר הוי' אל משה לאמר קדש לי כל בכור ובאמירת משה כתיב ויאמר משה אל העם זכור את היום הזה אשר יצאתם ממצרים כו' וכמוהו רבים במקרא. ולהבין זאת ביאור מצות והגית בו יומם ולילה ואף שיש כמה דינים שאינן נוהגין בזה הזמן והנהוגים אינם שוה לכל נפש:"],[82,"<b>אמנם<\/b> הנה יש ב' מיני אהבות. יש אהבה שנמשלה למים כדכתיב מים רבים לא יוכלו לכבות את האהבה שהולך תמיד בלי שינוי ותוספות ומגרעת כלל כתמול שלשום כמאז כן עתה. ויש אהבה שנמשלה לאש כדכתיב רשפיה רשפי אש כו'. והוא שמתנענע תמיד ברצוא ושוב. וב' אהבות הללו נמשכו מב' דעות שבאדם."],[82,"והנה כתיב בנים אתם לה' אלהיכם שהוא ית' אוהב אותנו כאב את בנו וממיל' נמשך לדעת אותו כמים הפנים כו' והוא כמים דייקא שהולך בתמידות שוה בלי שום שינוי. שכן אהבת האב שעל בנו לא ישתנה לעולם."],[82,"ויש דעה אחרת שמכיר בוראו שהניח כל צבא השמים ושמי השמים העליונים ורצה להיות לו דירה בתחתונים דהיינו שיהי' שכלו הא\"ס ליצמצם בגבולים גשמיים וזאת התורה אשר שם הוא מדבר בדברים גשמיים."],[82,"והכל בשביל אהבתו אותנו שלא כדרך הטבע כי אהבה מקלקלת את השורה והכל מרצונו ית' שכרצונו ית' חכמתו שבשביל שהוא רם ונשא וגבוה מאד יכול להתלבש ביותר גבולי ומצומצם וזהו טעמי מצות שהוא רצונו ית' לא נתגלה כי בלתי אפשר להשיגם עד ביאת משיחנו."],[82,"וזהו נודע בשערים בעלה וגו' מה שיכולי' להשיג את הקב\"ה הוא בשבתו עם זקני ארץ. פי' בשביל שבתו הוא הורדתו והשתלשלותו עם זקני ארץ. פי' החכמה שבארץ דזקן היינו זה שקנה חכמה."],[82,"וזאת ישים האדם אל לבו ויתעורר בו אהבה גדולה מאד שלא לחשוב שום רצון בעניניו רק יבטל רצונו מפני רצון שמים שלא יהיה לו רק רצון א' לעבודת הבורא וכרצונו יעשה השכל ג\"כ שהשכל נמשך אחר הרצון."],[82,"וכמו שמצינו בגמ' גבי שוחד דאמר אי בעי טעין הכי והיינו משום שרצונו נוטה לזה דגם השכל השלים אתו וכמו שהשי\"ת רוצה להיות לו דירה בתחתונים שלא כדרך הטבע להיות א\"ס בלי גבול מוגבל ומצומצם כמו כן יעשה האדם רצונו להפרד מן הגוף והטבע לדבקה בו יתב' ושלא כדרך הטבע. ולכן נאמר והגית בו יומם ולילה. לא ישבות יומם מלראו' לרצונו ית'. וזהו כבודו של מקום באהבתו אותנו מתלבש ומגביל ומצמצם וממנו יראה האדם וכן יעשה וחי כו':"],[82,"<b>וזהו<\/b> למען תהיה תורת ה' בפיך כי ביד חזקה הוצאך כו'. פי' דכ\"מ שנאמר יד אינו אלא ימין (מנחות דף י) שהוא רחמים ונאמר ועברתי בארץ מצרים. פי' שהעביר על מדותיו שעשה דינים במצרים אע\"פ שמדותיו לרחם ולהטיב לברואיו והכל מחמת אהבתו לישראל כמשל האב בעבור אהבתו שרוצה לעשות חסד עם בנו כובש חסדו וכועס על אחרים המצערים את בנו."],[82,"וזהו ביד חזקה שהוא הימין היתה כבושה בכדי להוציאם ממצרים והיה שינוי שלא ע\"פ הטבע לכן תהיה תורת ה' בפיך לעשות רצונך כרצונו וכיון שהכל הוא מרצונו הפשוט הוצרך לצמצם בכדי שיוכל העולם לקבלו. ולכן נאמר פעם ויאמר הוי' אל משה ופעם לא נאמר אמירת הוי' אל משה אלא אמירת משה אל העם כפי כח ויכולת העם שיוכלו לקבל כך צמצם את עצמו והכל גלוי וידוע לפניו באיזה אופן יוכל לצמצם בכדי שיוכל העולם לסובלו:"],[83,"⟦סא,א⟧<b>ויהי בשלח פרעה את העם ולא נחם אלהים דרך ארץ פלשתים וגו'.<\/b> הנה על ישראל בגלות מצרים כתיב וזרעתיה לי בארץ ואמרז\"ל זורע כור מוציא כמה כורים וכו' ולהבין ענין הזריעה והתוספת והרבוי שנתהוה מן הגלות. הנה כתיב קדש ישראל לה' ראשית תבואתה תבואתו דווקא שישראל נקראו תבואת ה' והוא כמו שאדם זורע תבואה ע\"ד משל בשביל התוספת שיצמח. כך ברצות ה' שיתוסף ויתרבה גילוי אלהותו בעולם וימלא כבוד ה' את כל הארץ ונגלה כבוד ה' וראו כל בשר וגו'. זורע את ישראל שהן הם תבואתו ושע\"י יתגלה כבודו ברבוי ותוספת וזהו ברוך ה' אלהי ישראל מן העולם ועד העולם פי' שכדי שיומשך ברכה ותוספת רבוי בגילוי אלהותו מעלמא דאתכסיא לעלמא דאתגליא הוא ע\"י ישראל ולכן נקרא ה' אלהי ישראל שע\"י כן נמצא רבוי גילוי אלהותו למטה כמו למעלה וכשם שלמעלה כתיב וצבא השמים לך משתחוים מפני שהם בטלים ממציאות מגילוי אור ה' המושג להם כך הנה כתיב לעתיד כי עין בעין יראו וגו' וכתיב ובאו במערות צורים ובמחילות עפר מפני פחד ה' וגו' וכמאמר כל ברך לך תכרע כו' ולפניך יכרעו ויפולו כו' והגורם לישראל מעלה ומדרגה רבה זו היא עסק הזריעה בארץ בזמן הגלות שהוא כמו ע\"ד משל שזורעין גרעין אחד ומצמיח הרבה או כמו שנוטעין חרצן אחד וצומח אילן שלם בענפים הרבה וכמ\"ש ואנכי נטעתיך שורק וגו' שהוא זמורה של גפן כדי להצמיח גפן שלם וכמאמר רז\"ל על פסוק והנה גפן לפני שישראל נמשלו לגפן כו':"],[83,"<b>והנה<\/b> כמו במשל הזריעה והנטיעה הנ\"ל שמכסין הגרעין בעפר הארץ ומשם יצמח בעבור שהגרעין נרקב ונפסד ובטל לגבי כח הצומח אשר בארץ וכח הצומח ההוא הוא שמגדל ומצמיח ברבוי ותוספת כך הוא ענין הזריעה של ישראל."],[83,"וביאור ענין זה כי הנה נודע שקליפה קדמה לפרי כדכתיב ואלה המלכים אשר מלכו בארץ אדום לפני מלך מלך לבני ישראל ולא שהקליפה ממש ח\"ו קדמה לפרי אלא שהאור והחיות המלובש בתוכם בבחינת גלות ונפילה שנפלו שמה בשבירת הכלים כידוע ליודעי חן הנה הוא נפל שמה ממדרגות גבוהות ומעלות עליונות מאד מאד למעלה מעלה מבחינת עוה\"ב וישראל אשר נשמותיהם מושרשות במדות הקדושות ואורייתא דנפקא מחכמה הנקרא בחינת עשיה והן הם מעשה המצות וכו':"],[83,"<b>וביאור<\/b> הענין דתנן עשרה דורות מאדם עד נח וכו' ועשרה דורות מנח עד אברהם כו' להודיע כמה ארך אפים לפניו שכל הדורות היו מכעיסין ובאין וכו'. פי' מה שכל עכו\"ם מקבלים שפע וחיות עולם הזה מקדושתו של הקב\"ה וכדכתיב ואתה מחיה את כלם הוא מבחינת ארך אפים ורב חסד דהיינו מפני שהוא ית' כל יכול ומחיה ומשפיע בבחינת רב חסד אף במקום שמכסה ומסתיר על קדושתו ית' וקרו ליה אלהא דאלהיא כו'."],[83,"ולכן יש להם עושר וכבוד שלא ע\"פ חשבון ומעשה ודעת כי יניקתם מחיות אלהי שנפל בקליפות בשבירות הכלים כידוע ליודעי חן והוא מוסתר ומכוסה אצלם וימנע מרשעים אורם שאינו מאיר אצלם בהתגלות כ\"א בחשך כפול ומכופל עד שמכחשים בה' אמר נבל בלבו אין אלקים ונראים ליש ודבר בפני עצמו. משא\"כ בסטרא דקדושה שהם מקבלים חיות מגילוי אור פני ה' והוא מתגלה בירידת והשתלשלות סדר המדרגות בעשר ספירות הקדושות שהן הם מדותיו ית' שהם בחינת כלים להמשכת גילוי אלהותו ית' וכן התורה יש לה מדה וכמ\"ש ארוכה מארץ מדה מפיק ה' פי' מדתה דהיינו שיש לה מדה שהוא מדת בחינת כלי אומנתו ית' אלא שהיא ארוכה מארץ וגו' ולכן כתיב אם בחקתי תלכו וגו'."],[83,"ולכן נקרא יעקב הקטן כי הוא ⟦סא,ב⟧בחינת קטנות וצמצום אלהותו ית' להתגלות ע\"פ מדותיו ע\"י אור התורה והמצות להיות רצונו העליון שאם יטעון ראובן כך כו'. יהיה הפסק כך."],[83,"וכן ע\"ד זה שאר מצות ציצית ותפילין שגילוי אלהותו ורצונו ית' הוא בחינת צמצום שהרי בעצמותו ומהותו ית' לא שייך כלל בחינת רצון שהוא למעלה מעלה מבחינת רצון ונקרא בעל הרצון וע\"ז נאמר הנה השמים ושמי השמים לא יכלכלוך פי' אפילו כמו כלי תוך כלי לקבל חיות מקדושתו של הקב\"ה בבחינ' שקודם הצמצום שיהיה בבחינת התגלות ירידת והשתלשלות סדר המדרגות. משא\"כ בחי' ואלה המלכים כו' שמקבל חיות מקדושתו של הקב\"ה מבחינת ורב חסד שלמעלה מהצמצום ע\"י נפילת האור והחיות וירידתו בסתר המדרגות ממדרגה למדרגה להתלבש בבחינת הסתר פנים ולא בגילוי כלל וכלל עד לעתיד לבא שיקוים בנו מקרא שכתוב ואת רוח הטמאה אעביר מן הארץ וכתיב כי עין בעין יראו וגו':"],[83,"<b>והנה<\/b> אמרז\"ל גלו לבבל שכינה עמהם. פי' הנה ניצוץ אלהות שבנפשם הוא בבחינת גלות והניצוץ אלהות שבתוכם רצונו וחשקו לדבק ולהסתלק למקורו כטבע האש וכו' ועי\"ז הם מלקטים ג\"כ ניצוצי חיות אלהי שנפלו שמה בשבירת כלים ומעלים אותם לקשרם ולדבקם באלהים חיים ע\"י עסקו בפרנסתו בדברים הנתונים תחת ממשלת קליפת נוגה וכמארז\"ל אין לך כל עשב כו' והוא מתרחק משקר וגניבה וגזילה וכיוצא בהם מדברים אסורים וקשורים בידי החיצונים שאינן יכולין לעלות כו' כמ\"ש במ\"א וכן כשמקיים מצות תפילין וציצית שהצמר של ציצית והקלף של תפילין היו נתונים תחלה תחת ממשלת השר והמושל המשפיע להם שפע וחיות להחיותם ולקיימם מחיות קדושתו של הקב\"ה שנפל שמה בשבירת הכלים כנ\"ל ועי\"ז מתעלה ג\"כ חיות הקדושה הנ\"ל למקורם ושרשם ואתהפכא חשוכא לנהורא כמ\"ש וידעו מצרים כי אני ה'."],[83,"וזהו תוספת ורבוי אור זרוע הנזרע בקרקע ומכוסה בעפר הארץ להצמיח ולהעלות מעלה מעלה ברבוי ותוספת אורה כיתרון אור הבא מן החשך וגו' וז\"ש ותקח רבקה את בגדי עשו וגו' ותלבש את יעקב בנה הקטן כי קטן יעקב מבחי' קטנות וצמצום אורו ית' להתלבש במדותיו ע\"פ דרך התורה כנ\"ל."],[83,"והנה התורה נתלבשה בלבושים גשמיים ומעשה המצות בדברים שהיו נתונים תחת ממשלת קליפת נוגה ששרשם מעולם התהו ונק' בגדי עשו בנה הגדול כי עולם התהו קדם לעולם התקון שע\"י זה נתוסף אורה ושמחה כיתרון אור הבא וכו' והשמחה היא כאשר תתהפך חשכת הדברים הנתונים תחת ממשלת ק\"נ לאור התורה ומתעלים בקדושה וכמאמר אשר קדשנו במצותיו בקודש העליון כו' וזהו בחי' תשובה וכמארז\"ל אם ישראל עושין תשובה נגאלין דהיינו בחינת נשיאת הנפש למקורה ושרשה כמ\"ש אליך ה' נפשי אשא בחינת מסירת הנפש מה שהיה נהנה וניזון בנפשו החיונית מכל אכילה ושתיה שהיה תחת ממשלת קליפת נוגה ושארי תענוגי עוה\"ז להתהפך מהפוך להפוך לעבוד ה' בשמחה ובטוב לבב וכמ\"ש תחת אשר לא עבדת וגו' ובכל דחיה ודחיה שישראל מדחה את תאוות גופו ומקרב לבו לעבודת ה' הרי זה בחי' מסירת הנפש כי מה לי קטל' כולה מה לי קטל' פלגא וכן ע\"י הצדקה ממעות שאינן גזל כו' כדכתיב צדקה תרומם גוי והוא כענין וירם קרן לעמו פי' דקאי אדלעיל מניה הודו על ארץ ושמים הודו וזיוו לבד כמ\"ש במ\"א והוא בחינת סוכ\"ע. אבל וירם קרן לעמו למעלה מעלה מבחי' הודו אלא להיות עם קרובו של עצמותו ומהותו כביכול ממש שהוא למעלה מעלה מבחי' סוכ\"ע שאינו בגדר עלמין כלל כו' כמ\"ש במ\"א וזהו אתה בחרתנו מכל העמים שמבחינת כל העמים דוקא בחרתנו ⟦סא,ג⟧רוממתנו כנ\"ל וכמארז\"ל במקום שבעלי תשובה עומדין צדיקים גמורים אין כו' וזהו בחינת בכל מאדך וע\"ד זה נתקן כל ענין התפלה ולכן בזמן שבהמ\"ק היה קיים לא היו מאריכין כ\"כ בתפלה כמו עכשיו:"],[83,"<b>והנה<\/b> כמו במשל שבזריעת הגרעין הנ\"ל שאינו צומח עד שנרקב ויפסד ואז יעלה ויצמח כך א\"א להעלות ולהצמיח תוספת אורה ושמחה בה' כנ\"ל כ\"א ע\"י לב נשבר רוח נשברה רוח הסטרא אחרא הגסה בקרבו שיבא לידי רקבון והפסד וישוב אל ה' וירחמהו על גלות ניצוץ אלהי שנפל בקליפות להחיותם איך שנפל מאיגרא רמא כו' וע\"ד זה תקנו תיקון חצות כדי להיות התפלה בכוונה וכמאמר רז\"ל אין עומדין להתפלל אלא מתוך כובד ראש שיהא מיצר ודואג על בחי' ראש ומעלת קדושתו ית' שהוא כביכול בכובד הגלות אלא שלחסידים הראשונים היה די בשעה אחת בהתבוננו' שעה אחת קודם התפלה אבל לשאר צריכין לקבוע עת וזמן בפ\"ע לעורר מרירות בנפשנו. דהיינו בחצות ואחר חצות לימוד התורה בשמחה ואור הבא מתוך החשך כו' כמ\"ש במ\"א וזהו תחת אשר לא עבדת את ה' בשמחה וגו'. שהוא עונש מדה כנגד מדה לפי שבחורבן בית המקדש נאבד ממנו בעונינו השמחה שלמה שהית' במקום מנוחתה שע\"י זה יעלה ויבא ויגיע לבחינת השמחה ואורה הבאה מתוך החשך כנ\"ל."],[83,"וזה שאמרו רז\"ל על ר\"ע כשראה כרך של עכו\"ם שחק ואמר אם לעוברי רצונו כך לעושי רצונו על אחת כמה וכמה פי' שהשפעת חיות ושפע עולם הזה לעכו\"ם שהם נקראים עוברי רצונו שעובר על הרצון מבחי' למעלה מהרצון כי שם אין העונות מפסיקים ומעכבים את השפע כי אם צדקת מה תתן לו ורבו פשעיך מה תעשה לו. אלא אחר שנתהווה בחי' רצון ורצון אותיות צנור שהוא מעבר התגלות שפע וחיות אלהי דרך צמצום והשתלשלות סדר המדרגות על פי מדותיו ית' ששם הוא על פי דרכי התורה אם בחקתי תלכו וגו'. אבל למעלה הוא כחשיכה כאורה ומשם הוא יניקת עכו\"ם דרך נפילת האור שמרחוק כנ\"ל אף שהם רחוקים מאור פניו ית' המתגלה כנ\"ל וכ\"ש לעושי רצונו דהיינו העושים הרצון וממשיכין שפע וחיות אלהי דרך צנור המתגלה בהשתלשלות המדרגות שהרי הם עליונים וקרובים יותר למקורם ושרשם אלא מאחר שנמשכין מאור פניו ית' בדרך התפשטות האור בסדר המדרגות והשתלשלות שלא בדרך נפילה ח\"ו א\"א להיות השמחה בהתגלות אורה כנ\"ל. אבל לעתיד כשיתעלו הנצוצות הנפולים כנ\"ל הרי גם בחינת אור וחיות שהיתה בתוך הנפילה שהיא מבחי' למעלה מהרצון מתגלה בתוספת אורה ושמחה בגלוי רב ועצום ביתר שאת:"],[83,"<b>וזהו<\/b> ויהי בשלח פרעה את העם כי פרעה אמר לא ידעתי את ה' והוא בחינת עורף אחוריים דרצון העליון ויניקתם מבחי' עוברי רצונו הנ\"ל. והיה משלח פארות וענפים ועושי פרי למעלה את העם שע\"י גלותם במצרים והשתעבדותם בהם גרמו שנתעלו בחי' נצוצי אלהים שנפלו שמה בשבירת הכלים והוא הוא בחי' כח הצומח להצמיח ישועות ישראל כמ\"ש ופרעה הקריב ואמרו רז\"ל שהקריב את לבם של ישראל לאביהם שבשמים. ועל דרך זה נתיסד כל שירת הים אז ישיר משה וגו'. כמ\"ש במ\"א:"],[83,"<b>ולא<\/b> נחם אלהים דרך ארץ פלשתים וגו'. פלשתים לשון מבוי המפולש כמו שאמרו רז\"ל על פסוק ובמושב לצים לא ישב אלו פלשתים. והענין כי זה לעומת זה עשה אלהים ויש בחי' פלשתים בקדושה ובחי' פלשתים בקליפה. בחי' פלשתים שבקדושה היא בחי' התגלות השמחה בדביקות ה' בפילוש ובגלוי ובהתרחבות לאין קץ בחי' ובכל מאדך הנ\"ל."],[83,"ופלשתים שבקליפה הם הלצים שהוא ג\"כ ענין הרחבת ⟦סא,ד⟧פיו כרצונו לדבר מה שלבו חפץ והיא שמחה של הוללות לאמר שפתינו אתנו כו'. ואין מעצור לרוחו. ולכן נק' קליפה כי כמו שהקליפה מכסה ומסתרת על הפרי שנראית כמו שהוא עיקר הפרי כך השמחה של הוללות מכסה ומסתרת על אור ה' שבה להיות יש ודבר בפני עצמו הפך רוחניות וחיות אלהי שבקרבה לשמוח בה' אלהים חיים מחמת הבטול במציאות אליו ית'."],[83,"ופי' הפסוק שאין זה דרך ה' לבא מיד לבחינת השמחה בה' כי קרוב הוא ליפול מזה כי פן בראותם מלחמה שהוא ענין הנסיון שיבא לאדם לא יוכל לעמוד בקשרי המלחמה ויסוג אחור ושבו מצרימה. אלא הדרך הנכון כמ\"ש תחת אשר לא עבדת את ה' אלקיך בשמחה שתהא השמחה ע\"י עבודה וזהו ויסב אלהים את העם דרך המדבר ים סוף. ים הוא החכמה סוף הוא סופא דכל דרגין כמ\"ש בזוהר והיא תושבע\"פ שהוא ענין קבלת עומ\"ש כמ\"ש שום תשים עליך מלך לקיים מצותיו שעיקר התורה מיוסד על דיני המצות וכמו שארז\"ל ע\"פ התורה והמצוה אשר כתבתי להורותם התורה זו תושב\"כ והמצוה זו תושבע\"פ כו' שע\"י יתקיים בו השמחה אמתית אשר קדשנו במצותיו כנ\"ל כי זה השער לה' תרעא לאעלאה כו' והשמחה אמתית שהיא מאהבת ה' צריך להקדים לה היראה שהיא ראשית העבודה ועקרה ושרשה כמ\"ש במ\"א."],[83,"והנה ארז\"ל הרוצה לקבל עליו עומ\"ש שלימה יפנה ויטול ידיו ויניח ציצית ותפילין פי' שמתחלה יפנה ויסיר הצואה מקרבו שהוא בחי' הרע שבקרבו ואח\"כ יקבל עליו עומ\"ש בפריסו דטלית של מצוה שהוא ענין שום תשים עליך מלך דהיינו בחי' מלכותו ית' שהיא מלכות כל עולמים ימשיך על נפשו בפריסו דטלית וכן עד\"ז הוא קיום כל המצות להמשיך על נפשו אור וחיות מבחי' מלכותו יתברך."],[83,"וכן הוא בענין לימוד התורה דמתניתא מלכתא בחי' מלכותו ית' ובחי' ודברי אשר שמתי בפיך וגו' ואשים דברי בפיך וגו' ועי\"ז ממשיך בחי' מלכותו ית' בנפשו ממש. וזהו ויסב אלהים את העם דרך המדבר ים סוף שבכדי לבא לבחי' ים סוף דהיינו קבלת עומ\"ש צריך תחלה להסב דרך המדבר שהוא בחי' יפנה הנ\"ל דהיינו לשום מרירות תמיד בנפשו על חטאותיו אשר עשה ואף שכבר עשה תשובה עליהם וכמ\"ש וחטאתי נגדי תמיד או אפי' לא חטא כלל מ\"מ ישים לנגד עיניו תמיד להיות ממארי דחושבנא על מחשבה דבור מעשה אשר לא לה' המה בהבל בא ובחשך ילך ואח\"כ יכול לקבל עליו עומ\"ש בחי' ים סוף הנ\"ל בעסק התורה והמצות וכיון שמקבל עליו עול תורה מעבירין מעליו עול ד\"א שהוא שעבוד לנה\"ב ויעלה ויבא ויגיע מזה לבחי' שמחה אמתית ודביקות בה' אחד בבחינת בטול אליו ית' להתיחד באחדות ה' ממש שהיא בחינת ארץ כנען מלשון הכנעה וביטול בה' אחד והיא מעלה ומדרגה יותר מעולה מבחי' ארץ פלשתים הנ\"ל:"],[84,"<b>וירא ישראל את היד הגדולה אשר עשה הוי\"ה במצרים וייראו העם את הוי\"ה ויאמינו בהוי\"ה ובמשה עבדו.<\/b> להבין למה הקדים בחי' יראה לבחי' אמונה. הנה כתיב ויקרא הוי\"ה הוי\"ה ב\"פ. כי הנה יש ב' בחי' שמות הוי\"ה. א' הוא בחי' שם הוי\"ה דלתתא המהוה כל העולמות מאין ליש."],[84,"ולהבין לשון מאין ליש והלא כתיב כי ממך הכל. אך בהיות כי מהותו ועצמותו ית' אין לו שייכות לעולמות ואין ערוך אליו כו'. ולכן בלתי אפשר לעולמות לקבל חיותם והתהוותם כ\"א ע\"י בחי' שם הוי\"ה ב\"ה היינו על ידי צמצום שהוא בחי' יו\"ד ואח\"כ התפשטות זיוו ואורו בחי' ה' וע\"ז נאמר כי הוא צוה ונבראו והוא קאי על שם הוי\"ה דכתיב לעיל מיניה יהללו את שם ה' ושם ה' הוא צוה לשון התקשרות כו'. ונבראו לשון נפעל כו'."],[84,"והנה כמו שבבחי' זו צ\"ל צמצום והתפשטות בחי' שם הוי\"ה. ⟦סב,א⟧כן יש בחי' שם הוי\"ה דלעילא ג\"כ יו\"ד בחי' צמצום כו'. והוא בחי' רצון עלה במחשבה להיות הוי\"ה דלתתא להיות העולמות כמו למשל באדם שקודם שהוציא מלאכתו מכח אל הפועל היה הדבר ההוא מצוייר במחשבתו איך ומה לעשות כו'."],[84,"ובבחי' זו צ\"ל ג\"כ בחי' יו\"ד הוא צמצום תחלה ואח\"כ ה' התפשטות. ובחי' זו נק' עלמא דאתכסייא שאינה נראית ונגלית כמו הוי\"ה דלתתא. ולכן אמר פרעה מי הוא הוי\"ה שלא האמין לבחי' שם הוי\"ה דלעילא. כי בודאי שם הוי\"ה דלתתא המהוה כל העולמות ידע כו'."],[84,"וביצ\"מ כתיב וירא ישראל את היד הגדולה אשר עשה הוי\"ה במצרים. פי' אשר עשה הוי\"ה דלעילא ע\"י בחי' מצרים אעא דלא סליק בה כו'. כי בלתי אפשר להגיע לבחי' הוי\"ה דלעילא כ\"א ע\"י סור מרע בחי' בטול וצמצום לאו קודם להן כו'. י\"ה עם שמי שס\"ה כו'. ובאתערותא דלתתא שצמצם א\"ע להיות סו\"מ נעשה לעילא בחי' יו\"ד הוא בחי' צמצום. ובעושה טוב שהוא בחי' התפשטות כמו בחי' צדקה כו' נעשה לעילא בחי' ה' הוא בחי' התפשטות:"],[84,"<b>והנה<\/b> ישראל ראו את היד הגדולה ע\"י קי\"ס וישם את הים לחרבה. ים הוא בחי' עלמא דאתכסייא כל מה שיש ביבשה כו'. ויבשה הוא בחי' עלמא דאתגלייא. ובראותם שהוא ית' הפך ים ליבשה וישם את הים לחרבה בלי שום לחלוחית כו' בחי' יקוו המים כו' ותראה היבשה האמינו בהוי\"ה שיכול להיות התגלות בחי' הוי\"ה דלעילא שהוא בחי' עלמא דאתכסייא כו'."],[84,"וזהו וייראו העם את ה' ויאמינו בהוי\"ה. וייראו את הוי\"ה היינו הוי\"ה דלתתא עלמא דאתגלייא שהוא בבחי' השגה ושייך בו לשון יראה יראה בושת כמשל הרואה את המלך כו'. ויאמינו בה' הוא הוי\"ה דלעילא עלמא דאתכסייא שאינו נראה ומושג ולא שייך בו בחי' יראה כ\"א אמונה."],[84,"ולכן כתיב הגדול הגבור והנורא שלהיות בחי' נורא צ\"ל תחלה וי\"ו הוא בחי' המשכה מלמעלה למטה להיות בחי' נורא. ובמשה עבדו משה הוא בחי' דעת והתקשרות. כי משה משבעה רועים. והוא הממשיך לכללות נש\"י בחי' אמונה. ולכן נק' רעיא מהימנא רועה נאמן שרועה ומפרנס וממשיך בחי' אמונה. כמ\"ש בכל ביתי נאמן הוא והוא המחבר ומקשר ב' הויות הנ\"ל כו'. ולכן ארז\"ל אטו יראה מילתא זוטרתא היא. אין לגבי משה כו' וע\"י בחי' משה נתעלו לבחי' הוי\"ה דלעילא ולכן כתיב ואתם תחרישון בחי' שתיקה וכו' עלמא דאתכסייא:"],[84,"<b>והנה<\/b> כ' בנהר יעברו ברגל שם נשמחה בו. כי הנה עתה בזמן הזה לא שייך בחי' שמחה שהשמחה היא מבחי' התגלות. ועתה בזמן הזה אין בבחי' זו התגלות כ\"א אמונה מחמת הסתר הגוף כו'."],[84,"ולע\"ל שיהי' בלע המות כו'. כתיב כי עין בעין יראו. עין בעין הוא בחי' עלמא דאתכסייא בחי' סוכ\"ע ומתחת זרועות עולם כו' ועלמא דאתגלייא שיתגלו ב' הויות הנ\"ל כי לעתיד כתיב והכהו לשבעה נחלים כו'."],[84,"והיתה מסילה לשאר עמו כו' כאשר היתה לישראל ביום עלותו מארץ מצרים היינו שיתגלה עלמא דאתכסייא כו'. וע\"ז נאמר בנהר יעברו ברגל שם נשמחה לשון עתיד ושם דייקא נשמחה בהשגת הוי\"ה דלעילא משא\"כ עתה שאינו אלא בבחי' אמונה רק שהיום לעשותם כתיב ולמחר כו' שהיום צריך לעשות ע\"י סומ\"ר בחי' בטול והודאה ובאתעדל\"ת כו' כנ\"ל."],[84,"ולכן ארז\"ל מאן דלא כרע במודים כו' כי יש ב' בחי' בחי' ברכה היינו המשכת כו' ובחי' הודאה בחי' בטול בחי' תשובה ומע\"ט ולכן ארז\"ל יפה שעה אחת בתשו' ומע\"ט בעוה\"ז מכל חיי עוה\"ב כי חיי עוה\"ב הוא משם הוי\"ה דלתתא ביו\"ד נברא ⟦סב,ב⟧כו' משא\"כ תשובה ומע\"ט. שע\"י נעשה בחי' הוי\"ה דלעילא כנ\"ל."],[84,"ודוקא ע\"י בחי' משה כנ\"ל. ולכן כתיב ויקרא הוי\"ה הוי\"ה ויקרא קאי על משה שמשה קורא וממשיך מהוי\"ה דלעילא להוי\"ה דלתתא. שהי' פסיק טעמי' כו'. וע\"י בחי' משה נעשה חבור וקשור ב' הוי' כנ\"ל. ולכן בשעת קי\"ס כתיב אז ישיר משה ובני ישראל כו' אשירה לה' כי גאה גאה בחי' עלמא דאתכסייא טורי דחשוכא."],[84,"והנה אחר שנתעלו בני ישראל לבחי' זו לא רצו ליסע משם לכן כתיב ויסע משה ויסע בע\"כ ויבאו מדבר שור. שור הוא לשון ראיה והתגלות בחי' עלמא דאתגלייא. ויבאו מרתה כי רגליה יורדות כו'. ויורהו ה' עץ הוא עץ החיים. ועד\"ז היו כל המ\"ב מסעות שהם כנגד שם מ\"ב הוא בחי' עלייה ממדרגה למדרגה כו' חסד שבחסד חסד שבגבורה כו'. ולכן היתה נסיעתם פעם בבקר פעם בערב והכל ע\"י משה כו' וד\"ל:"],[85,"<b>אז ישיר משה ובני ישראל את השירה הזאת לה' ויאמרו לאמר אשירה לה' כי גאה גאה סוס ורוכבו רמה בים.<\/b> הנה להבין ענין קי\"ס. וגם הלא לפי דרך בנ\"י ממצרים לא\"י לא היה להם דרך על הים אלא שצוה ה' וישובו ויחנו כו' (וגם לא עברו את הים מעבר לעבר אלא באותו צד שירדו באותו צד עצמו עלו). הטעם כתיב וידעו מצרים כי אני ה'. וצריך להבין דהא כתיב ויכסו מים צריהם אחד מהם לא נותר. אלא הענין כי הנה יש מצרים בכל אדם ובכל זמן. ולכן אמרו בכל דור ודור חייב אדם לראות א\"ע כאלו הוא יצא ממצרים וכתיב למען תזכור את יום צאתך מארץ מצרים כל ימי חייך."],[85,"ואיתא בתוספתא שצריך לזכור ג\"כ קריעת ים סוף והענין כי הנה ארז\"ל על ג' דברים העולם עומד. על התורה ועל העבודה ועל גמ\"ח. עבודה הן הן הקרבנות שהיה אש שלמעלה יורד ע\"ג המזבח ארי' דאכיל קורבנין."],[85,"ומשחרב בהמ\"ק תקנו תפלה כנגד הקרבנות דהיינו למסור נפשו הבהמית שתוכלל באש של מעלה בחי' אהבה רבה הבאה מלמעלה ואתערותא דלעילא כו'. ולהבין כיצד הוא מרומז בתפלה איך שיורד בחינת אש שלמעלה. אך הענין זהו אשר תקנו בש\"ע לומר כל הברכות ברוך אתה כו'."],[85,"והוא ע\"ד מ\"ש ברוך ה' אלהי ישראל מן העולם ועד העולם. פי' מעלמא דאתכסייא לעלמא דאתגלייא דהיינו מבחי' סוכ\"ע לממכ\"ע כי הוי\"ה הוא האלהים וכשמקשר נפשו הבהמית לה' אחד אזי גם בחי' אש שלמעלה מבחי' סוכ\"ע שורה ומתגלה בנפשו. וזהו ברוך לשון המשכה מההעלם אל הגילוי להיות בבחי' אתה לנוכח:"],[85,"<b>וביאור<\/b> הענין כי הנה ארז\"ל כל מה שיש ביבשה יש בים. ים הוא בחי' עלמא דאתכסיא ויבשה הוא בחי' עלמא דאתגלייא. והנה ההפרש שבין יבשה לים בגשמיות הוא שהברואים שבים אינם נראים לחוץ כי הים מכסה עליהם וגם חיותם וקיומם הוא בתוך הים דוקא וא\"א להם לחיות ביבשה שמיד מתים משא\"כ ברואים שביבשה הנה הארץ תוציא צמחה ועושה פרי למעלה."],[85,"והגם שיניקותם ממנה הם נראים כאלו הן יש ודבר בפ\"ע ומכ\"ש שאר הברואים אשר בהם נפש חיה למינה. ועד\"ז יובן ההפרש ברוחניות למעלה ההפרש בין עלמא דאתכסיא לעלמא דאתגלייא. כי הנה מבשרי אחזה שיש בנשמה שכל ומדות והשכל נחלק לג' והמדות לז' ויש עליהם ג' לבושים מחדו\"מ וגם הם מתחלקים לפרטים רבים ובכללן הם ה' בחינות שכל ומדות ומחדו\"מ כנגד נרנח\"י וכמה מיני מדרגות גבוה מעל גבוה וגבוהים עליהם כולם הם בבחי' נרנח\"י כל אחד יש לו בחי' בפני עצמו מה שאין בחבירו יש מי שעובד בבחי' ומדרגת כלות ⟦סב,ג⟧הנפש כו' וכן הנשמה בפ\"ע בג\"ע יש כמה בחי' ומדרגות שונות. אך יש מהן בבחי' עלמא דאתגליא שנראים המדרגות מופרדים בגילוי."],[85,"ויש מהם שהם עלמא דאתכסייא שהם בטלים במציאות במקורם שהוא בחי' סוכ\"ע דכולא קמיה כלא חשיב ומבחי' זו היתה מדרגת משה רבינו ע\"ה שנאמר עליו כי מן המים משיתהו מבחי' ים עלמא דאתכסייא ולכן היה כבד פה שבחי' דבור והתגלות נמנע ממנו לפי שהיה לו יתרון ומעלה בבחי' ומדרגת בטול במציאות במאד כמ\"ש ונחנו מה כו'. וזהו ענין הברכה ברוך אתה כו' מן העולם ועד העולם שיהיה בחי' עלמא דאתכסייא ובחי' סוכ\"ע שהוא בחי' בטול דכולא קמיה כלא חשיב נמשך בגלוי גם בעלמא דאתגלייא וראו כל בשר כו':"],[85,"<b>אך<\/b> כל בחי' ברכה והמשכה מלמעלה למטה זו היא בחי' ומדרגת עבודת הכהן. אבל עבודת הלוים מדה אחרת היתה בם היא ממטה למעלה דכתיב ועבד הלוי הוא שבחי' עבודתו היא בבחינה עלמא דאתכסייא שלא יהיה בחי' ומדרגת עלמא דאתגלייא נראה לבחי' ומדרגה כלל ולא יהיה תופס מקום כלל כמ\"ש אתה הוא הוי' לבדך וגו' שאינו בגדר עלמין כלל לא בגדר ממלא ולא בגדר סובב ולזה היתה עבודתם בשירה וזמרה בנגון. כי ענין הנגון הוא שאין בו רק התפעלות הנפש מפני גילוי התנועות ולא מפני שיש בתנועות ההם מצד עצמם שום שכל והתחדשות אלא מפני גילוי התנועה מתעורר גילוי הלב."],[85,"ולכן אפילו בנגון ישן יש התעוררות והתפעלות מפני גילוי התנועה שבה כך הוא ענין עבודת הלוי בשירה להיות בחי' התפעלות הנפש מצד עצמה ולא מצד השגה להוליד מבינתו כו' מאחר שעבודתו בבחי' הוא בחי' אתה הוא ה' לבדך וגו' דלית מחשבה תפיסא ביה כלל אלא התפעלות רעותא דלבא שיהיה נוגע עד הנפש נקודת הלב ולא להיות בחי' מקיף לבד."],[85,"ועד\"ז נתקן פסוקי דזמרה קודם ק\"ש ולכן קוראין אותן פסוד\"ז שהם כעין בחי' נגון שהוא רק הרחבת הדבור וביאור הענין בתוספת ביאור לפרש הדבר היטיב להלהיב לבו ונפשו שיתפעל מזה משא\"כ כשאומר הפסוקים ואינו נוגע לנקודת לבבו אין זה בחי' זמרה ונגון ואין זו עבודה תמה."],[85,"וזהו אשירה לה' כי גאה גאה. פי' שבחי' אשירה הוא מפני כי גאה למעלה מגאה וגאה הוא בחינת סובב כל עלמין דכולא קמיה כלא חשיב. וגאה על גאה הוא יתברך בעצמו ובכבודו אין סוף ברוך הוא ממש דלית מחשבה תפיסא ביה כלל בחינת אתה הוא ה' לבדך וגו' לא נערוך אליו קדושתו. פי' שאפילו קדושתו שהוא קדוש ומובדל כו' לא נערוך אליו לפי שאינו בגדר עלמין כלל:"],[85,"<b>ולכן<\/b> סוס ורוכבו רמה בים. כי הנה כתיב כי תרכב על סוסיך מרכבותיך ישועה. וביאור הדבר דהנה האותיות נקראים סוסים כמו שסוס בטל לגבי רוכבו והרוכב מנהיגו. כך הנה אותיות דבורו הם בטלים לגבי השכל והשכל מנהיגו לכל אשר יחפוץ יטנו אך מ\"מ יש יתרון מעלה בסוס שיכול להוליך את הרוכב למקום שאין הרוכב יכול לילך שם."],[85,"וכך יש יתרון ומעלה באותיות הדבור שיכולים להגביה את השכל למדרגה מאד נעלה מה שאין ביכולת השכל להשיג מצד עצם השכלתו כמו שנראה בחוש שע\"י הדבור יתוסף השפעת שכל בשכלו. וכך הוא הענין בנפש האדם המדברת בתפלה הגם שהדבור הוא רק מלבושי הנפש ואין לו ערך כלל לגבי מהות הנפש עצמה שהאר' ממנה בלבד היא מתפשטת להיות שכל ומדות כו' מ\"מ מבחי' הדיבור נעשה אור מקיף להנשמה שמקיפה מראשה ועד רגלה להיות צרורה בצרור החיים את ה' ממש וכו' כמ\"ש בלק\"א מה שלא היה כח בנשמה ⟦סב,ד⟧מצד עצמה."],[85,"והנה כתיב לא בגבורת הסוס יחפץ ולא בשוקי האיש ירצה רוצה ה' את יראיו כו' כי בחי' אותיות שהם בחי' סוסים הם בחי' גבורות וכענין וגבורתך ידברו. וגבורותיך יגידו. להודיע לבני האדם גבורותיו. שהם בחי' צמצומים ומסכים הרבים מינים ממינים שונים כדי להתהוות עולמות עליונים ותחתונים שבאמת הן הם גבורותיו כו' דכולא קמיה כלא חשיב והוא צופה ומביט עד סוף כל הדורות וקורא הדורות מראש ובמחשבה אחת ברא את העולם כו' כמ\"ש במ\"א:"],[85,"<b>וזהו<\/b> יש קונה עולמו בשעה אחת. פי' שכל בחי' תענוגי הנבראים מה שיכול להיות נמשך לנברא בעל גבול להיות מקבל תענוג מזה ואפילו תענוג רוחני וג\"ע העליון נק' בחי' יש. וכמ\"ש להנחיל אוהבי יש."],[85,"והנה בחי' יש זה קונה עולמו כשנכלל בבחי' שעה אחת שהוא בחי' מחשבה אחת שבה כו' ברא את העולם. וזהו לא בגבורת הסוס יחפץ. פי' שאינו מאיר חפץ ה' בגבורות וצמצומים בחי' האותיות לבדם כי האומר אין לי אלא תורה כו'. וכן לא בשוקי האיש המחזיקים בחי' הסוסים דהיינו הדעת והמחשבה הצריך לדבור ומעשה בלבד בזה אין חפץ ורצון ה' מאיר כ\"כ. אלא רוצה ה' שמאיר חפצו ורצונו בפנימיותו את יראיו דהיינו מי שהוא בבחי' בטול כמו שאמר משרע\"ה ונחנו מה והוא מצד התפעלות הנפש מפני עצמותו ומהותו ית':"],[85,"<b>וזהו<\/b> המיחלים לחסדו. פי' שאין להם בחי' אהבה מצד עצמם להיות תשוקתם לדבקה בו ית' לרוות צמאונם בלבד אלא להיות המשכת חסדו חסד עולם מעולם ועד עולם ומיחלים כאשר ירד ויומשך מלמעל' ולא שהדבר נוגע לעצמם."],[85,"וזהו סוס ורוכבו רמה בים. פי' שבחי' האותיות דומ\"ח מקור דעלמא דאתגליא שהן הן בחי' צמצומים וגבורותיו רמה והגביה עד בחי' ים הוא עלמא דאתכסייא והיינו מפני כי גאה גאה שאתה הוא ה' לבדך כולא קמיה כלא חשיב לפניו כחשיכה כאורה דעלמא דאתכסייא ועלמא דאתגלייא שוין."],[85,"ולכן הפך ים ליבשה וזהו בנהר יעברו ברגל שם נשמחה בו. פי' בעצמותו ומהותו כביכול אך מפני כי בבחי' זו גם האויב אמר ארדוף כו'. פי' שגם עכו\"ם רוצים להיות יניקתם ואחיזתם משם מאחר שלפניו ית' כחשיכה כאורה וסוס ורוכבו רמה בים ולזה אמר עיניו בגוים תצפינה והסוררים אל ירומו למו סלה שאין לעכו\"ם התרוממות זו אלא ויכסו מים צריהם ואין להם אלא ירידה מבחי' זו עצמה כי רם על כל גוים ה' וזהו סיבת נפילתם. אבל ובני ישראל הלכו ביבשה בתוך הים כי המים להם חומה מימינם ומשמאלם פי' כי הנה ארז\"ל על ג' דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח. שהוא בחי' ימין ושמאל וישראל עלו במחשבה ולכך אומרים אשר קדשנו במצותיו שע\"י המצות הם מתעלים בקודש העליון שמשם שרש נשמתם ורוח אייתי רוח ואמשיך רוח ולכך אצלם סוס ורוכבו רמה בים והלכו ביבשה משא\"כ הסוררים אל ירומו כו' כנ\"ל:"],[86,"<b>אשירה<\/b> לה' כי גאה גאה וגו'. ותרגם אונקלוס גיאה על גיותניא וכו'. יובן בהקדים להבין ענין ירידת הנשמה לעוה\"ז שירידה זו צורך עלייה היא כנודע. והנה הנשמה קודם בואה לעוה\"ז היתה עומדת לפני ה' ביראה ואהבה כמ\"ש חי ה' אשר עמדתי לפניו ואי אפשר לה לעמוד למעלה לפני ה' בלא דחילו ורחימו כי בלא דחילו ורחימו לא פרחא לעילא. וע\"ז נאמר והחיות רצוא ושוב כמראה הבזק (הגם שזה נאמר על המלאכים הוא הדין לנשמות וכל צבא מעלה) רצוא באהבה להיות נכספה וגם כלתה נפשו כו'. ושוב ביראה כי מי הוא אשר ערב לבו לגשת כו'. אך בירידתה לעוה\"ז נתעלמו הדחילו ורחימו ונתלבשה בגוף הגשמי ולא יכלה עוד להיות ⟦סג,א⟧תמיד בבחי' רצוא ושוב כמראה הבזק כמו שהיתה למעלה כי אם לפרקים ועתים מזומנים שתתעורר האהבה ואף גם זאת אין ערוך אהבה ויראה זו לגבי אהבה ויראה שהיה לה מימי קדם וירידה זו היא צורך עלייה שתתעלה בעסק התורה וקיום המצות."],[86,"וצריך להבין היתרון והמעלה שבעסק התורה וקיום המצות יתר על דחילו ורחימו שהיה לה. אך הנה נודע מאמר אדון הנפלאות המחדש בטובו בכל יום תמיד מעשה בראשית שמראשית השתלשלות ועד סוף כל הנבראים הם מתחדשים בכל יום מאין ליש והתחדשות זו היא בבחי' ממלא כל עלמין להיות דרך השתלשלו' מעילה לעילה תחלה רוחניות עולמות עליונים ושכלים נבדלים ואח\"כ יורד ומשתלשל למטה מטה עד שנתגשם החיות להיות מעשה שמים וארץ גשמיים."],[86,"וכמשל הנשמה המתפשטת בגוף שראשית הגלוי במוח השכל ואח\"כ בפה הדבור. ואח\"כ בידים המעשה כו'. והתחדשות זו להיות בחי' מעלה ומטה רוחניות וגשמיות הוא בטובו שהיא מדת טובו ורחמנותו. וכמ\"ש טוב ה' לכל ורחמיו על כל מעשיו כי הוא יתברך אין סוף הסובב כל עלמין השוה ומשוה קטן וגדול מעלה ומטה גשמיות ורוחניות שוין לפניו כו'. וזהו אדון הנפלאות. פי' שאפי' בחי' נפלאות שהן עלמין סתימין כו' אין ערוך אליו יתברך וכמ\"ש עשה פלא שבחי' פלא הוא בחי' עשיה כו'."],[86,"והנה דביקות הנפש בשרשה באלקים חיים היא מחמת השגתה את החיות המתפשט מאור אין סוף ב\"ה להחיות העולמות כי עמך מקור חיים כו' שעל ידי זה היא בבחינת רצוא לאהבה את ה' כי הוא חייך חייך דוקא. אך אם רץ לבך שוב לאחד לפי שהוא ית' בעצמו הוא אדון הנפלאות ועושה פלא ואינו בכלל השגת הנפש ודבקותה ולכך היא בבחי' שוב."],[86,"וזהו נורא תהלות אדון הנפלאות. נורא תהלות עשה פלא. כי לפי שהוא אדון הנפלאות עושה פלא לכך הוא נורא תהלות שיראים להללו כו'. אבל ע\"י עסק התורה וקיום המצות תהיה דביקות הנפש בבחינת סובב כל עלמין אדון הנפלאות. כי הנה התורה והמצות נמשכים מבחינת אדון הנפלאות וסובב כל עלמין."],[86,"וזה היה ענין קריעת ים סוף קודם מתן תורה הפך ים ליבשה. שהים הוא בחינת עלמא דאתכסייא כמאמר רבותינו ז\"ל כל מה שיש ביבשה יש בים אלא שהמים מכסים ואינם נראים שבחי' עלמא דאתכסייא בא לידי גילוי בבחינת עלמא דאתגלייא כדי להיות גילוי המשכת התורה במתן תורה."],[86,"והנה צירופי אותיות התורה נק' בשם סוסים על דרך משל. ועל זה נאמר סוס ורוכבו רמה בים כמו שיתבאר. מפני שהסוס הגם שהוא טפל לרוכבו על כל זה יש בו מעלה יתירה שיכול לרוץ ולהוליך את הרוכב למקום שלא היה הרוכב יכול להגיע שם בלי סוס כך כל צירופי אותיות התורה יש בהם יתרון ומעלה זו שבדביקות נפש האדם בצירופי אותיות אף שאינו יודע ומבין הענין בעין השכל רק שהוגה ומדבר בהם (לאפוקי הרהור דלאו כדבור דמי) הרי הם מעלים את הנפש למקום שלא היתה הנפש מגעת שם מצד שרשה כי שרש אותיות התורה היא הגבה למעלה משרש הנפש דאבא יסד ברתא אלא שהאדם צריך להיות בחי' רוכב להאותיות שיהא מושך ומנהיג ע\"י דחילו ורחימו שיעורר כפי אשר יוכל שאת כל חד לפום שיעורא דיליה."],[86,"ואפי' האהבה הטבעית המסותרת בו כי בלא דחילו ורחימו כלל לא פרחא לעילא. וכמו שהוא לענין תורה כך הוא לענין שאר מצות דכתיב ושמרו דרך ה' לעשות צדקה ומשפט למען הביא ה' על אברהם את אשר דבר עליו שע\"י המצות שנקראו דרך כלל בשם צדקה ומשפט כמו שיתבאר נמשך על בחי' אברהם שהיא מדת האהבה ברצוא הלוך ונסוע. את אשר דבר עליו עליו ⟦סג,ב⟧דייקא הוא בחינת אדון הנפלאות שהוא למעלה מעלה מהשגת הנפש ודביקותו באלקים חיים שלכן היא בחי' שוב כנ\"ל:"],[86,"<b>וביאור<\/b> זה הוא כי הנה דרך הוי'. פירוש דרך ומבוא להיות הוי' דהיינו שיהי' בחי' הוי' המורה על התהוות העולמו' מאין ליש על ידי אותיות שם הוי\"ה יו\"ד חכמה כו' כי הרי הוא ית' למעלה מן החכמה ואנת הוא חכים כו'. פירוש ע\"ד במקום שאתה מוצא גדולתו שם אתה מוצא ענותנותו כי כולם בחכמה עשית עשיה גשמית."],[86,"וכתיב אני הוי' הוא שמי. שמי בלבד כמשל השם שאינו מערך ומהות העצמית כו'. ועד שלא נברא העולם היה הוא ושמו בלבד. פי' בלבד בבחי' העלם וכדי להיות הוי' בבחי' גילוי נמשכה מדת טובו ורחמנותו. טוב ה' לכל ורחמיו על כל מעשיו. המחדש בטובו כו'. הטוב כי לא כלו רחמיך כו' היא בחי' רחמים רבים שלפני האצי' שהוא למעלה מעלה מסדר ההשתלשלות כי מדת הרחמים שבסדר ההשתלשלות יש כנגדה מדת הדין המצמצמת ימינא ושמאלא כו' והיא בחי' מדה וגבול. אבל רחמי' רבים שלמעלה מהשתלשלות הוא רחמנות שאין לה שיעור ולא ערך אפילו בערך אדם שמרחם על הזבוב שרחוקה היא ממהות ומדרגת האדם. על כל זה יש לה איזה ערך שהיא בריה כמוהו. משא\"כ לא\"ס ב\"ה אין ערוך אליו כלל ואפי' עולמות עליונים בחי' נפלאות."],[86,"ולכן גם עליהם נופל מדת הרחמים הגדולה הזאת כי הוא אין סוף ב\"ה הסובב כל עלמין כו' והוא השוה ומשוה כו'. ועל זה נאמר חנון ורחום הוי' שהקדים בחי' חנון ורחום להיות הוי' שהן הן י\"ג מכילין דרחמי מקור האצילות כו' כמ\"ש במ\"א."],[86,"וזהו דרך והמשכה להיות בחי' הוי\"ה והיא על ידי אתערותא דלתתא בצדקה ומשפט שהן דרך כלל כל מצות התורה כמו שיתבאר. ובפרטות הוא מצות הצדקה שהיא התעוררות מדת הרחמנות להשפיע במדת טובו וחסדו להחיות רוח שפלים ועל ידי זה אתערותא דלעילא להיות דרך הוי' לעשות צדקה כו' שיהא התלבשות אור אין סוף ברוך הוא בבחי' תורה ומצות."],[86,"ולהיות אנת חכים כו' שהוא מדת טובו ורחמנותו להיות התלבשות זה והמשכה זו כמאמר אב הרחמן המהולל כו'. ועל זה נאמר משפט וצדקה ביעקב אתה עשית שעל ידי משפט וצדקה שביעקב נעשה בחי' אתה דהיינו גילוי אלהות. אך הנה בצדקה זו משפט כתיב בה. כמ\"ש לעשות צדקה ומשפט. משפט וצדקה ביעקב כי לא די לעורר בחי' חסדו וטובו יתברך בלבד כי מאחר שהיא התעוררות בחי' אין סוף השוה ומשוה כו'. הנה בבחי' זו נאמר שממית בידים תתפש והיא בהיכלי מלך שגם השממית היא בחינ' הקליפה וסט\"א יש לה יניקה ואחיזה כו'."],[86,"וכענין לא כאברהם שיצא ממנו ישמעאל כו'. וצריך לעורר בחינת משפט למעלה שלא יומשך חיות ויניקה אלא בסטרא דקדושה יאר ה' פניו אליך ישא ה'פניו אליך היינו פנימית ועיקר החיות. אבל יניקת החיצונים וסטרא אחרא היא ממותרות צפרנים ושערות כו'."],[86,"ובחי' משפט זה אשר לאלהים הוא על ידי אתערותא דלתתא בחי' משפט שעושה האדם בנפשו על מותרות חיי גופו נגד הצדקה. כי הנה ארז\"ל חייך קודמין לחיי חבירך ודוקא חייך ממש כמשל הקיתון של מים שאם ישתו שניהם ימותו כו' כדאיתא בגמרא. מה שאין כן המותרות שלך אינן קודמין לחיי חבירך שאינו בדין שיפנק האדם את נפשו בתפנוקי עלמא וחבירו ימות ברעב ח\"ו."],[86,"ועל ידי משפט זה שעושה האדם שלא לתת יניקה וחיות מותרות הגוף גורם למעלה בחי' משפט שלא יומשך חיות המותרות שהן החיצוני' וסטרא אחרא. וזהו שמשבחים ומברכים את ה' אוהב צדקה ומשפט:"],[86,"⟦סג,ג⟧<b>והנה<\/b> גם שאר מצות התורה נקראות בשם צדקה על דרך זה כי רמ\"ח מצות עשה הם רמ\"ח אברין דמלכא. היינו כמו על דרך משל האבר שמלובש בו חיות הנשמה שמבלעדי החיות זה נשאר הגוף כאבן דומם. כך הנה המצות הם בחי' אברין דמלכא שמלובש בהם חיות ואור אין סוף ברוך הוא."],[86,"ולהיות נמשך חיות זה הוא גם כן מחמת מדת טובו ורחמנותו כנזכר לעיל על ידי אתערותא דלתתא בקיום מעשה המצות בפועל ממש כמו תפלין לכתוב על קלף של בהמה פרשיות ואזכרות שעל ידי זה ממשיך בהם קדושה עליונה מאור אין סוף ברוך הוא להיות כנשמה לגוף המצות והיא בחינת מדת הרחמים להחיות למאן דלית ליה מגרמיה וכו'."],[86,"וזהו שכתוב לעשות את כל דברי התורה הזאת. ושמרתם ועשיתם אותם. אתם כתיב כמ\"ש במ\"א. ולכן נקרא המקיים התורה והמצות בשם צדיק ומעלת צדיק היא מעלה רבה מאד ששיבחו הכתוב וצדיק יסוד עולם ואמרו רבותינו ז\"ל ראה בצדיקים כו' עמד ושתלן כו' ולכאורה לשון צדיק הוא שהוא צדיק בדינו ואינו עושה עול לבריות ואין זו מעלה גדולה כל כך. אלא עיקר שם צדיק ע\"ש שהוא בעל צדק' שהוא המשפיע צדקה וחסד במדת טובו ורחמנותו להחיות את המצות על ידי קיומם במעשה בפועל ממש ולהמשיך להם חיות ואוא\"ס ב\"ה כנשמה לגוף כנזכר לעיל:"],[86,"<b>וזהו<\/b> תכלית ירידת הנשמה לעולם הזה. כי בירידה זו אף שהיא ירידה גדולה בבחינת דחילו ורחימו אף על פי כן גדלה מעלתה שנעשית בחינת בעל תשובה אחרי ירידתה לעולם הזה שצריכה לשוב כו' כמ\"ש במ\"א. ובמקום שבעלי תשובה עומדים אין צדיק גמור כו'. כי בחינת רחמים רבים שלמעלה מעלה הוא המתגלה בבחי' בעל תשובה. דהיינו אחר ירידת הנשמה לעוה\"ז שאז הרחמנות גדולה מאד (משא\"כ קודם בואה היא בבחינת צדיק גמור) דוקא ולכן אמרו רז\"ל אין עומדים להתפלל אלא מתוך כובד ראש. ופירש רש\"י הכנעה דהיינו לעורר רחמים רבים על נצוץ אלהות כו' שעל ידי זה מעורר רחמים רבים למעל' ממקור הרחמי' ולהמשיך בחינת חנון ורחום להיות גילוי הוי' בעסק התורה והמצות ולהיות אור אין סוף בתוכה כו' ולכן ירידה זו דוקא היא צורך עלייה:"],[86,"<b>וזהו<\/b> אשירה להוי' כי גאה גאה. כי ענין שירה הוא התעוררות בחינת שמחה דהיינו בחינת גילוי. כי עצבות ומרה שחורה היא קמיטת וכויצת החיות. והשמחה היא גילוי והתפשטות החיות כמו צהבו פניו כו'."],[86,"וגילוי זה הוא להיות גילוי בחינת הוי' מאור אין סוף ברוך הוא הסובב כל עלמין אדון הנפלאות כו'. ולהיות בחינת הוי' יו\"ד חכמה כו' הוא על ידי המשכת גילוי כי גאה גאה. גיאות היא בחינת נפלאות וגאה גאה הוא בחי' אדון הנפלאות דהיינו שיהא גילוי המשכת חסדו וטובו של מעלה מעלה בחינת רחמים רבים שלפני אצילות שבבחינה זו סוס ורוכבו רמה בים שגילוי בחינה זו היא למעלה מעלה מבחינת סוס ורוכבו שהם בחינת צירופי אותיות הדבור שבדחילו ורחימו כנזכר לעיל. כמו שגם הסוס על דרך משל אינו יכול לרוץ בים."],[86,"ולכן נאמר בקריעת ים סוף ואתם תחרישון. מה תצעק אלי וגומר. כי כדי שיהפך הים ליבשה דהיינו דעלמא דאתכסייא תהיה בבחינת עלמא דאתגלייא לשנות סדר ההשתלשלות הוא על ידי ירידה גדולה ועצומה מלמעלה מעלה מסדר ההשתלשלות מבחינת אין סוף ברוך הוא הסובב כל עלמין השוה ומשוה כו' אדון הנפלאות וגאה גאה עד שיהיה הכל בבחינת בטול כו'."],[86,"ולכן רמה יש בו שני פירושים. לשון התרוממות והעלאה. ולשון השלכה שהוא מלמעלה למטה כי היא בחינת גילוי אור אין סוף ⟦סג,ד⟧ב\"ה הסובב כל עלמין ומעלה ומטה שוין."],[86,"ומשם נמשך עזי וזמרת יה י\"ה הם בחי' עלמין סתימין וזמרת מלשון וכרמך לא תזמר שהוא לשון כריתה. וכמו החוצב אבן מההר וכך נחצבו אותיות י\"ה מאדון הנפלאות וגאה גאה להיות בבחי' גלוי וחציבה זו היא בבחי' עזי בחי' גבורות להיות בחי' אנת חכים כו'. שזהו ענותנותו והן הן גבורותיו וצמצומים כו' גם צריך להיות בחי' צמצום שלא ילך השפע למותרות כנ\"ל."],[86,"ואח\"כ נעשה בחי' זה אלי כו'. בחי' גלוי הנרמז בו\"ה וזהו ואנוהו. אך גלוי זה יהיה לעתיד לבא למחר לקבל שכרם אבל היום לעשותם. וזה שכתוב ואמר ביום ההוא הנה אלקינו זה קוינו לו. פי' קוינו מלשון קוין והמשכות שאנחנו עשינו את הקוין והמשכות של שם הוי\"ה להיות בבחי' גלוי יו\"ד קוצא לעילא וקוצא לתתא. ה' ג' קוין ורוחב כו'. וע\"ז נאמר אמרו צדיק כי טוב שעל ידי הצדיק נמשך טוב ה' לכל וגו':"],[87,"<b>לסוסתי ברכבי פרעה דמיתיך רעיתי.<\/b> הנה רעיתי נמשלה לסוסי פרעה כמו שפרעה העמיד תחלה סוסים נקבות ואח\"כ היפך זכרים קודם לנקיבות כמ\"ש בזהר פ' בשלח (ד' מז) כמו\"כ בשעת יציאת מצרים נאמר וה' הולך לפניהם יומם וגו'. ואח\"כ בשעת קריעת י\"ס נאמר ויסע מלאך האלקים ההולך לפני מחנה כו' וילך מאחריהם כו'. הנה צריך להבין מהו המשל והנמשל שנמשלה רעיתי לסוסי פרעה. הנה אותיות נקראו סוסים כמו הסוס שהאדם רוכב עליו ומוליכו כפי רצונו ואעפ\"כ הסוס מוליך את האדם למקום רחוק מאד אשר בלתי אפשר להגיע לשם בלי סוס. כמו\"כ השכל מנהיג את האותיות ורוכב עליהם שלפי ערך השכל כך הוא הדבור אעפ\"כ ע\"י האותיות מתעלה למעלה יותר מה שאין השכל יכול להשיג כלל."],[87,"והיינו ע\"י אותיות התפלה. אך אעפ\"כ צ\"ל התבוננות ג\"כ. אם לא מי שערכו פחות מלהתבונן כלל שלזה בהכרח להעמיק אף בהאותיות לבד כמ\"ש בא אתה וכל ביתך אל התבה וע\"י האותיות יכול לעלות כאשר יבואר לקמן בעז\"ה. אך אעפ\"כ כתיב לא בגבורת הסוס יחפץ כו' שאעפ\"כ אין רצון וחפץ ה' שורה בבחי' האותיות כנ\"ל שהם רק בחי' שוקיים כ\"א רוצה ה' את יראיו כו':"],[87,"<b>והנה<\/b> יש ב' מיני אותיות אותיות זכרים ואותיות נקבות אותיות נקבות היינו ההעלאה שממטה למעלה ע\"י האותיות הנ\"ל באתעדל\"ת ועי\"ז באתעדל\"ת אתעדל\"ע כי רוח אייתי רוח ואמשיך רוח (כי דרכו של איש לחזר אחר אשה) המשכה מלמעלה למטה בבחי' סובב שהוא בלי גבול דלית מחשבה תפיסא ביה למעלה מהשגה להיות בחי' גלוי למטה ע\"י סוסים זכרים והיינו באותיות התורה להיות השמים והארץ אני מלא ממש. דהנה לכאורה תמוה לפעמים כתיב מכה\"א כבודו שאינו רק כבודו ולא מהותו ועצמותו ולפעמים אמר השמים והארץ אני מלא דהיינו מהו\"ע שהוא בחי' אני ממש. אך שניהם אמת שבאמת אני מלא ממש. אך איך יוכל להתלבש בעולם הגשמי והשפל ומלא קליפות זהו ע\"י שמלא כל הארץ כבודו ואין כבוד אלא תורה כבוד בגימ' ל\"ב והם ל\"ב נתיבות החכמה והיא חכמת התורה כי אורייתא מחכמה נפקת ועי\"ז יוכל להיות את השמים ואת הארץ אני מלא ממש ע\"י התלבשותו באותיות התורה שהם אותיות זכרים המשכה מלמעלה למטה וכמארז\"ל כל היושב ושונה הקב\"ה קורא ושונה כנגדו היינו מה שהוא קדוש ומובדל שאף בחי' חכמה נחשבת אצלו כבחי' עשי' גשמיית כמ\"ש כלם בחכמה עשית ויומשך ויתגלה למטה ע\"י אותיות התורה."],[87,"וזהו שעל מתן תורה נאמר כי תרכב על סוסיך כו'. והיינו בחי' ⟦סד,א⟧סוסים זכרים הנ\"ל. וזהו מדלג על ההרים מקפץ כו' שהוא בבחי' דילוג ממקום למקום והיינו המשכה מלמעלה מבחי' סובב שיומשך ויתגלה למטה כמ\"ש וירד ה' על הר סיני וכל העם רואים את הקולות כו'."],[87,"והנה זה לעו\"ז עשה האלקים כמו שבקדושה יש ב' בחי' סוסים הנ\"ל אתוון נוק' ואתוון דכורין מלמעלה למטה וממט' למעלה. כמו\"כ בקליפות יש ג\"כ ב' בחינות האותיות והיינו שע\"י התקשרותו להבלי עולם בדב\"ט ומכ\"ש לה\"ר והוא בחי' אותיות נקבות הנה האותיות מוליכים אותו למקום רחוק מאד."],[87,"והיינו לעומק הקליפות בחי' מקיף שלהם שנק' פרעה עורף כו' להמשיך עליו המשכה מלמעלה מבחינת המקיף שלהם להקיפו ולהלבישו והוא בחי' הבל ורעות רוח ונעשים לבושים צואים עליו והוא בחי' סוסים זכרים אותיות זכרים שנעשים ע\"י אותיות נקבות הנ\"ל כי בההפוך אמר ג\"כ רוח אייתי רוח וכו'."],[87,"והנה פרעה רדף אחר ישראל בשעת יצ\"מ כמ\"ש וירדף פרעה שרצה להוריד ולהמשיך את נש\"י לתוך עומק הקליפות. וע\"כ העמיד סוסים נקבות תחלה בכדי שעי\"ז יהי' המשכה מלמעלה ג\"כ מעומק הקליפות כי דרכו של איש כו'. אך הקב\"ה הפך ועשה את הסוסים שני אותיות האלו באלקות בכדי להיות המשכת אלקות למטה כנ\"ל. וזהו וה' הולך לפניהם יומם כו' ואח\"כ בשעת קי\"ס נעשה להפך ויסע מלאך וילך מאחריהם כנ\"ל:"],[87,"<b>והנה<\/b> כ\"ז הוא ע\"פ תורה. וכמו\"כ הוא ע\"פ עבודת ה' כי הנה בכל נפש ישראל צ\"ל בכל יום בחי' יצ\"מ וקי\"ס כמ\"ש למען תזכר את יום צאתך מארץ מצרים וגו'. וכמארז\"ל בכל יום יהיה בעיניך כאלו היום יצאת מאמ\"צ וגם בק\"ש אומרים בכל יום אני הוי\"ה אלקיכם כו' מארץ מצרים כו' וגם באמוי\"צ נאמר וים סוף להם בקעת כו' שצ\"ל בכל יום שני בחינות הנ\"ל כי כל העולמות נק' מצרים שהם מבחי' מצרים וגבולי' כמו מן הארץ לרקיע מהלך ת\"ק שנה כו' וכן שית אלפי שנין הוי עלמא כו' וגלות מצרים נק' ההתקשרות בזה העולם הגשמי והמוגבל ומלך מצרים נק' השכל של הבלי העולם."],[87,"וכשנעשה התקשרות לזה העולם כ\"כ בחוזק עד שהוא בלי שכל כלל בלי טעם ודעת נק' אז וימת מלך מצרים ואזי ויאנחו בנ\"י מן העבודה ויזעקו שנעשה צעק לבם בק\"ש בבחי' ובכל מאדך שהוא בלי גבול דהיינו לצאת מן החושך וגבול הנק' מצרים רק להיות צעק לבם למהותו ועצמותו ממש והוא בחי' יצ\"מ. אך איך יבא לבחי' בכל מאדך הנ\"ל. הנה זהו ע\"י התבוננות בפסוד\"ז מב\"ש וכו'."],[87,"והעיקר הוא בברכות ק\"ש בשתים שלפניה כו' והיינו בורא קדושים ישתבח שמך לעד. הנה לעד הוא בלי גבול. כי הנה הארץ הגשמית היא בבחי' גבול ממש אבל ברוחניות והיינו מלאכים ונשמות הם בלי גבול ממש כמ\"ש היש מספר לגדודיו כו' שהם בלי גבול."],[87,"ועי\"ז ישתבח שמך לעד שחיותם אינו אלא מבחי' שמו לבד שאינו כמו כח הפועל בנפעל שמתלבש ממש בנפעל בבחי' שינוי אבל לפניו אין שינוי כלל. כמ\"ש אני הוי\"ה לא שניתי כו' המרומם לבדו מאז שכמו שקודם בריאת העולמו' היה הוא מרומם לבדו כן עתה הוא בלי שינוי כלל המתנשא מימו\"ע רק חיות כל העולמות אינו אלא מבחי' שמו נק' עליהם שהוא מלך עליהם כמאמר אלקים חיים ומלך עולם היינו שמחיה כל העולמות רק בבחי' שהוא מלך עליהם שמו לבד ואעפ\"כ הוא בלי גבול ששמו הוא ג\"כ בלי גבול. וזהו בורא קדושים ישתבח שמך לעד כו' כנ\"ל אבל מהותו ועצמותו רם ומתנשא כו':"],[87,"<b>והנה<\/b> אחר שיתבונן כל זאת ואזי ממילא יתעורר מזה בק\"ש להיות ואהבת כו'. בכל מאדך בלי גבול לצאת מהחשך כו' ורק ⟦סד,ב⟧להיות צעק לבם למהותו ועצמותו ממש באתעדל\"ת והוא בחי' אתוון נוקבין ועי\"ז באתעדל\"ת אתעדל\"ע לעורר האהבה למעלה ג\"כ והוא פ' שניה שבק\"ש שהוא לאהבה את ה' אלקיכם וגו' דאינו לשון שם דבר כמו לאהוב רק לאהבה לעשו' אהבה למעלה שיומשך אלקות למטה הוי\"ה אלקיך ממש. דהנה לאו מכל אלין מדות כלל ואיך יהיה אהבה למעל' רק ע\"י אתעדל\"ת בבחי' אהבה מלמטה אתוון נוקבין ואהבת וגו' אזי ממילא נעשה אהבה למעלה ג\"כ כי רוח אייתי רוח כו'."],[87,"וזהו והחיות רו\"ש שהוא אותיות נקבות ואותיות זכרים וזה נקרא אותיות זכרים דהיינו המשכה מלמעלה למטה שיהיה הוי\"ה אלקיך ממש ועי\"ז יכולים לומר אח\"כ ונתתי עשב בשדך ונתתי מטר ארצכם וגו' דלכאורה איך אומרים ונתתי כו' אלא רק מחמת שנמשך מלמעלה להיות הוי\"ה אלקיכם ממש וע\"י התלבשותו באותיות התורה שהן אתוון דכורין שהקב\"ה יושב ושונה כנגדו שקדוש ומובדל ממש מתלבש באותיות התורה להיות ואשים דברי בפיך ממש כמ\"ש ודברת בם ולא נאמר ודברת אותם והיינו בם ממש מתניתין מלכתא מאן מלכי רבנן שהוא כמו מלך שגוזר ומצוה על מדינתו ברצונו כך הם רבנן גוזרים על כשר פסול טמא וטהור שהוא דברי בפיך ממש וזהו הדברים האלה אשר אנכי מי שאנכי מצוך כו' ועי\"ז יכולים לומר אח\"כ ונתתי מטר כו' ובק\"ש חותמים אני הוי\"ה אלקיכם אשר הוצאתי אתכם מארץ מצרים שהוא בחי' יציאה מן מצרים וגבולים ורק להיות הוי\"ה אלקיכם כו'. והוא אתעדל\"ע אותיות זכרים שבאים אחרי אתעדל\"ת אותיות נקבות כי דרכו של איש כנ\"ל:"],[87,"<b>אך<\/b> הנה יש עוד אתעדל\"ע שהם אותיות זכרים שהם באי' שלא על ידי אתעדל\"ת כלל שהם אותיות נקבות. והוא בחי' קריעת ים סוף כי הנה ענין ים הוא שכל מה שיש ביבשה יש בים שכל הברואים שיש בים ישנם ג\"כ ביבשה אלא שבים הם נעלמים ומכוסים וביבשה הם באתגלייא כמו\"כ למעלה ג\"כ יש בחי' ים ובחי' יבשה עלמא דאתכסייא ועלמא דאתגלייא וכמו\"כ באדם שהוא עולם קטן יש ג\"כ שכל ומדות מחשבה דבור ומעשה. שכל הוא בחי' עלמא דאתכסייא כי הוא בהעלם ומדות הם בחינת עלמא דאתגלייא שהם בחי' גלוי לגבי השכל."],[87,"ומחשבה נק' ג\"כ בחי' גילוי לגבי השכל ודבור הוא יותר בחי' גילוי אף לגבי המחשבה כמו\"כ למעלה יש מחשבה ואף דכתיב כי לא מחשבותי מחשבותיכם עכ\"ז הוא כערך האדם למטה שמחשבתו נק' העלם לגבי דבורו. כך למעלה יש בחי' העלם שהוא בחי' מחשבה. כמ\"ש בזוהר כמה מחשבתין אית כו' שהוא מחשבה למחשבה שמה שנק' העלם לגבי למטה הימנו נק' בחי' גילוי לגבי מדרגה העליון ממנו וכן גבוה מעל גבוה שהתחתון הוא בחי' גילוי לגבי העליון ממנו שהוא בחי' העלם ממנו וזה נק' השתלשלות העולמות שהוא כמו שלשלת שכ\"א אחוז בחבירו. כמו כן השתלשלות כל העולמות שהוא גבוה מעל גבוה עילה ועלול העלם וגילוי כו' אבל לגבי מהותו ועצמותו עצמות המאציל שלמעלה מעלה מהשתלשלות העולמות שהם נעלמים אין שייך לפניו כלל מעלה ומטה גם חשך לא יחשיך ממך ולילה כיום יאיר כו':"],[87,"<b>והנה<\/b> בשעת קי\"ס הי' התגלות מהותו ועצמותו ממש שלמעלה מהשתלשלות ועי\"ז ים ויבשה שוין ממש ונעשה מים יבשה מהעלם גילוי וזהו הפך ים ליבשה בנהר יעברו ברגל ויעברו בתוך הים ביבשה דייקא שההעלם נעשה גילוי ע\"י גילוי עצמותו שהעלם וגילוי שוין ממש."],[87,"וזהו שם נשמחה בו ממש במהותו ועצמותו ממש והוא בחי' שמחה של מצוה. כי הנה כתיב תחת אשר לא עבדת את ה' אלקיך בשמחה וכו' מרוב כל שרוב כל נק' השתלשלות כל העולמות ⟦סד,ג⟧שהם רוב מאד כגלדי בצלים גבוה מעל גבוה כו' אבל השמחה של מצוה היא בבחי' עצמותו ממש שהוא מרוב כל למעלה מהשתלשלות כל העולמות."],[87,"וזהו ושמחת לפני הוי' אלקיך שהוא בחי' שמחה של מצות התורה שהוא לפני הוי' ממשיכי' כו'. כי הנה אנו אומרים אק\"ב כו' דרמ\"ח מצות הן רמ\"ח אברים דמלכא והוא כמשל אברים של אדם הנה הנשמה אין יכולים לאוחזה ולתופסה כלל רק אעפ\"כ כשנוטלין את האדם בידו הימנית או השמאלית ומושכין אותו ממקום למקום. אזי נמשכה הנשמה ג\"כ ממקום למקום אף שהנשמה בעצמה אין יכולים לאוחזה כלל רק שע\"י שהתלבשות הנשמה היא בהאברים עי\"כ נמשכה הנשמה ג\"כ ממילא."],[87,"וכמו\"כ המצות הם אברין דמלכא כמו חסד דרועא ימינא שע\"י הצדקה וחסד שנותנים למטה לעני ממשיכי' את עצמותו כביכול ע\"י התלבשותו בבחי' חסד דרועא ימינא וכן גבורה דרועא שמאלא וכמארז\"ל איזהו גבור הכובש את יצרו כמו לכבוש איזה תאוה כו' שעי\"ז ממשיכים אותו מלמעלה ג\"כ עי\"ז. גבורה דרועא שמאלא."],[87,"וכן ת\"ת עמודא דאמצעיתא שהוא בחי' תורה שהוא כמו שנוטלין את האדם בכל גופו. ועי\"ז מוליכים אותו למקום שרוצים כמו\"כ ע\"י תורה ממשיכין את עצמותו כביכול למטה. וזהו שמחה של מצוה שהוא מתן שכרן של מצות שהוא בחי' גלוי עצמותו שהי' אז התגלות בשעת קי\"ס וזהו שם נשמחה בו בעצמותו ממש והוא בחי' אתעדל\"ע בחי' אותיות זכרים שבא שלא באתעדל\"ת כלל כי אין אתעדל\"ת יכול לעורר כלל. וזהו ויאמר ה' אל משה מה תצעק אלי בעתיקא תליא מילתא שהוא עצמות המאציל העליון שאין אתעדל\"ת יכול לעורר כלל אלא ה' ילחם לכם ואתם תחרישון:"],[88,"ביאור על הנ\"ל"],[88,"<b>וה' הולך לפניהם יומם.<\/b> וה' הוא וב\"ד היינו שכינה שהי' בשעת יצ\"מ הולך לפני מחנה ישראל ואח\"כ בשעת קי\"ס ויסע כו' וילך מאחריהם שנעשה שכינתא לאחוריהם דישראל. וביאור הענין הנה ענין ב' סוסים נקבות וזכרים והיינו אתעדל\"ת ואתעדל\"ע אתעדל\"ת נקראים סוסים נקבות ואתעדל\"ע נקראים סוסים זכרים. כי הנה עולמות התחתונים נקראים בשם נוקבא בחי' מקבל כמו שהנקבה מקבלת מן הזכר כן עולם התחתון מקבל ההשפעה מלמעלה שהוא בחי' דכר."],[88,"והנה כמו הנקבה שמקבלת מהזכר מוכרח להיות תמיד התעוררות הנקבה מקודם ועי\"ז משפיע הזכר אליה כי דרכו של איש לחזר אחר אשה. כמו כן ע\"י אתעדל\"ת מעולמות התחתונים והוא בחי' סוסים נקבות בחי' מקבלים מעוררים ההשפעה מלמעלה בבחי' סוסים זכרים."],[88,"והנה מלכות דאצילות מתלבשת בבי\"ע שהיא מדרגה התחתונה אזי תמיד היא עולה להתעורר למעלה בבחי' אצילות לקבל ההשפעה מלמעלה כמ\"ש אלקים אל דמי לך. למען יזמרך כבוד כו'. והוא נק' אתעדל\"ת ועי\"ז נעשה ממילא אתעדל\"ע להיות השפעת אלקות בבחי' מלכות דאצילות וחוזרת ומתלבשת בבחי' אברהם חסד כו' ובנשמות ומלאכי' להיות גילוי ההשפעה בבי\"ע כפי האופן אתעדל\"ת."],[88,"ולכן פעמים עליית המלכות הוא בבחינת שירה כמ\"ש אשירה לה' כו' בכדי שיהי' השפעה מלמעלה ג\"כ בבחי' שיר ולפעמים ההעלאה בבחי' זמרה כמ\"ש למען יזמרך כו' ולפעמים בבחי' בקשה שתהיה ההשפעה מלמעלה באופן האתעדל\"ת כי אתעדל\"ע הוא ממש כפי אופן האתעדל\"ת."],[88,"וזהו בחינת יצ\"מ. כי הנה בי\"ע נק' מצרים שהם בבחינת מצרים וגבולים כי עולם העשיי' הוא בגבול ממש מהלך ת\"ק שנה שית אלפין כו'. וכן יצירה ⟦סד,ד⟧ובריאה הם ג\"כ בבחינת גבול להשגתם מאחר שהם נבראים מחודשים ואף ג\"ע העליון שבבריאה וג\"ע התחתון שביצירה הכל הוא בבחי' גבול משא\"כ עולם האצילות נק' עולם הא\"ס שהמשכת אור א\"ס שבעולם האצילות הוא בלי גבול כי איהו וחיוהי וגרמוהי חד בהון כו' רק מאצילות לבריאה נעשה הפסק הפרסא והמעקה והגג שעי\"ז הם בבחי' מצרים וגבול:"],[88,"<b>והנה<\/b> ארז\"ל גלו למצרים שכינה עמהם כמ\"ש אנכי ארד עמך מצרימה שבחינת מלכות דאצילות מתלבשת בבי\"ע ממש והוא גלות השכינה גלות מצרים שהשכינה שהיא מלכות דאצילות היא בגלות בתוך מצרים וגבולים."],[88,"ויצ\"מ היא שיוצאת מן הגלות דבי\"ע ליכלל למעלה בבחינת אצילות בבחינת אתעדל\"ת הנ\"ל לעורר למעלה שתהי' השפעת אלקות למטה וע\"י זה נעשה אתעדל\"ע להיות גילוי אלקותו בבחינת מלכות להתפשט בבי\"ע בבחינת אברהם שהוא בע\"ג וכן במלאכי' כו' ופרעה רצה להמשיך להפוך מן הקליפות ע\"כ העמיד ג\"כ סוסים נקבות תחלה שהוא אתעדל\"ת בכדי שילכו הזכרים היינו אתעדל\"ע ממילא אחר הנקבות כי דרכו של איש כו' וכן בעבודה בק\"ש ע\"י התבוננות שמע ישראל הוי\"ה אלקינו או\"א והיינו מאין ליש ואיך שהיש בטל לאין בתכלית."],[88,"והיינו יחוד או\"א וכדומה בהתבוננות באריכות. אזי נעשה אתעדל\"ת לצאת מהחשך וגלות הגוף ולהיות ואהבת כו' בכל מאדך בלי גבול להיות נכלל למעלה בבחינת אצילות שהוא בלי גבול וע\"י זה נעשה ממילא אתעדל\"ע בפ' שניה שהוא לאהבה את ה' אלקיכם שיהיה אהבה מלמעלה לימשך למטה שיהיה ה' אלקיכם ממש שיכולים לומר אח\"כ ונתתי מטר כו' ונתתי עשב כו', ובסוף הק\"ש חותם אני ה' אשר הוצאתי אתכם מארץ מצרים שהוא בחי' יציאת מצרים וגבולים כנ\"ל:"],[88,"<b>אך<\/b> הנה האתעדל\"ע שבא ע\"י אתערותא דלתתא הנ\"ל שהיא בחי' יציאת מצרים כנ\"ל אינו אלא המשכה מלמעלה מבחי' חכמה דאצילות כי אין האתעדל\"ת יכול לעורר כלל למעלה מבחינת חכמה דאצי' כי אבא יסד ברתא כמו הדבור שנמשך מבחי' חכמה שהיא ראשית ומקור הדבור ע\"כ אין בכח הדבור לעלות למעלה מבחי' חכמה. כמו\"כ חכמה דאצי' נק' אבא שהוא מקור וראשית הגילוי ראשית ההשתלשלות ומל' נק' ברתא. ע\"כ אין בכח מל' דאצי' לעלות ולעורר באתעדל\"ת הנ\"ל למעלה מבחי' חכמה דאצי'. כמשל התנוק שנמשך אחר אביו מחמת שהוא מקורו. כמו\"כ עליית המל' אינה אלא לבחי' חכמה שהוא ראשית הגלוי באתעדל\"ת כנ\"ל."],[88,"ועי\"ז רוח אייתי רוח ואמשיך רוח כו' להיות אתעדל\"ע להיות השפעה והמשכה מבחי' חכמה דאצי' לבחי' מל' להתפשט בבי\"ע אבל למעלה מבחי' חכמה בחי' כ\"ע אין אתעדל\"ת יכול לעורר כלל כי הוא למעלה מהשתלשלות העולמות. והיינו מבחי' חכמה שנק' ראשית לבחי' בינה ומבינה למדות כו'. כי הנה אף שחכמה היא למעלה מבינה וכן בינה ממדות כו'. עכ\"ז יש להם ערך זה לזה אבל בחי' חכמה לגבי בחי' כ\"ע נאמר אין ערוך לך שאין ערוך כלל שהוא בחי' אין ממש כמ\"ש והחכ' מאין (ממש) תמצא שהוא בחי' כתר שהוא למעלה מהשתלשלות כלל, והוא בחינת גולגלתא דאריך בחי' מל' דא\"ס והוא כמשל הכתר למטה שהוא על הראש ואין לה שייכו' כלל עם הראש כמו היד והרגל שאף שהן למטה במדרגה מן הראש עכ\"ז יש להם שייכות עם הראש. אבל הכתר הוא על הראש כו'. כמו\"כ כ\"ע אין לו שייכות כלל עם בחי' חכמה שאין ערוך כלל ע\"כ אין אתעדל\"ת יכול לעורר כלל לבחי' כתר רק הוא דבר שחל ממילא שבחי' כתר מתגלה ממילא בלי אתעדל\"ת כלל כמו בשבועות מתגלה ⟦סה,א⟧בחי' הכתר כו'. וזהו בחי' קריעת ים סוף שהי' אז התגלות בחי' כ\"ע. כמ\"ש ויאמר ה' (ז\"א) אל משה מה תצעק אלי. שאין הדבר תלוי בי אלא בעתיקא תליא בחי' גולגלתא הנ\"ל בחי' כתר ולגבי בחי' כתר אין אתעדל\"ת יכול לעורר כלל. וזהו ה' ילחם לכם ואתם תחרישון."],[88,"וכמאמר הזוהר לא תתערון מידי שאם תתערון אזי אין יכול להיות אתעדל\"ע אלא כפי האתעדל\"ת שאינו אלא מבחי' חכמה אבל אז היה התגלות בחי' כתר שהוא מתגלה ממילא בלי אתעדל\"ת כלל ולכן תחרישון. ועי\"ז נעשה קי\"ס שהפך ים ליבשה כו' שנעשה מהעלם גלוי דאו\"א נק' עלמא דאתכסייא וזו\"נ נק' עלמא דאתגלייא ואיך יהי' ההעלם לגילוי רק מחמת שהיה התגלות בחי' כתר הנ\"ל שלמעלה מהשתלשלו' ששם העלם וגלוי שוין כחשכה כאורה ויכול להיות מהעלם גילוי:"],[88,"<b>וזהו<\/b> שם נשמחה בו שהוא בחי' שמחה של מצוה שהוא ג\"כ התגלות בחי' כתר הנ\"ל. והוא בחי' תענוג המצות כמו שהם בעצם בבחי' רצה\"ע כי הנה אורייתא מחכמה נפקת והיינו הפירוש של המצות שהם מבחינת חכמה אבל שרש המצות הוא מבחי' כתר חיוורתא דגלגלתא שמשם נמשכין שית מאה ותליסר ארחין בז\"א שהם ארחות הוי\"ה."],[88,"והם התרי\"ג מצות עם ז' מצות דרבנן הוא בגימטריא תר\"ך בחי' כתר ונמשכים למטה במצות גשמיים בבחי' כלים דוקא ולכן נקראו המצות אברים דמלכא שהוא כמו שמוליכין את האדם ממקום למקום בידו הימנית כו'."],[88,"ועי\"ז מתנענע הנשמה ג\"כ אף שאין יכולי' לאוחזה ולתופסה כלל. אך אעפ\"כ ע\"י התלבשותה באברים אזי כשמנענעין את ידו כו' ממילא מתנענע הנשמה ג\"כ. כמו\"כ למעלה אף שבחי' כתר הנ\"ל הוא למעלה מהשתלשלות ואין יכולים לעורר כלל באתעדל\"ת רק דוקא ע\"י התלבשותו במצותיו שהם כלים ואברים לבחי' כתר הנ\"ל חסד דרועא ימינא אזי ע\"י חסד שעושים למטה מוליכים אותו בדרועא ימינא כו'."],[88,"וכן גבורה כו' וכן ת\"ת עמודא דאמצעיתא שהוא המצו' של תורה שהוא ג\"כ מבחי' כתר הנ\"ל. וזהו שם נשמחה בו שהוא בחי' שמחה של מצוה הנ\"ל שהי' אז התגלות בחי' כתר הנ\"ל ועי\"ז נעשה קי\"ס כנ\"ל:"],[88,"<b>וזהו<\/b> שמתחלה בשעת יציאת מצרים היה ו\"ה הוא בחי' מלכות דאצי' מקור נשמות ישראל הולך לפניהם שנשמות ישראל נמשכין אחריה שביציאת מצרים שמל' דאצי' עולה מן הגלות דבי\"ע ונכלל למעלה באתעדל\"ת כנ\"ל."],[88,"ועי\"ז נשמות ישראל ג\"כ עולים ממצרים ליכלל למעלה בבחי' אצילות ונמשכים אחר כנס\"י. אבל בשעת קי\"ס שהיה התגלות לישראל בחי' כתר עליון כנ\"ל שאין מל' יכול לעלות כ\"כ למעלה שעליית המל' אינה אלא עד בחי' חכמה כנ\"ל רק ביוכ\"פ בנעילה שאז עליית המל' עד הכתר וגם זאת אינה אלא לדיקנא דאריך אבל לא לבחי' גלגלתא אזי ישראל נעשו אז למעלה מבחי' שכינה מל' דאצי'."],[88,"וזהו עד יעבור עמך הוי\"ה שנעשית למעלה מהוי\"ה בהתגלות בחי' כתר כנ\"ל. ולכן כתיב ויסע מלאך ה' היינו שכינה הנ\"ל ההולך לפניהם שהי' בשעת יצ\"מ לפני מחנה ישראל שנשמות נמשכו אחריה כנ\"ל. וילך מאחריהם שבשעת קי\"ס נעשו ישראל למעלה וכנס\"י נעשה לאחריהם וד\"ל:"],[89,"<b>ויאמר משה אכלהו היום כו'.<\/b> להבין למה לא ירד המן בשבת והלא כל השפעות שבעוה\"ז הגשמי אינן נעצרין אפי' בשבת והכל נשפע מלמעלה אין לך עשב כו'. וגם מהו אכלהו היום והלא כל הימים אכלו. אך הנה כתיב הנני ממטיר לכם לחם מן השמים כו'. למען אנסנו הילך בתורתי אם לא. ולהבין למה ⟦סה,ב⟧הקדים המן לקבלת התורה למען אנסנו אם יוכל להיות קבלת התורה. ואיזה שייכות יש לנסיון זה על התורה. וגם מהו לשון הילך בתורתי הל\"ל היקיימו תורתי:"],[89,"<b>אך<\/b> הנה זאת התורה היא בחי' אותיות. ס\"ר אותיות כנגד ס\"ר נשמות. והענין כי אותיות מלשון אתא בקר שהוא לשון המשכה מלמעלה למט' מבחי' סוכ\"ע בבחי' ממכ\"ע. כי לכן נק' אותיות סוסים כי תרכב על סוסיך כו'. כי ידוע שהתהוות העולמות מאין ליש היא בחי' הארה דהארה כי נשגב שמו לבדו שמו היינו בחי' מלכותו שהיא מחשבה הקדומה אנא אמלוך שממנו נבראו העולמות ושמו הוא ג\"כ בבחי' לבדו רק הודו מבחינת שמו על ארץ ושמים שבריאת שמים וארץ אינו כמעשה בו\"ד שהכח הפועל הוא בנפעל והשכל המלובש במעשה זה לא היה בו קודם שהתחיל לעשות. ומכ\"ש האותיות. אבל בהשי\"ת לא שייך זה כי אני ה' לא שניתי כתיב ואתה הוא קודם שנברא העולם בלי שינוי."],[89,"והנה ההמשכה להיות הארה דהארה זו הוא ע\"י וירם קרן לעמו לבני ישראל עם קרובו שהם הממשיכים כו'. וכמארז\"ל במי נמלך. ונק' בנאים שעוסקים בבנינו של עולם. ולכן ארז\"ל כשם שא\"א לעולם בלא רוחות כך כו'."],[89,"ולהבין איך המשל דומה לנמשל. אלא הענין כי רוחות הם ו\"ק צפון ודרום כו' שהם עיקר העולם שזהו גבול המקום ואם לא הרוחות לא הי' בחי' מקום כלל אלא כמ\"ש הנה מקום אתי שהוא בבחי' בטול כו'. כך א\"א לעולם בלא ישראל שהרי המשכת אור א\"ס להיות מתלבש בבחינת מקום הוא ע\"י ישראל שהם הממשיכים כו'."],[89,"והיינו ע\"י ששה משמותם על האבן האחת כו'. בחינת ו\"ק וגם להיות כ\"א כלול מיו\"ד ויו\"ד מיו\"ד עולה עד ס\"ר כנגד ס\"ר נש\"י וכל נשמה יש לה אות אחת בתורה שהיא ממשכת אותו אות."],[89,"וע\"ז נאמר ה' בצאתך משעיר כו' ארץ רעשה כו'. שעיר היינו בחי' שערות שהן הארה בעלמא כי אף שגדילות מהמוח מ\"מ אם יחתוך אותו אינו כואב. והוי\"ה הוא המחיה ומהוה תמיד מאין ליש. בצאתך בבחי' גילוי במתן תורה הוא מבחי' שעיר כי כדי להיות המשכה מסוכ\"ע למטה אין לזה דמיון ומשל אחר רק כמו השפע היוצא בבחי' שערות וכל התגלות זו היה ע\"י מתן תורה כמו שסיים ארץ רעשה שנעשה בחי' בטול והוא ע\"י ישראל שהם הממשיכים ה' משעיר להיות ארץ רעשה זה סיני היינו בקבלת התורה:"],[89,"<b>אך<\/b> הנה גם המלאכים בקשו תנה הודך על השמים אלא שישראל שבאותו הדור זכו לזה ע\"י שיעבוד מצרים בחומר ובלבנים שעי\"ז אתכפיא סט\"א. אך הנה בכל יום אנו מברכין נותן התורה ובכל יום חייב אדם לראות את עצמו כאלו יצא ממצרים ועד\"ז תקנו סדר התפלה להיות אתכפייא ובטול רצון נה\"ב לאהבה את ה' בק\"ש בכל לבבך ובכל נפשך ממש ונק' בזוהר לאשתאבא בגופא דמלכא כי לכן נאמר אכלתי יערי עם דבשי אכילה שנכלל באברים כמו המאכל שמתעכל ונהפך לדם הוא הנפש וכך צ\"ל התהפכות הנפש לאלהות ממש."],[89,"והנה כמו שבמאכל המובחר מתעכל ונהפך לדם והפסולת נדחה לחוץ והיינו כי המאכל נלקח מהע' שרים כו' וצריך לברר כך הנה כתיב מצרף לכסף כו' ואיש לפי מהללו שבמהללו בתפלה מצרף שהגו סיגים מכסף והמובחר נבלע באלקות ואהבת בכל לבבך כו'. והפסולת נדחה לחוץ בשמ\"ע סלח לנו ואשמנו להעביר פסולת ולדחותו:"],[89,"<b>אך<\/b> הנה יש ב' מיני אכילות של חול ושל שבת צדיק אוכל לשובע נפשו ובטן רשעים תחסר. כי אכילות של חול הוא להיות ⟦סה,ג⟧בירור ובטן רשעים תחסר ובחכמה אתברירו כי להיות מן המאכל נעשה דם הוא הנפש ובכח זה מתפלל ונמצא שהמאכל שהיה תחת ממשלת השרים נתהפך ולכן יש בו פסולת."],[89,"ואכילת שבת לשובע נפשו וקראת לשבת ענג. אז תתענג על ה' דא היא סעודתא דע\"ק כו' ואין נמשך בו פסולת כלל וא\"צ בירור. וכך יש הפרש בין תפלת החול שהוא בבחי' בירור כנ\"ל. אבל בשבת התפלה הוא שנמשך ענג וקראת לשבת ענג. כי ענין השבת כי בו שבת כמשל האדם שנח ממלאכתו שחוזר השכל למקורו שבשעת מלאכה היה השכל טרוד במלאכתו ואח\"כ כשנח חוזר כו'."],[89,"וכך כתיב שבת להוי' כי בחי' ה' שהוא בצאתך משעיר כו' להיות מאין ליש הנה בשבת חוזר למקורו אז תתענג על הוי\"ה למעלה מבחי' הוי\"ה ולכן אין אומרים סלח לנו בשבת שאין בו בירור כו':"],[89,"<b>והנה<\/b> להיות בחי' אלו בחול ובשבת הוא ע\"י המן כי במן נאמר ותעל שכבת הטל שהוא מבחי' טל שאין לו הפסק והוא מבחי' אתעדל\"ע שלמעלה מאתעדל\"ת ומזה נמשך הכח בנפש להיות אתעדל\"ת כי מוריד הטל ירידה זו צורך עליה היא להעלות הנשמה."],[89,"והנה במן נאמ' דבר יום ביומו למען אנסנו הילך כו' והנסיון הוא איש אל יותר ממנו עד בקר כי ארז\"ל כי מי שיש לו פת בסלו ודואג על למחר הוא מקטני אמנה שהוא בבחי' קטנות. אבל להיות הילך בתורתי בבחי' הליכה ממטה למעלה ומלמעלה למטה בתורתי באותיות התורה. כי כמו שיש אותיות התורה הממשיכות מלמעלה למטה. כך יש בחי' אותיות שממטה למעלה ונק' סוסים. סוסים זכרים וסוסים נקבות וכמו דאיתא בס\"י באותיות א\"ב שיש אותיות כך ויש כך כו'."],[89,"והליכה זו בבחי' אותיות שממטה למעלה הוא עד רום המעלות עד א\"ס ממש. ולכן צ\"ל דבר יום ביומו בכל יום יהיו בעיניך כחדשים כי נער הייתי גם זקנתי שרו של עולם אמרו. משא\"כ קמי קוב\"ה מי איכא זקנה מאחר שהוא אני ה' לא שניתי. ולכן עיני האדם לא תשבענה עיני האדם היינו עיניך יונים שהוא בחי' לאסתכלא כו':"],[89,"<b>וזהו<\/b> ענין המן שהיה מבחי' טל העליון בחי' אני ה' לא שניתי שלמעלה מהזמן כו'. ולכן היה צ\"ל דבר יום ביומו ולכן היום לא תמצאוהו בשדה. שדה היינו בחי' עולם ו\"ק מעלה ומטה מזרח כו' כי שבת היום לה' שבחי' שם הוי\"ה הוא ג\"כ בבחי' שבת שחוזר למקורו אלא אז תתענג על הוי\"ה שהוא אתעדל\"ע שאינו תלוי באתעדל\"ת וכמ\"ש ישא ה' פניו אליך כי למטה יש בחי' פנים ובחי' אחוריים. משא\"כ כשישא ה' פניו שם אין בחי' אחוריים כלל."],[89,"ולכן אכלוהו היום שהוא בחי' אכילה לשובע נפשו וקראת לשבת ענג. אבל בחול הגם שנמשך הטל ברדת טל על המחנה לילה. היינו בחי' קוצותיו רסיסי לילה קווצותיו בחי' שערות כמו קוצותיו תלתלים."],[89,"והיינו בחי' ה' בצאתך משעיר אבל בשבת ותעל שכבת הטל שהיה ביום. וזהו אכלוהו היום ולכן דוקא המן לבד לא ירד בשבת משא\"כ שאר השפעות שבעוה\"ז להיות כי בחי' עליית העולמות שבשבת זהו רק בפנימיות העולמות משא\"כ בחיצוניות העולמות הרי אין שום שינוי בשבת מבחול."],[89,"וזהו ההפרש בין המן לשארי השפעות ששאר השפעות נמשכים למטה בעוה\"ז מחיצוניות העולמות מהמזלות והשרים. משא\"כ המן הוא נמשך ממקום גבוה מאד מבחי' טל. ולכן נאמר ברדת הטל על המחנה לילה ירד המן עליו שנמשך ע\"י בחי' רסיסי לילה שהוא מבחי' שערות שזהו לפי שנמשך ממקום עליון שלמעלה מהשתלשלות עילה ועלול שלכך נמשך רק בבחי' שערות."],[89,"וע\"ד דוגמא מעין מה שנאמר ⟦סה,ד⟧במ\"ת הוי\"ה בצאתך משעיר משא\"כ שארי השפעות שנמשכים ע\"י המזלות בהן שייך השתלשלות עילה ועלול כי הם בחי' חיצוניות ובבחי' זו אין שום שינוי בשבת מבחול שחיצוניות העולמות אין להם עלייה דהעלייה בבחי' פנימיות וכמ\"ש כי שבת היום להוי\"ה."],[89,"וענין שביתה זו הוא מבחי' בצאתך משעיר שהוא ירידות וצמצומים למעלה מהצמצומים ולכך המן שנמשך מבחי' זו א\"א לו לירד למטה בשבת כי כדי שיומשך מבחי' המן למטה בשדה בגשמיות ממש א\"א כ\"א ע\"י צמצומים גדולים הנק' רסיסי לילה שעי\"ז יומשך השפעה עליונה זו למטה בגשמיות והרי בשבת היא השביתה ועלייה מבחינת צמצומים הנ\"ל:"],[90,"<b>להבין<\/b> ענין לחם משנה. שיש הפרש בין ע\"פ נגלה. ובין ע\"פ נסתר. שע\"פ נגלה צ\"ל זה על גבי זה. וע\"פ הנסתר צ\"ל זה בצד זה. צריך להקדים תחלה מה שנתקן בברכת המזון על הארץ ועל המזון שהטעם מה שחותמין בשתים מבואר בדברי רז\"ל ארץ דמפקא מזון."],[90,"וצריך להבין למה חותמין במזון כלל. וגם צ\"ל מה שמבואר בדברי רז\"ל ע\"פ ואכלת ושבעת וברכת זו ברכת הזן משה תקן. על הארץ זו ברכת הארץ יהושע תקן. הטובה זו ברכת בונה ירושלים שנאמר ההר הטוב כו'. ולמה בברכת הזן אין מזכירים כלל מעין ב' ברכות האחרות ובברכת הארץ מזכירים ג\"כ על אכילת מזון כו'. וגם מסיימין בה על הארץ ועל המזון:"],[90,"<b>אך<\/b> להבין כל הנ\"ל יש להקדים ענין כוונת אכילה ע\"פ כי על כל מוצא פי ה' כו'. שהפי' הוא מוצא פי הוי\"ה שבמאכל כו' ממאמר תדשא הארץ הוא המחיה כו'. והיינו בחי' נצוץ אלקות שמתלבש בלחם בהשתלשלות רבי רבבות מדרגות. וכמארז\"ל אין לך עשב כו'. וגבוה מעל גבוה כו'."],[90,"והנה להבין הלא גם האדם נשתלשל ממאמר נעשה אדם כו' ולמה האדם צריך ללחם ואין הלחם צריך לו. אך הנה פי' יחיה האדם לא קאי על נפש הבהמית לבדה כי הלא גם בהמה מקבלת חיות מן המאכל אלא קאי על נפש האלקית שנתוסף בה אור וחיות מהמאכל וזהו האדם בה' הידיעה."],[90,"ויובן בהקדים תחלה שרש ענין תהו ותקון כי שרש האדם הוא מבחי' תקון כי אדם בגימטריא שם מ\"ה שהוא שם מ\"ה החדש שהוא עיקר התקון. ושרש בהמות וחיות הם מבחי' תהו שקדם לתקון."],[90,"ושרש הדבר הוא כי הנה ידוע שבחי' תהו הוא בחי' נקודות זו תחת זו בלי התכללות שכאו\"א הוא מהות בפ\"ע ומזה נעשה ונמשך ברבוי השתלשלות מעילה לעילה עד שנתהוו דברים גשמיים כמו בהמות וחיות שאנו רואין בחוש שכל מין ומין יש לו טבע בפ\"ע. טבע הנשר הוא מבחי' רחמנות."],[90,"ושור הוא מגבורות שור נגח כו' ואין בהם התכללות כלל והטעם הוא כי ראשית מציאותם הוא מבחי' התהו שאין בהם התכללות וכל מדה היא מהות בפ\"ע. וכאו\"א אינו יכול לסבול חבירו."],[90,"וכמ\"ש וימת וימלך תחתיו היינו שלא היה באפשרי להתהוות ספירה אחרת רק בהעדר ובטול ספירה הקודמת לה. והכל מצד הרגשת הגוף מהותו של כאו\"א ומצד תוקף הרגשת עצמותו לא היה יכול לסבול חבירו שהוא הפך מהותו כמו חו\"ג שהם הפכים לא היה בהן התכללות והיה בהן שבירה. עד שברבוי השתלשלות בעילה אחר עילה נתהוו מהם דברים גשמיים כמו דצח\"מ."],[90,"והכל מפני שלא היה בהם הארת המוחין ולא היה בהם בחי' בטול. אבל בחי' התקון שהיא בחי' אד\"ם בחי' פרצוף בחי' הארת שם מ\"ה החדש במילוי אלפי\"ן יו\"ד לעילא יו\"ד לתתא וי\"ו באמצעיתא המחבר אותם להיות בהם בחי' התכללות."],[90,"ועיקר בחי' התכללות הוא מצד בחי' הבטול. דהיינו בחי' חלישת ⟦סו,א⟧הגוף הרגשת עצמותו. והיינו מבחי' שם מ\"ה שבחכמה שהוא ענין הארת המוחין להיות הנהגת המדות ע\"פ שכל דוקא."],[90,"וכמ\"ש לפי שכלו יהולל איש. ומצד בחי' כח מ\"ה שבחכמה שהוא הבטול בחי' אין נעשה בחי' התכללות לחבר ב' הפכים כמו חו\"ג יחד כו' והיינו מצד השתלשלות אור א\"ס בבחי' מ\"ה שבחכמה בחי' בטול הנ\"ל כמ\"ש עושה שלום במרומיו בין מיכאל וגבריאל מיכאל שר של מים כו'."],[90,"ולכן אנו רואים בבחי' אדם הגשמי שנשתלשל למטה מבחי' אדם דלעילא יש בו ג\"כ בחי' התכללות מב' הפכים יחד וחבור והתכללות מחו\"ג יחד. ולכן אדם הוא פרצוף שלם בבחי' התכללות ברבוי קוין מבחי' שם מ\"ה בחי' אדם כנ\"ל. וזהו מ\"ש בזוהר דא איהו רזא לאכללא שמאלא בימינא. והיינו מצד הארת שם מ\"ה בחי' בטול הנ\"ל שמאיר במדת חו\"ג ויכולים להתכלל ולהתחבר ב' הפכים כנ\"ל."],[90,"והנה ידוע שכל דצ\"ח נשתלשלו ברבוי מדרגות בעילה אחר עילה עד שירדו למטה מטה ונתהוו מהם דברים גשמיים ושרשם הוא מבחי' התהו כנ\"ל. היינו מבחי' מרכבה העליונה פני אריה פני שור כו'. והיינו בהמות מפני שור וחיות מפני אריה ועופות מפני נשר כו'. וגם כל העשבים יש להם שרש למעלה כמו שכתוב ועשב לעבודת האדם."],[90,"והנה אף שבחי' מרכבה העליונה היא מבחי' תקון ג\"כ כי יש להם בחי' בטול וכמ\"ש וצבא השמים לך משתחוים ואומרים קדוש שמורה על הבטול שהוא בחי' התקון כנ\"ל. וגם נאמר בהם ופני נשר לארבעתן כו' שכאו\"א כלול מכל הד' פנים. מ\"מ ברבוי השתלשלות מבחי' שמרים שבהם כמו שמרי האופנים כו' נתהוו מהם דברים גשמיים של כל בחי' דצ\"ח:"],[90,"<b>והנה<\/b> ע\"י אכילת אדם שהוא מבחי' התקון בחי' שם מ\"ה שבו התלבשות אור א\"ס כו' מתעלה המאכל להיות בבחי' התכללות מפני שע\"י אכילתו נתחזק כחו וחיותו ויוכל להתפלל בכח האכילה ולמסור נפשו באחד בבחי' בטול. לכך גם המאכל מתעלה ומתכלל בבחי' בטול. וזהו ענין בירור כלים דתהו להעלות בבחי' התקון והתכללות כו'."],[90,"והנה מצד ששרש התהו קדם בהשתלשלות לבחי' התקון וגם שנתעלו האורות דתהו בבחי' עצמות אור א\"ס למעלה ממקור מציאותם הנה אחר שנתעלו הכלים דתהו בבחי' התקון עי\"ז נתוסף אור וחיות יותר גם בבחי' התקון להיות המשכת אור מאורות דתהו כי נתבררו ונתכללו בחי' כלים דתהו בבחי' התקון ומצד שרש התהו הנה הוא קדם במעלה מבחי' התקון וכמ\"ש לפני מלך מלך כו'."],[90,"וגם מצד שנתעלו האורות דתהו למעלה כו' הנה ע\"י בירור כלים דתהו נמשך תוספת אור גם בבחי' התקון מבחי' אורות דתהו כמו שהם למעלה בבחי' עצמותו. ומטעם זה צריך האדם למאכל כי האכילה היא צורך גבוה."],[90,"וכמו\"כ באדם דלעילא כמ\"ש ועל דמות הכסא דמות כמראה אדם כו' נמשך בו ג\"כ תוספת אור וחיות מבחי' אורות דתהו ע\"י בירורי כלים דתהו. וזהו וברכת את הוי\"ה אלקיך כו' לשון ברכה הוא בחי' המשכה שנמשך תוספת אור להוי\"ה אלקיך שהוא בבחי' התקון מבחי' אורות דתהו וזהו האדם בה' דקאי על אדם דלעילא. וזהו פי' לחם מן הארץ כי בחי' ארץ היא בחי' שם ב\"ן בחי' תהו ולחם מן הארץ היינו בחי' בירורים דתהו:"],[90,"<b>והנה<\/b> יש עוד בחי' לחם שנקרא לחם מן השמים והיינו לחם של המן כמ\"ש הנני ממטיר לכם לחם מן השמים והוא ענין בחי' טל טלא דבדולחא. וכמ\"ש ותעל שכבת הטל כו' והנה המן ירד בזכות משה שהוא מ\"ה שבחכמה והיינו עצם שם מ\"ה ⟦סו,ב⟧שהוא למעלה מהארת המוחין שנמשכו במדות לצורך הנהגתם והיינו בחי' פנימית כמו שהוא בעצם ולכן נאמר במשה כבד פה כו'."],[90,"ומבואר בזוהר שכבד פה היינו תושבע\"פ. וכבד לשון היינו תושב\"כ. כי שרש משה היה בבחי' פנימית אבא כמו שהוא בעצם למעלה מהארת המוחין במדות של התורה כשר פסול טהור כו' ולכך אמר כי כבד פה וכבד לשון אנכי."],[90,"ולכן אמר ג\"כ מי אנכי כו' וכי אוציא את בנ\"י כו'. כלומר כי אוציא את בנ\"י לקבל את התורה כי לא היה יכול להשפיל את עצמו למטה להיות נמשך ממנו שרש התורה."],[90,"והשיב לו הקב\"ה אנכי אהיה עם פיך אנכי מי שאנכי הוא עצמות א\"ס ב\"ה שהוא למעלה מעלה מבחי' אבא ומעלה ומטה שוין אצלו ולפניו ית' כחשכה כאורה ממש ולכן ירד המן בזכות משה כי שרש המן הוא למעלה מאתעדל\"ת שבאתעדל\"ת אתעדל\"ע היינו כי מבחי' הבירורים דתהו נמשכו המ\"ד מאורות דתהו. אבל שרש המן הוא למעלה והוא אתעדל\"ע שלא ע\"י אתעדל\"ת רק ע\"י בחי' מי שאנכי כשנמשך בבחי' פנימית אבא בחי' משה. אנכי אהיה עם פיך עי\"ז יכול לירד ולהשפיל למטה ולהיות למטה כמו שהוא למעלה ממש כי שרש המן היה מבחי' עקודים שעקוד בכלי א' שבחי' התכללות שבבחי' עקודים אינה כמו התכללות שבבחי' התקון ששרשו הוא עולם הברודים שהוא רבוי הכלים בהתחלקות קוין שאופן התכללותם הוא ע\"י בחי' בטול מהארת שם מ\"ה שבחכמה שהיא הארת המוחין במדות ע\"י התלבשות אור א\"ס בחכמה מטעם שע\"י הארת המוחין במדות מתכללים גם ב' הפכים כמו חו\"ג יחד מצד חלישות המדות מהמוח השליט על הלב ומחליש את המדות שלא יהיו נרגשים בתקפם ומהותם. אבל בחי' ההתכללות שבבחי' עקודים הוא כי אף גם בהיות המדות בתקפם אעפ\"כ מתאחדים ומתכללים יחד מצד גלוי אוא\"ס בהם בבחי' השלימות דוקא ומצד גלוי אוא\"ס שבהם לא שייך ב' הפכים כלל וגם לא בחי' התחלקות כי בחי' התוקף שלהם אינו מצד תוקף המהות אלא מצד גלוי אוא\"ס שהוא שלימותא דכולא ולכן נק' עקוד בכלי א' שאינו מצד רבוי הכלים והתחלקות קוין שהוא ענין הבטול והחלישות כנ\"ל אלא מצד גלוי אוא\"ס ותוקף השלימות שבהם:"],[90,"<b>והנה<\/b> עם כל זה יובן מה שארז\"ל ברכת הזן תקן משה כי בברכת הזן נאמר הכל בלשון נסתר כי הוא נותן לחם לכל בשר כו'. והיינו מפני כי משה הוא בבחי' שם מ\"ה כמו שהוא בעצם שאינו בבחי' גלוי והארת המוחין במדות רק בבחי' הבטול כו'. לכן נאמר הכל לשון נסתר כו'."],[90,"ובברכת הארץ נאמר לשון נוכח נודה לך כו'. והיינו מפני שברכת הארץ קאי על לחם מן הארץ דהיינו לחם שע\"י בירורי מ\"ן ומ\"ד שהוא הכל בבחי' ממכ\"ע. ולכן נאמר בברכת הארץ ועל הכל אנו מודים לך כו' לשון הודאה כי ענין הודאה הוא ע\"ד מודים חכמים לר\"מ דהיינו ב' החולקים זע\"ז כשא' מבטל דעתו נגד חבירו נק' בחי' הודאה."],[90,"וכמו\"כ מודים אנחנו לך. כי הנה יש ב' דעות וכמ\"ש כי אל דעות הוי\"ה יש דעת שמלמטה למעלה שהגשמיות הוא היש והרוחניות הוא אין כי אינו מושג כו'. ומלמעלה למטה הוא בהפוך שהרוחניות הוא היש אמתי מצד שהוא עיקר המהוה והמחיה וכמ\"ש להנחיל אוהבי יש והגשמיות בטל לאין בתכלית."],[90,"וזהו ענין הודאה שאנחנו מודים שהגשמיות בטל והאמת הוא כמו שהוא קמיה. וזו היא מעלת כל העוסק בתורה ומצות רק להעלותן מיש לאין. ולכן ארז\"ל גדולים מעשה צדיקים ממעשה שמים וארץ. שמעשה שמים וארץ הוא מאין ליש והוא מסתיר את האין."],[90,"ומעשה צדיקים העוסקים בתומ\"צ עושים מיש אין להיות הכל כמו שהוא ⟦סו,ג⟧קמיה וזהו גדולים כו'. כי ידוע מארז\"ל גמירא משמיא מיהב יהבי משקל לא שקלי. והיינו שבחי' אור ושפע האלקית הנמשך מאין ליש להיות נמשך בבחי' ממכ\"ע כח הפועל בנפעל לצורך התהוות העולמות וכמ\"ש ואתה מחיה כו' המחדש בטובו כו'. פי' אתה אל\"ף ותי\"ו וה' מוצאות הפה. היינו שכל עיקר מציאות ההשתלשלות הוא מבחי' אותיות."],[90,"וכמ\"ש בדבר ה' כו' והוא ע\"י ה' מוצאות הפה ה\"ג מנצפ\"ך. וזהו מיהב יהבי היינו שיהא נמשך תמיד אור ושפע אלקות מאין ליש להתהוות העולמות. וזהו דעה הא' שמלמעלה למטה שיהא נמשך תמיד אור וחיות כו'."],[90,"וזהו מעשה שמים וארץ כו'. אבל בחי' צדיקים גדולה ממעשה שמים וארץ שמהפכים ומבררים ע\"י בחי' התקון פרצוף אדם בחי' יש הגשמי להיות עולה לבחי' אין דלעילא שהוא יש האמיתי כו'."],[90,"וזהו ענין אנחנו מודים לך. וענין ומברכים אותך הוא כי ההפרש בין ברכה להודאה כי הודאה הגם שמודים שהאמת הוא כמו שהוא קמיה מ\"מ אינו בגלוי ממש. וענין ברכה הוא שתהיה המשכה בגלוי ממש כמו שהוא למעלה כו' כי אחרי העלאת מ\"ן ממעשה הצדיקים נמשך אח\"כ המשכת מ\"ד בתוספת גלוי אור מאורות דתהו כו'. וזהו ומברכין כי ברוך ל' המשכה כו':"],[90,"<b>ואחר<\/b> שנתבאר כל הנ\"ל מעתה צריך לבאר ענין השבת. כי הנה כתיב כי ששת ימים עשה כו'. וביום השביעי שבת כו'. וישבת ביום השביעי כו'. וענין ששת ימים ידוע שהם ו\"ק בחי' ז\"א מדות דאצי' שבכל יום נמשכה המשכה מיוחדת מבחי' ז\"א ע\"י בחי' מל' דאצי' היינו ביום א' ממדת החסד וביום ב' ממדת הגבורה כו' לצורך התהוות בי\"ע בבע\"ג והאור משתלשל בצמצומים מעילה אחר עילה בכלים מכלים שונים עד שיוכל להיות בע\"ג בתכלית כי רצון המאציל היה להיות לו דירה בתחתוני' דוקא."],[90,"והענין מובן עד\"מ מאדם שרוצה להעלות איזה שכל עמוק על הכתב הנה אור ההשכלה צריך לירד ולהשתלשל דרך צמצומים רבים דרך חו\"ב ומחו\"ב למדות כו' עד כח העשיה שביד המוגבלת באותיות הכתב."],[90,"והנה אנו רואים אחר שנח ממלאכתו חוזרים כל האורות וכל הכחות אשר היו נמשכים בהשתלשלות דרך עילה ועלול ויש להם עלייה להיות נכללים בכח השכל ובעצמות הנפש. וכך עד\"מ ששת ימים עשה בבחי' השתלשלות דרך עילה ועלול ברבוי רבבות מדרגות עד עולם השפל הגשמי הזה שהיא היותר תחתון במדרגה."],[90,"וביום השביעי כתיב וישבת כו' שחוזרים האורות ונכללים בבחי' כח הכללי כי שם מעלה ומטה שוין שהוא כח כללי פשוט בתכלית הפשיטות. וזהו ענין מקיף מכל צד בשוה. וכמאמר צופה ומביט עד סוף כל הדורות כו' שסובב ומקיף כל פרטי ההשתלשלות ונכללים בו בתכלית ההתכללות וכמו עד\"מ אדם המרגיש עצמו בכל פרטי אבריו מראשו ועד רגלו בסקירה אחת."],[90,"וזהו ענין שבת כי בו שבת הוא עליית העולמות ⟦סו,ד⟧בבחי' פנימית ונכללים בכח הכללי הפשוט בתכלית ההתכללות. ועיקר ההפרש שבין שבת למן כי במן ההתגלות הוא מבחי' מקור השייך להשתלשלות כמו בחינת עקודים שעקוד בכלי א' שיש בו מכל פרטי ההשתלשלות הכל בבחי' התכללות ואופן בחי' התכללותו אשר נכללים בו כל פרטי פרטים שבהשתלשלות הוא מצד שהוא מקור השייך להשתלשלות והוא בעצמו ג\"כ מערך ההשתלשלות רק שהוא ראשית המקור שלהם לכן התגלות שלו הוא ע\"ד התגלות הכלל אשר שייך להפרטים אשר נכללים בו (עיין בדרוש דור הפלגה מענין עקודים). אבל בחי' שבת הוא עליית ההשתלשלות לבחי' מקיף הכללי לבחי' עצמות א\"ס (עמ\"ש ע\"פ שבתותי תשמורו שבת עלאה) אשר לא שייך בו לומר שהוא מקור וכלל השייך להשתלשלות מצד שהוא בבחי' א\"ס ויכול להיות רבי רבבות השתלשלות באופנים אחרים. ולכן ההתגלות שלו הוא ג\"כ עד\"ז שנגלה הארת מקור הכללי הפשוט בתכלית הפשיטות. (ומטעם זה עצמו שהוא מקור כללי בתכלית בבחי' א\"ס מוכרח לומר שגם בחי' השתלשלות הנכללים בו היינו מצד השלימות ולא מצד שהוא מקור השייך להם ולא שייך לומר בבחי' ההשתלשלות שהם כמו הפרט לגבי הכלל כי כל כלל הוא שייך להפרטים רק מה שנכללים בו ההשתלשלות הוא דבר שממילא מפני שהוא שלימותא דכולא והוא רק בבחי' זיו והארה וכמו שבחי' האור עצמו הוא ג\"כ רק גלוי ממילא מבחי' א\"ס כו'. ולכן הוא רק בבחי' זיו. מהרי\"ל). ומטעם זה לא ירד המן בשבת כי בחי' המן שרשו מבחי' עקודים כמבואר לעיל ובחי' עקודים בערך השתלשלות הוא. ולכן שייך בו לומר שהוא עקוד בכלי א' מצד שהוא בערך השתלשלות וכל בחי' השתלשלות הוא בערך פרט לגבי הכלל כנ\"ל ומצד שבשבת העלייה היא לבחי' מקיף הכללי הנ\"ל אשר שם מעלה ומטה שוין ומקיף הכל בהשוואה אחת כו' לכך המן שהוא מבחי' עקודים לא ירד בשבת מאחר שבחי' עקודים היינו מערך ההשתלשלות כנ\"ל."],[90,"ואחר כל זה מובן ענין שתי הלחם שבשבת שע\"פ נגלה צריך להניח זו ע\"ג זו כי בחי' נגלה היא בבחינת השתלשלות בחי' או\"י וכאשר יניח זו ע\"ג זו מורה על בחי' השתלשלות בדרך עילה ועלול כו'. ובחי' נסתר הוא בחי' או\"ח עליית אורות להיות עולות ונכללות בתכלית ההתכללות בבחי' מקיף הכללי כנ\"ל מטעם זה צריך שיהיו זו בצד זו שתיהן בשוה שמורים על בחי' התכללות אמתי במקיף העליון שמקיף לכל פרטי פרטי ההשתלשלות בשוה כו' קמיה מעלה ומטה שוין כו' וד\"ל. (ועמ\"ש לקמן בד\"ה זכור ושמור שהן זו\"נ כי זכור לדכורא ושמור לנוקבא והן ב' חלות דלחם משנה. וע\"פ סדר ההשתלשלות הרי המלכות מקבלת מז\"א והוא למעלה ממנה במדרגה. וזהו כמו שהן באצי' אבל מצד עצמות א\"ס ב\"ה שניהן בדבור א' נאמרו כו' שכולל לשניהם בשוה וזהו שע\"פ הנסתר צ\"ל ב' חלות דלחם משנה זו בצד זו):"],[91,"⟦סו,ד⟧<b>בחדש השלישי לצאת בני ישראל מארץ מצרים ביום הזה באו מדבר סיני.<\/b> הנה נאמר סתם ביום הזה ולא פי' באיזה יום רק חז\"ל דרשו שהוא בר\"ח. כתי' הכא ביום הזה וכתיב התם החדש הזה לכם."],[91,"ולהבין למה נק' ר\"ח בכתוב בלשון ביום הזה. יובן בהקדים ענין מעלת קבלת התורה והלא קודם מ\"ת היו כמה צדיקים והאבות הן הן המרכבה ג\"כ קודם שנתנה התורה. אך הענין כי הנה מעלת אברהם הוא שהי' הולך ונסוע הנגבה. פי' שהי' הולך ונסוע ממדרגה למדרגה עד שבא הנגבה הוא בחי' ומדת אהבה העליונה."],[91,"וכ\"כ היה הולך מעלייה לעלייה עד שהיה בבחי' מרכבה ממש לאהבה זו העליונה עד שהיתה בבחי' גילוי בנפשו ממש ⟦סז,א⟧והליכה זו היא ממטה למעלה מבחי' מצרים כמ\"ש ויעל אברם ממצרים דהיינו בחי' מצר וגבול שמצד הגוף ונפש הבהמית המגבילים ומלבישים את נפש האלקית שבאדם עד שאע\"פ שנפשו האלקית היא משכלת ומתבוננת בגדולת א\"ס ב\"ה והתפשטותיו על הנבראים שהוא חיי החיים ואתה מחיה את כלם. את השמים ואת הארץ אני מלא ומכה\"כ. אעפ\"כ אינו בכח נפשו לצאת מנרתקה הוא מאסר הגוף להיות בבחי' אתכפייא ואתהפכא כו' רק הגוף עומד על עמדו בתקפו ובגבורתו כתולדתו."],[91,"וכמארז\"ל גנבא אפום מחתרתא כו'. ומעלת אברהם היתה שעלה מבחי' מצר זה לדבקה נפשו באהבה עליונה עד שתחפוץ להתפשט מלבושי' שבנגה שמצד הגוף להיות בבחי' בטול אליו ית' לבדו בבחי' כלות הנפש ממש."],[91,"והנה אהבה זו באה מחמת התבוננות באור א\"ס ב\"ה עצמו הסוכ\"ע דלית מחשבה ת\"ב כלל כי מלכותך מלכות כ\"ע בחי' מלך לבד שהוא בחי' דבור כמ\"ש דבר מלך שלטון. וכמאמר ברוך שאמר והיה העולם אמירה בלבד שמזה נמשך חיות כל העולמות וקיומם והתהוותם מאין ליש שאין זה אלא בחי' הארה בעלמא וכמ\"ש תתברך בשמים ממעל ועל הארץ מתחת על כל שבח מעשה ידיך שכל העולמות שמים וארץ מן הארץ לרקיע ת\"ק שנה אינה אלא בחי' מעשה ידיך שכמו במעשה ידי אדם עד\"מ אינו מלובש אלא כח המעשה שהוא לבוש החיצוני של הנפש. כך החיות המלובש בכל העולמות אינן אלא בבחי' כח המעשה שהוא כח החיצוני והארה בעלמא שאינו נוגע לעצמות ומהות הנפש כלל."],[91,"ובורא קדושים ישתבח שמך לעד כו' שהקדושים שהם מלאכים ונשמות הם בחינת שם בלבד שהוא ג\"כ אינו אלא זיו והארה כו' אלא שאינם בבחי' מעשה ידיך כמו חיצוניות העולמות כי הנה כח המעשה המלובש באיזה כלי או שאר דבר מעשה ידי אדם עד\"מ הנה הכח ההוא אין לו שייכות כלל עם עצמות ומהות הנפש כי נעשה נפרד מובדל ממנו וע\"י אחיזת הכלי עם הכח המלובש בו אין נמשך עצמות אדם אחריו. משא\"כ בקראו שמו נמשך ג\"כ עצמות האדם שהשם הוא זיו והארה הנוגע לעצמות הנפש ועודנו קשור ומיוחד עמה. אך עכ\"ז אין זה אלא בחי' זיו. אבל הוא ית' בכבודו ובעצמו רם ונשא כו'."],[91,"והוא הוא הסוכ\"ע ומעלה ומטה שוים לפניו כו'. וכמ\"ש אני ה' לא שניתי ואי לזאת תשפך הנפש אל חיק אביה ממש להיות נכספה וגם כלתה נפשי להיות בבחינת בטול ממש אליו ית' לבדו וכמ\"ש מי לי בשמים וז\"ש אני ה' לא שניתי ואתם בני יעקב לא כליתם. פי' שהנביא מתמה על ישראל הרי אני ה' לא שניתי ומפני מה לא כליתם שאין לכם כלות הנפש. אך דבר הגורם להיות מונע ומעכב את הנפש מבחי' בטול זה כמו שהעיד הכתוב ואתם בני יעקב לא כליתם הגם שיתבונן בגדולת א\"ס ב\"ה כי אני ה' לא שניתי ולא כל האדם זוכה למעלת ומדרגת אברהם שנעשה מרכבה בבחי' בטול ממש באהבה עליונה מחמת התבוננות זו. הנה הסבה היא חלישת כח הנפש שאין בכחה לצאת מנרתקה ומאסרה."],[91,"והוא מ\"ש כשל בעוני כח שע\"י העונות נכשל ונתחלש כח הנפש וכמ\"ש כי אם עונותיכם היו מבדילים ביניכם לבין אלהיכם ולא עונות ממש אלא גשמיות הגוף וחומריותו הוא שנעשה מסך מבדיל שהוא הוא המצר וגבול שמגביל ומלביש את הנפש עד שמורידה לימשך אחריה ואינה יכולה לעלות ולצאת ממנה וע\"ז נאמר ותרא את עני אבותינו היינו מדות אהוי\"ר כו' אברהם מדת האהבה כו':"],[91,"<b>ולזה<\/b> נתנה התורה לישראל שהתורה נק' עוז שהיא הנותנת כח ועוז לנפש האלקית להתגבר על חומריות הגוף ונפש הבהמית וגסותן לצאת ממסגר אסיר. וזהו ה' עוז לעמו יתן ה' יברך את עמו ⟦סז,ב⟧בשלום כי ע\"י התורה שנק' עוז נעשה בשלום פי' ב' שלום. כמארז\"ל עושה שלום בפמליא של מעלה ובפמליא של מטה. שלום היינו התקשרות בפמליא של מעלה היינו בחי' גילוי אור א\"ס ב\"ה ממש בנפש האלקית להיות קשורה ומיוחדת בבחי' בטול ממש."],[91,"ובפמליא של מטה היינו הארת כחות נפש האלקית המלובשת בגוף ונה\"ב שלא יהיה מונע ומעכב מצד הגוף ונפשו הבהמית רק שיהיו כולם מסכימים ומתרצים ליחוד זה כד אתכפייא ואתהפכא חשוכא לנהורא כי התורה שנק' עוז נק' ג\"כ תושיה שמתשת כח הס\"א שמצד הגוף כי לאום מלאום יאמץ וכשזה קם זה נופל. אך להבין כיצד הוא העוז של התורה ליתן כח לנפש האלקית ולהתיש כח גשמיות הגוף וחומריותו הלא גם התורה נתלבשה בענינים גשמיים תרומות ומעשרות כו'. אמנם הנה נודע כי מקור התורה ויסודה בהררי קדש עליון מאא\"ס ב\"ה בעצמו ובכבודו הסוכ\"ע אני ה' לא שניתי אורייתא וקוב\"ה כולא חד."],[91,"והנה עיקר קבלת התורה הוא מ\"ש בעשרת הדברות וידבר אלקים את כל הדברים האלה לאמר אנכי. דלכאורה מלת לאמר אין לה הבנה ואינה כמו כל לאמר שבמקרא שפי' לאמר לזולתו. משא\"כ בעשרת הדברות א\"א לפרש כך שהרי כל ישראל שמעו ופב\"פ דבר ה' את אשר ישנו פה ואת אשר איננו פה כו'. אך פי' הוא לאמר ולדבר את כל דברי התורה מה שכבר נאמר למשה מסיני כי כל מקרא ומשנה הלכות ואגדות כולם נאמרו למשה בסיני הגם שבגמרא הוזכרו שמות תנאים ואמוראים שאמרו הלכה זו כמו ב\"ש אומר כך כו' היינו דבר ה' זו הלכה שנאמרה למשה מסיני שיצא מפי אותו תנא ואמורא."],[91,"וכענין דברי אשר שמתי בפיך וכח זה ניתן לישראל להיות הלכה היוצאת מפיהם דבר ה' ממש שנאמרה למשה מסיני ניתן בזמן קבלת התורה בעשרת הדברות לאמר מה שכבר נאמרה דהיינו בחי' בטול אליו ית' שאין הדבור נעשה נפרד אצל האדם להיות יוצא מפי עצמו כאלו הוא שלו רק כמ\"ש תען לשוני אמרתך שהתורה היא אמרתך אלא שלשוני תען כעונה אחר האומר מה שהוא אומר."],[91,"ויו\"ד הדברות הן כללות כל התורה שבקבלתן עשרת הדברות מפי הגבורה קבלו כל התורה להיות בחי' בטול אצלם לדבר ה' המדבר בפיהם ולהיות רק כעונה אחר האומר שהוא ענין גילוי אור א\"ס למטה כמו למעלה בבחי' בטול ממש."],[91,"ומזה יתבונן המשכיל ויפול עליו אימה ופחד בעסק התורה בשומו ללבו כי דבר ה' הוא ממש שנאמרו למשה מסיני. וזהשארז\"ל ע\"פ והודעתם לבניך ולבני בניך וסמיך ליה יום אשר עמדת כו' מה להלן באימה ויראה כו' אף כאן כו' שלכאורה אינו מובן דמיון זה מה להלן אף כאן כו' שהרי במעמד הר סיני וכל העם רואים את הקולות ופב\"פ דבר ה'. משא\"כ בעסק התורה של כל אדם כשלומד בפני עצמו. אלא הענין הוא כמש\"ל כי גם עסק התורה שבכ\"א ובכל זמן הוא דבר ה' ממש שנאמר למשה מסיני. ועל ידי זה תפול עליו אימה ויראה כאלו קבלה היום מהר סיני:"],[91,"<b>והנה<\/b> עסק התורה בבחי' בטול זה הוא הנותן עוז ותעצומות לנפש האלקית ותושיה לסט\"א. וזהו אנכי ה' אלקיך אשר הוצאתיך מארץ מצרים כי בקבלת התורה נמשך בחי' אנכי דהיינו אנכי ממש עצמותו ומהותו ית' הסוכ\"ע כו'."],[91,"וכמ\"ש והיו הדברים האלה אשר אנכי מצוך היום כו' ובחי' אנכי זה נמשך לישראל בבחי' הוי\"ה דהיינו ע\"י צמצום והתפשטות כנ\"ל עד שנעשה בבחי' אלקיך ממש ואזי אשר הוצאתיך מארץ מצרים מבחי' מצרים וגבולים שמצד הגוף ונה\"ב המגבילים ומלבישים את נפש האלקית ומעכבים לצאת מנרתקה וכמ\"ש ואעלה אתכם מעני מצרים אל ארץ טובה ורחבה כי ⟦סז,ג⟧ע\"י קבלת אנכי דהיינו בחי' סוכ\"ע ואני ה' לא שניתי בעסק התורה בבחי' בטול כו' הוא הנותן כח לנפש האלהית."],[91,"ותושיה לתאוות הגוף כו'. וזהו ענין אנשי יריחו היו כורכין את שמע ולא היו מפסיקין בין אחד ואהבת. כי ע\"י קבלת בחי' אחד דהיינו בחי' יחודא עלאה שהוא בחי' בטול ממש לאור א\"ס ב\"ה הסוכ\"ע כנ\"ל תגדל האהבה ביתר שאת עד שתהיה בכל לבבך בשני יצריך דאתכפיא סט\"א ואתהפכא חשוכא לנהורא שמבחי' בטול זה נמשך עוז ותושיה כנ\"ל. משא\"כ בשכמל\"ו הרי כתיב מלך אלהים על גוים כי שם זה הוא חיות העולמות ואפי' עכו\"ם בכלל. וכענין שארז\"ל לא כאברהם שיצא ממנו ישמעאל כו' אלא שאנו אומרים בשכמל\"ו בחשאי כי ועד הוא ג\"כ אחד אלא שהוא בחילופי דאתוון כמ\"ש בזוהר:"],[91,"<b>ובזה<\/b> יובן מה שישראל מונים ללבנה. כי הלבנה לית לה מגרמה כלום רק שמקבלת האור שלה מאור השמש להאיר על הארץ. ולכן בכל חודש וחודש מתמעטת קודם חידושה עד שנעשית בבחי' נקודה מפני שבאה תחת אור השמש ממש לקבל ממנה ולכן אינה מאירה על הארץ והולכת ואור עד מילוי הלבנה והכל מאור השמש ממש שהלבנה לית לה מגרמה כלום."],[91,"ואחר מילוי הלבנה חוזרת ומתמעטת להיות בבחינת נקודה בסוף החדש עד שחוזרת ומתחדשת. וככל הדברים האלה וכמשל הזה כך הוא ענין ישראל שהם בחי' בטול לאור א\"ס ב\"ה הסוכ\"ע ותורתם ועבודתם הם בבחינת דלית להון מגרמיהון כלום. שאינו בבחי' יש מי שלומד יש מי שאוהב כו'. אלא הכל בבחי' בטול לאור א\"ס ב\"ה ממש ואור א\"ס ב\"ה ממש הוא השוכן בתוך תורתם ועבודתם ודבר ה' זו הלכה היא המדברת בפיהם וזו היא בחי' שמש כמ\"ש כי שמש ומגן הוי\"ה אלקים. שבחי' הוי\"ה נק' שמש."],[91,"ובחי' אלהים נק' מגן כו' כמ\"ש במ\"א. והתורה נמשך משם הוי\"ה. וזהו ענין תורה ועבודה וגמ\"ח שצריך להיות שלשתן דוקא כי גמ\"ח היינו צדקה. וצדקה היא כללות כל התורה שנק' בשם צדקה ובפרטות מעשה הצדקה ממש שהצדקה היא להחיות רוח שפלים היא בחי' שמש כמ\"ש וזרחה לכם יראי שמי שמש צדקה. כי כמו שהצדקה היא להחיות רוח שפלים."],[91,"וכן אור השמש הוא להאיר במקום חשך שאין בו אור שהיא בחי' השפעה מלמעלה למטה. והשפעה זו היא ע\"י בחי' עבודה שהוא בחי' בטול ממטה למעלה אור א\"ס ב\"ה הסוכ\"ע להיות השפעת אוא\"ס ב\"ה ממש שורה ומתגלה למטה כמו למעלה דהיינו כמו בטול הלבנה לאור השמש ממש:"],[91,"<b>וזהו<\/b> בחדש השלישי לצאת בני ישראל מארץ מצרים ביום הזה כו' כי בצאת ישראל ממצרים התחילו לספור ספירת העומר כמ\"ש שבעה שבועות תספר לך. והם הכנה להיות קבלת התורה בשבועות. דהיינו להיות גילוי אוא\"ס ב\"ה למטה כמו למעלה בבחי' בטול אליו ית' לאמר אחר מה שיאמר הוא ולהיות דבר ה' ממש בתוך בני ישראל בעסק תורתם."],[91,"ובשבוע הז' ביום ג' בו הוא כאלו כבר נכנסה כל השבוע ונעשו אז ישראל מוכנים ועומדים לקבל בחי' בטול זה. והיה אז מולד הלבנה שהוא גילוי אוא\"ס ב\"ה אחר בטול הלבנה אליו. ולכן נק' ביום הזה סתם כי יום היינו אור וגילוי כמ\"ש ויקרא אלהים לאור יום והיינו גילוי ואהבה שבבחי' בטול אליו ית' (שבחי' אהבה זו נק' היום הזה כי פי' זה הוא בחי' יחו\"ע שלכן משרע\"ה נתנבא בזה. ובר\"ח מקבלת כנ\"י מוחין מחכמה. עמ\"ש בד\"ה והיה מדי חדש. לכן האהבה היא בבחי' בטול) כי ואהבת ב\"פ אור ואזי באו למדבר סיני שירדה שנאה כו' דהיינו ענין ⟦סז,ד⟧תושיה שמתשת כח הס\"א כו' ומדבר מלשון דבור כמו ומדברך נאוה ונק' מדבר בתוספת מ' כי המ' הוא מאותיות האמנתי\"ו שהן להקטין הענין כלומר שאין בזו בחי' דבור בפ\"ע רק בחי' שכבר נדבר דהיינו שהדבור הוא בחי' בטול בדבר ה' המדבר בו (ועמ\"ש בד\"ה הנ\"ל) ואזי ויסעו מרפידים. בחי' רפיון ידים כמארז\"ל למה נק' שמה רפידים כו' דהיינו בחינת חלישת כח הנשמה רק שניתנה להם עוז ותעצומות לנשמה ותושיה לס\"א כו':"],[92,"<b>משה ידבר והאלהים יעננו בקול.<\/b> בקולו של משה. ולהבין כי לא פירש בכתוב מה דבר משה ומה ענהו ה' דלא קאי על עשרת הדברות דהא אנכי ולא יהיה לך מפי הגבורה שמענו וכתיב אנכי עומד בין ה' וביניכם להגיד וגו'. הרי שלא נאמר בזה הענין שמשה הוא המדבר והקב\"ה העונה וגם להבין מהו ידבר ומהו יעננו לשון עתיד או הווה והוה ליה למימר משה דבר והקב\"ה ענהו. הענין הוא דאיתא בגמרא דאמר רב יוסף אי לאו האי יומא דקא גרים כמה יוסף איכא בשוקא."],[92,"ולהבין מעלת האי יומא דוקא שהוא יום מתן תורה ומהו ענין מתן התורה. והלא קיים אברהם אבינו ע\"ה את כל התורה עד שלא ניתנה ואפי' עירובי תבשילין מפני שלמד את כל התורה כו' עד שלא נתנה."],[92,"וכמ\"ש וישמר משמרתי מצותי חקותי ותורתי ובודאי לימד ג\"כ ליצחק בנו ויצחק לימד ליעקב ובניו ומה חדוש נתחדש בנתינתה. אך הנה נודע ענין המצות דרמ\"ח פקודין אינון רמ\"ח אברין דמלכא. ולכאורה אינו מובן לשון אברין והלא אין לו דמות הגוף וכו' אך יובן ע\"פ מ\"ש בזהר דכל מעשה המצות הן לאתקנא רזא דשמיה שבמצוה זו ממשיך שם זה ובמצוה זו ממשיך שם זה והענין כי שמותיו של הקב\"ה הם שבעה שמותיו שאינן נמחקין."],[92,"והם הם בחינת התפשטות החיות והשפעה להתהוות מדותיו ית' לך ה' הגדולה והגבורה והתפארת וגו' שאינן אלא בחי' שם לבד ע\"ד משל כמו השם שאינו אלא לזולתו שיקראנו בשמו כי הוא ית' רם ונשא וכו'."],[92,"וכמ\"ש בתקוני זוהר לאו מכל אלין מדות כלל ואנת הוא חכים ולא בחכמה ידיעא. כי החכמה הידיעא היא בנבראים שנק' בשם חכמה שהיא השכלה להשכיל דבר מושכל אבל אצלו ית' לא שייך זה כי אפי' בחי' המחשבה שהיא למטה מחכמה נאמר עליה כי לא מחשבותי מחשבותיכם וגו' אלא שנק' חכמה ומחשבה לפי שהיא מקור המחשבה ומקור החכמה."],[92,"וכמ\"ש כי עמך מקור חיים באורך נראה אור. פירוש באורך כשנמשך האור למטה אזי נראה ומושג אור החכמה והמחשבה כו'. וכן בחי' החסד כמ\"ש ועשה חסד לאלפים. שיש אלפים מדרגות שהם רבוי הצמצומים והמשכות עד שיהיה התהוות חסד."],[92,"וכמ\"ש עולם חסד יבנה שצריך הוא להיות נבנה שיהיה חסד. והמשכה זו להיות התפשטות החיות בבחי' חכמה וחסד הוא מז' שמות שאינם נמחקין הוי\"ה בנקוד פת\"ח היא בחכמה ושם אל בחסד. וכמ\"ש חסד אל כל היום שהם בחי' שם בלבד. אך מ\"מ אחר שנמשך ובא לידי גילוי מדת החסד והחכמה הנה ההמשכה ההיא היא מלובשת ממש במדת החסד והחכמה עד שמתאחדת עמהם וזהו ענין איהו וחיוהי חד. איהו וגרמוהי חד. דהיינו כענין הוא המדע הוא היודע כו'. וכמ\"ש לך ה' הגדולה והגבורה פי' שמתאחדת ונעשית בבחי' לך ה' ממש."],[92,"והנה המשכת החיות להיות התפשטות אוא\"ס ב\"ה והתלבשותו במדת החסד והחכמה שאין ערך אליו דאנת הוא חכים ולא בחכמה ידיעא ולא מכל מדות אלין כלל באתערותא דלתתא תליא מילתא ע\"י מעשה המצות שע\"י מצוה שהיא בחכמה ממשיך אור א\"ס ב\"ה בחכמה."],[92,"וע\"י מצוה שבחסד ממשיך אור א\"ס ב\"ה בחסד. והן הן המשכת ⟦סח,א⟧שמותיו ית' והתלבשותו בחכ' וחסד הוי\"ה בנקוד פת\"ח בחכמה כו' ולכן נקראו המצות בשם אברין דמלכא דכמו שמלובש חיות הנפש באברין ע\"ד משל עד שמתאחדת עמהם כך מלובש אור א\"ס ב\"ה המשכת בחי' שמותיו ית' בבחי' חכמה וחסד שבמעשה המצות עד שמתאחדת ממש באור א\"ס ב\"ה הנמשך בהם."],[92,"ובזה יובן ענין המצות שכתוב באברהם וישמר משמרתי מצותי וגו'. דהיינו שגרם ירידת והמשכת אור א\"ס ב\"ה והתלבשותו במדת החכמה וחסד ע\"י שנעשה מרכבה אליו ית' במדת האהבה הלוך ונסוע הנגבה בבחי' רצוא ושוב כי רוח אייתי רוח ואמשיך רוח."],[92,"וכמ\"ש אם ישים אליו לבו וגו'. וגם מחמת שהרבה חסד בעולם. ויטע אשל וגו'. וע\"י שהיה שפל רוח מאד. וכמ\"ש ואנכי עפר ואפר. לכן עי\"ז כמים הפנים וגו'. ע\"י מדת ענוה המשיך ירידת אור א\"ס ב\"ה בחכמה וחסד שהוא בחי' ירידה ושפלות לגבי אור א\"ס ב\"ה דאנת הוא חכים ולא בחכמה ידיעא ולאו מכל מדות אלין כלל שאין ערוך אליו. וכמאמר רז\"ל במקום שאתה מוצא גדולתו של הקב\"ה שם אתה מוצא ענותנותו כו':"],[92,"<b>אך<\/b> הנה עיקר המשכות אברהם אבינו ע\"ה היה בעולמות עליונים הגם שהמשיך אור א\"ס ב\"ה למטה ג\"כ להיות גילוי אלהות בעולם וכמ\"ש ויקרא שם בשם ה' אל עולם. וגם הנפש אשר עשו בחרן ונטע אמונת ה' בלבם מ\"מ אין זה ערך לגבי המשכות שהמשיך למעלה בעולמות עליונים להיות תוספת גילוי אור א\"ס ב\"ה בבחינת חכמה וחסד עליון דאצי' ושם היה עיקר עבודת אברהם וישמר משמרתי מצותי וגו'. מצותי דוקא מצות שהקב\"ה עושה בעצמו הקב\"ה מבקר חולים שענין החולים בעולמות עליונים הוא כמ\"ש סמכוני באשישות וגו' כי חולת אהבה אני. שבחי' חולת אהבה היא מחמת ההסתר וההעלם שכל בחי' ממלא וסובב כל עלמין אינן אלא בחי' זיו ורק הודו על ארץ ושמים וגו'."],[92,"ואי לזאת תכסף ותכלה הנפש לדבקה בא\"ס ב\"ה ממש. ועל זה נאמר סמכוני באשישות רפדוני בתפוחים שהם ענין התגלות אור א\"ס ב\"ה מההסתר והעלם שגילוי זה הוא רפואה לחולת אהבה זו."],[92,"וכן אמרו הקב\"ה מניח תפלין. כי תפלין מלשון התקשרות שהוא התקשרות אור א\"ס ב\"ה בחכמה. והיינו דאמרינן תפלין דמארי עלמא מה כתיב בהו ומי כעמך ישראל וגו'. כי ישראל עלו במחשבה בראשית בשביל ישראל שנקראו ראשית והתפלין הם ההתקשרות של אור א\"ס ב\"ה בבחי' ישראל שנקראו ראשית הוא בחי' חכמה וע\"ד זה שאר המצות של הקב\"ה הן המשכות מאור א\"ס ב\"ה בעולמות עליונים ושם גילוי המשכת אור א\"ס ב\"ה והתלבשותו בחכמה וחסד בבחי' איהו וחיוהי חד איהו וגרמוהי חד. אבל האי עלמא עלמא דפרודא כמ\"ש ומשם יפרד וגו'."],[92,"וכדי להיות המשכת אור א\"ס ב\"ה בבחי' איהו וחיוהי חד כו' גם למטה בעולם הפירוד נתנה התורה לישראל שתהא התלבשות והתאחדות אור א\"ס ב\"ה ממש בחכמה וחסד שלמטה במעשה המצות וקיומן בעשיה גשמית. וכמ\"ש וירד ה' על הר סיני. וע\"ז אמרו דהאי יומא הוא דקא גרים:"],[92,"<b>והענין<\/b> הוא הנה כתיב כי אל דעות הוי\"ה. פי' ב' דעות יחודא עלאה ויחודא תתאה. יחודא עלאה מלמעלה למטה שכל מה שלמטה מטה הוא יותר כלא וכאין וכל מה שהוא למעלה יותר יותר נחשב ליש."],[92,"וכמ\"ש להנחיל אוהבי יש. ויחודא תתאה ממטה למעלה היא בחי' יש מאין שכל מה שלמטה מטה נחשב יותר ליש ונראה לעיני בשר דבר בפני עצמו ומורגש ומה ⟦סח,ב⟧שהוא למעלה מעלה הוא ענין שאינו נראה ולא מורגש ומושג ובשם זה של אל כולל ב' הדעות שכשם שמלמעלה למטה כל מה שלמטה הוא כלא ואינו תופס מקום כך הוא ממטה למעלה ג\"כ מפני כי ולו נתכנו עלילות ולא כתיב באלף והקרי ולו בוי\"ו."],[92,"ולא באלף הם מצות לא תעשה. ולו בוי\"ו הם מצות עשה. נתכנו להיות שוים יחודא עלאה ויחודא תתאה להיות למטה כמו למעלה ממש שלא יהיה היש תופס מקום כלל כי על התורה ומצות נאמר נעשה אדם בצלמנו כדמותנו. בצלמנו בחי' התורה. כדמותנו בחי' המצות שהן הן בחי' אדם שעל דמות הכסא כו' שהן הן פנימיות רצונו וחכמתו ית' בלי שום הסתר פנים ואין היש מעלים ומסתיר על אור א\"ס ב\"ה השורה בתוכם ובהם ועל ידם ממשיך אור א\"ס ב\"ה להיות למטה כמו למעלה בבחי' אין עוד מלבדו ולא תחללו את שם קדשי שלא לעשות חלל כו' ולא להיות דוחק רגלי השכינה רק ואשים דברי בפיך דברי ממש."],[92,"והנה המצות הן לבושין ומקיפין והתורה היא מזון ופנימיות שבהם ממשיך אור א\"ס ב\"ה להיות שורה על נפשו בבחי' מקיף וגם להיות הנפש תוכה רצוף אהבה בבחי' פנימית. וע\"ז נאמר כי הוי\"ה אלהיך אש אוכלה הוא. פי' הוי\"ה בחי' תורה."],[92,"ואלהיך פי' בחי' מצות הן הם כמו האש ע\"ד משל שאם נותנים אש תוך הכלי וסביבותיו הרי ממילא שולט האש מעבר אל עבר ושורף ומכלה לגמרי. כך התורה והמצות ע\"י שהם בבחי' פנימיות ובבחינת מקיפין הרי יש בהן כח לכלות ולשרוף לגמרי את חומריות נפש הבהמית וגסותה שהיא המסתרת ומעלמת על אור ה' א\"ס ב\"ה להיות נראה ליש ודבר בפני עצמו שלכן היא צריכה למירוק בגיהנם אבל תלמיד חכם אין אור של גיהנם שולט בו כי התורה והמצות הם הממרקות מבית ומבחוץ ונגלה כבוד ה' למטה כמו למעלה. וזהו שכתוב והר סיני עשן כלו מפני אשר ירד עליו ה' באש וידבר הוי\"ה אליכם מתוך האש וגו':"],[92,"<b>והנה<\/b> כח זה להמשכה זו ניתן לישראל שהם הם הממשיכים תורתו ומצותיו ע\"י עסק תורתם ועבודתם בבחינת ולא תחללו וגו'. מה שא\"כ עכו\"ם אפי' אם מקיימין תורה ומצות אין ממשיכין כלום והיא בחי' מתנה טובה."],[92,"וכמארז\"ל שלש מתנות טובות כו'. וזמן מתנה זו היא בחג השבועות זמן מתן תורה גלוי בחי' כתר תורה שהיא למעלה מבחי' התורה. וזהו אי לאו האי יומא דקא גרים כמה יוסף איכא בשוקא כמה בחי' יוסף. יוסף דעת יוסף מכאוב וכמה מיני חכמות זרות דכתיב בהם חכמים הם להרע ולהטיב לא ידעו כי משם יפרד אבל האי יומא הוא גלוי חכמתו ורצונו ית' המלובשת בתורה שבה התלבשות אוא\"ס ב\"ה וגלוי למטה כמו למעלה. כי האי יומא הוא ממחרת השבת אחר ימי הספירה שבעה שבועות שהם מבחי' ז' שמות שאינן נמחקין שהם בסדר השתלשלות שכך צריך להיות תחלה ההמשכה מעט מעט עד שבחג השבועות בא הגלוי מלמעלה מסדר ההשתלשלות שמעלה ומטה שוין שם רוחניות כמו גשמיות. כמ\"ש המשפילי לראות בשמים ובארץ וגו' כמ\"ש במ\"א. והוא ענין כתר תורה. ולכן בא לידי גלוי למטה כמו למעלה."],[92,"והנה על המשכת התורה בבחי' זו כתיב משה ידבר. משה בחינת בטול והאיש משה ענו מאד מכל האדם אשר על פני האדמה. ונחנו מה. ידבר מלשון המשכה והנהגה. כמו ידבר עמים דהיינו שממשיך אוא\"ס ב\"ה למטה ע\"י בחי' בטול כי החכמה מאין תמצא מבחי' אין. ובמקום שאתה מוצא גדולתו שם אתה מוצא ענותנותו. והיינו ע\"י בחי' ענוה."],[92,"והנה משה הוא הממשיך מלמעלה למטה. כי משה שושבינא דמלכא ואיש האלהים בעלה דמטרוניתא ⟦סח,ג⟧דהיינו שהוא ממשיך בחי' יחודא עלאה שכל מה שלמטה מטה הוא כאין ואין עוד מלבדו וגו' והאלהים הוא בחי' יחודא תתאה שהוא בחי' כסא הכבוד שהוא מקור לנפש הבהמית פני אריה פני שור כו'. משא\"כ משה בחי' מה היינו בחי' אדם שעל הכסא כו' אדם בגימטריא מ\"ה."],[92,"והוא בחי' הצמצום להיות יש מאין כי אלהים לשון שררה כי אין מלך בלא עם מלשון עוממות. והאלהים יעננו הנה לשון עניה בלשון הקודש הוא כמארז\"ל גבי הלל עונה אחריהם מה שהם אומרים שמה שהשומע אומר מה שאומר המדבר נק' עונה. וזהו והאלהים יעננו שבחי' יחודא תתאה יענה להמשכה זו של משה שהמשיך מבחי' יחודא עלאה להיות מלמטה למעלה כמו מלמעלה למטה. וענין ידבר ויעננו לשון הווה. הנה אתפשטותא דמשה בכל דרא היא בחי' הבטול שיש בכל אדם לפום מאי דמשער בלביה בקיום התורה והמצות בבחי' בטל רצונך:"],[92,"<b>וזהו<\/b> שאמרו רז\"ל כל הקורא ושונה הקב\"ה קורא ושונה כנגדו. לא הכל שוים בבחינה אחת אלא כל חד לפום שיעורא דיליה בבחי' הבטול לאור א\"ס ב\"ה בחי' אין עוד מלבדו ואני ה' לא שניתי."],[92,"וכמו שהיה אוא\"ס ב\"ה ממלא כל חלל זה דעוה\"ז קודם שנברא עולם הזה כך הוא ממש לאחר שנברא והוא בחי' משה ונחנו מה. ושכינה מדברת מתוך גרונו של משה וכן בכל דור ודור. כמו שאמר המגיד להבית יוסף אני המשנה המדברת בפיך."],[92,"ולכן נק' התלמיד חכם בשם משה כדאיתא בגמ' משה שפיר קאמרת. כי התלמיד חכם הוא המקבל מבחי' חכמה עלאה כח מ\"ה ואבא יסד ברתא כמ\"ש ה' בחכמה יסד ארץ הוא דבר ה' זו הלכה שבפי ת\"ח. וזהו בקולו של משה כי קול הוא בחי' המשכה מההעלם אל הגלוי כמו מהבל הלב אל הגרון ע\"ד משל כנודע מ\"ש על פסוק קנה חכמה כלומר כפי ערך המשכת בחי' הבטול לאור א\"ס ב\"ה ככה ממש האלהים יעננו להיות קורא ושונה כנגדו:"],[93,"ביאור על הנ\"ל"],[93,"<b>ביאור<\/b> ע\"פ משה ידבר כו'. דעם היות דקיים אברהם כל התורה כולה עד שלא נתנה היה עיקר ההמשכה למעלה אבל משה ידבר וימשיך להיות הגילוי למטה גם בעשיה. וצ\"ל מהו הענין שהמשיך אברהם ע\"י המצות למעלה. אך הוא כי רמ\"ח מ\"ע נקראים רמ\"ח אברים דמלכא היינו רמ\"ח אברים דז\"א. כי ז\"א הוא בעל ט' ספירות ט' פעמים ט' הוא פ\"א."],[93,"וכל בחינה יש בה ג' כלים פנימיים תיכונים חיצוניים הנק' סת\"ר סוף תוך ראש. הנה ג\"פ פ\"א הוא רמ\"ג וה\"ח המגדילים הרי רמ\"ח אברי ז\"א שהן שרש רמ\"ח מ\"ע ולהמשיך בחינת זו שיהי' הגדלת אברי ז\"א ע\"ד הנ\"ל להיות טפ\"ט כו' הוא ע\"י בחי' עבור יניקה מוחין כי בבחי' עבור הוא תלת כלילן מתלת. ואח\"כ בחי' יניקה הוא שמתגדל ז\"א בבחי' ו\"ק וכל א' כלול מששה מספר ל\"ו. וזהו ענין מי ברא אלה. מי הוא בחי' בינה ברא אלה הן ו\"ק דז\"א כל א' כלול מששה כו'."],[93,"והנה אף שביניקה יש ג\"כ מוחין ונק' מוחין דיניקה. עכ\"ז נק' רק ו\"ק כי מוחין אלו הם בכלל המדות יחשבו עד\"מ השכל של המדה שיאהב מחמת טעם ושכל שזה השכל מגדיל המדה כחלב שמגדל את הולד. ולכן בכלל המדה יחשב שהוא מדה ממש ע\"כ נק' רק ו\"ק. ואח\"כ בחי' מוחין ממש הוא על דרך משל השכל שבפ\"ע כמו הלומד חכמה ונק' חב\"ד דאצילות כו':"],[93,"<b>וזהו<\/b> ענין המצות שקיים אברהם. היינו שהמשיך אוא\"ס בז\"א כי ⟦סח,ד⟧אברהם הוא בחי' אבר מה ע\"ש היותו יסוד אבא שבז\"א השכל של המדה כנ\"ל וממשיך אורות בכלים שמתחלה עד שלא נברא העולם היה הוא ושמו בלבד. ועתה נתחלק לז' שמות כו' חסד כו'. (פי' כי הז' שמות הם בחי' אורות של הז' מדות היינו בחי' האור א\"ס המתלבש בכלי החסד נק' אל כמ\"ש חסד אל כל היום ואור המתלבש בגבורה נק' אלקים כו' ולכן הם ז' שמות משא\"כ קודם שנברא העולם ולא היה עדיין אצילות המדות היה בחי' האור א\"ס כמו שהוא למעלה מבחי' התלבשות בכלים והוא ענין היה הוא ושמו בלבד) והיינו בבחי' גמ\"ח ממשיך האור במל' בת היתה לאברהם ובכל שמה. וע\"כ אמר אדנ\"י אל נא תעבור כו' ומעולם לא קראו להקב\"ה אור א\"ס אדון שיומשך במלכות אלא אברהם כו'. ואמנם כל המשכות אלו דאברהם הי' נשאר באצילות היינו גידול רמ\"ח אברי ז\"א ע\"י מוחין דיניקה כנ\"ל. אבל כדי שיומשך בבי\"ע הוא ע\"י משה שהוא מבחי' ח\"ס שבכתר דא\"א אלא שנשפל ביסוד אבא והורד שמה ולהיותו גבוה יושפל יותר למטה. כענין שכתוב ועברתי בארץ מצרים אני ולא מלאך כו'. וכמ\"ש באדרא רבא (ד' קל\"ב ע\"א) בענין תלת עלמין דנפיק מתקונא קדמאה כו'. שהתלת עלמין הם ג' עולמות בי\"ע והם נמשכים מהתקון הראשון מי\"ג ת\"ד דא\"א דאצי' שהוא בחי' מי אל כמוך כו'. וזה פליאה לכאורה איך יהיה דילוג המדרגה מבחי' י\"ג ת\"ד דא\"א שהיא מקור האצי' שיומשך מזה ג' עולמות בי\"ע. אך הענין הוא משום דאדרבה כי כדי שיבא האור עד למטה כ\"כ בעולמות בי\"ע צריך שיבא ממקום הנעלה ביותר כי לעוצם הרוממות יוכל להשפיל א\"ע למטה יותר כו'."],[93,"ולכן שיהיה התהוות עולמות בי\"ע שהוא דוקא ע\"י המשכה מתיקון הראשון די\"ג ת\"ד. וזהו פי' מי אל כמוך שיוכל לישפל א\"ע כ\"כ למטה מטה כו'. ועד\"ז יובן ג\"כ בהמשכת האור ע\"י התומ\"צ בעולמות בי\"ע שהוא ע\"י משה דייקא להיותו ממקום גבוה יותר משרש בחינת אברהם. ע\"כ יכול להמשיך האור למטה ביותר גם בבי\"ע משא\"כ המשכות אברהם היו רק באצילות:"],[93,"<b>וזהו<\/b> כי אל דעות הוי'. ופי' ב' דעות הן יחו\"ע ויחו\"ת. יחו\"ע מלמעלה למטה כולא קמיה כלא ולמעלה היש כו'. ויחו\"ת הוא בהפך היינו יש מאין שלמטה היש. ובשם זה שם אל הוא בחי' תקון הראשון מי\"ג ת\"ד כולל הב' דעות."],[93,"והוא כמ\"ש היוצר יחד לבם המבין אל כל מעשיהם. בוחן כליות. וע\"כ משם נמשך הכח שיהיה הגלוי גם למטה להיות שוים פי' שלא יסתיר בחי' יחודא תתאה הדעה שממטה למעלה על בחי' גלוי דעה עליונה ויהיה הגלוי למטה כמו למעלה. וז\"ש והאלקים יעננו פי' אלקים הוא בחי' המסתיר להיות נראה למטה היש כו' והוא בחי' יחו\"ת יעננו למטה כפי שנמשך אליו בקולו של משה מלמעלה למטה וע\"ז ארז\"ל יושב ושונה כנגדו ממש:"]]);
